INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推动", "is_correct": true, "explanation": "“推动”表示促使事情完成，符合“好朋友……我完成了这件事”的语境。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开或拆除，不能表示促使别人完成事情。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，与句意完全无关。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”带的一般是具体物体，不能用来带人作宾语。"}], "explanations": {"推动": "“推动”表示促使事情完成，符合“好朋友……我完成了这件事”的语境。", "拆": "语义：“拆”指拆开或拆除，不能表示促使别人完成事情。", "烤": "语义：“烤”是加热食物，与句意完全无关。", "砸": "搭配：“砸”带的一般是具体物体，不能用来带人作宾语。"}, "sentence_index": 6, "correct_answer": "推动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "起义军推动了暴君。", "explanation": "这里应该用〈推翻〉。“推动”表示促使事情前进，不能表示打倒统治者，打倒暴君要说“推翻”。"}, {"text": "他在街上推动牛奶。", "explanation": "这里应该用〈推销〉。“推动”不能表示推销商品，推销牛奶要说“推销”。"}, {"text": "他总是推动责任，不肯承认错误。", "explanation": "这里应该用〈推卸〉。“推动”不能表示把责任推给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们昨天用力推动了着那辆大车。", "corrected_sentence": "工人们昨天用力推动了那辆大车。", "error_description": "错误：“了”和“着”不能同时用在“推动”后面。应说“工人们昨天用力推动了那辆大车”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府推动了着这项改革。", "corrected_sentence": "市政府推动了这项改革。", "error_description": "错误：“了”和“着”不能同时用在“推动”后面。应说“市政府推动了这项改革”，去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
