INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们说话或写东西时用来表达意思的字和词。", "primary_collocate": null, "pronunciation": "yǔ yán", "ipa": "y˨˩˦ iɛn˧˥", "syllable_count": 2, "sentences": [{"text": "世界上有几千种语言。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会说几种语言？", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学一门新语言需要很多时间。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言不同，我们只能用手说话。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很喜欢语言，会说四种话。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中文是一种很有意思的语言。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学语言比大人快。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都有自己的语言。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学校学了两门语言，英语和法语。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的语言很简单，我看得懂。", "target_word": "语言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "门", "label": "量词"}, {"form": "语言学", "label": "复合"}], "register": "中性", "sense_fingerprint": "语言：人们表达意思用的字和词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语言", "is_correct": true, "explanation": "正确：“语言”可以用“种”计数，“几千种语言”指世界上各种语言。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不能按“种”计数，“几千种年龄”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的重量，不能分成“几千种”，与语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“种”用于可以分类的事物，不能修饰“身高”这种度量。"}], "explanations": {"语言": "正确：“语言”可以用“种”计数，“几千种语言”指世界上各种语言。", "年龄": "语义：年龄是人的岁数，不能按“种”计数，“几千种年龄”不成立。", "体重": "语义：体重是人的重量，不能分成“几千种”，与语境不符。", "身高": "搭配：“种”用于可以分类的事物，不能修饰“身高”这种度量。"}, "sentence_index": 0, "correct_answer": "语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个语言的时间是三点。", "explanation": "这里应该用〈会议〉。“语言”指语言系统，不能像会议那样有开始的时间。"}, {"text": "他的语言很大，大家都听见了。", "explanation": "这里应该用〈声音〉。“语言”不指说话的声音大小，说声音大要用“声音”。"}, {"text": "这辆车的语言很快。", "explanation": "这里应该用〈速度〉。“语言”不能描述车的快慢，形容快慢要说“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语言", "is_correct": true, "explanation": "正确：“学语言”是学习语言的常见说法，孩子在这方面比大人快。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“学”的对象是知识或技能，房子不能作为学习的对象。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“学”不与“空气”搭配，学习的对象通常是语言、知识或技能。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为学习的对象。"}], "explanations": {"语言": "正确：“学语言”是学习语言的常见说法，孩子在这方面比大人快。", "房子": "语义：“学”的对象是知识或技能，房子不能作为学习的对象。", "空气": "搭配：“学”不与“空气”搭配，学习的对象通常是语言、知识或技能。", "天气": "语义：天气是自然现象，不能作为学习的对象。"}, "sentence_index": 6, "correct_answer": "语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的语言很大。", "explanation": "这里应该用〈字〉。书上字的大小不能用“语言”来形容。"}, {"text": "他讲了很长的语言。", "explanation": "这里应该用〈话〉。“语言”指语言系统，不指说话的长短，说话多少要用“话”。"}, {"text": "他买了一斤很便宜的语言。", "explanation": "这里应该用〈苹果〉。“语言”是表达意思的系统，不能用斤两称量或买卖；买水果要说“苹果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世界上有很多语言们。", "corrected_sentence": "世界上有很多语言。", "error_description": "错误：“语言”后多加了“们”。正确：“们”只用于指人的复数，“语言”不加“们”，应说“很多语言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会说三本语言。", "corrected_sentence": "他会说三种语言。", "error_description": "错误：“语言”前用了量词“本”。正确：“本”用于书，“语言”用“种”或“门”计量，应说“三种语言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
