INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20954, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一种样子变成另一种样子。", "primary_collocate": null, "pronunciation": "zhuǎn xíng", "ipa": "tʂwan˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家老工厂今年开始转型。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从老师转型成了作家。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想转型做网上生意。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市正在转型，新工作越来越多。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "转型不容易，需要时间。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店转型以后，客人多了。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经转型过一次了。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村也在转型，很多人用手机卖菜。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店没有转型，所以关门了。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济转型需要新的技术。", "target_word": "转型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转型了", "label": "体标"}, {"form": "转型过", "label": "体标"}, {"form": "转型期", "label": "复合"}], "register": "中性", "sense_fingerprint": "从一种模式或样子变成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转型", "is_correct": true, "explanation": "转型：从一种模式或样子变成另一种，即本词。"}, {"text": "转醒", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同（第三声与第二声），意思是从昏迷或睡梦中醒过来。"}, {"text": "转性", "is_correct": false, "explanation": "xìng 与 xíng 声调不同（第四声与第二声），意思是改掉原来的习性。"}, {"text": "转向", "is_correct": false, "explanation": "xiàng 与 xíng 读音相近，但韵母和声调都不同，意思是改变方向。"}], "explanations": {"转型": "转型：从一种模式或样子变成另一种，即本词。", "转醒": "xǐng 与 xíng 声调不同（第三声与第二声），意思是从昏迷或睡梦中醒过来。", "转性": "xìng 与 xíng 声调不同（第四声与第二声），意思是改掉原来的习性。", "转向": "xiàng 与 xíng 读音相近，但韵母和声调都不同，意思是改变方向。"}, "sentence_index": null, "correct_answer": "转型"}, "level_3": {"options": [{"text": "发烧", "is_correct": false, "explanation": "语义：工厂不会发烧，“发烧”只用于人或动物的身体状况，不能用于“老工厂”。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：工厂不能结婚，结婚的主语只能是人。"}, {"text": "转型", "is_correct": true, "explanation": "转型：从一种模式或样子变成另一种，与“老工厂”和“今年开始”搭配自然。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：工厂不睡觉，“睡觉”的主体不能是机器或企业。"}], "explanations": {"发烧": "语义：工厂不会发烧，“发烧”只用于人或动物的身体状况，不能用于“老工厂”。", "结婚": "语义：工厂不能结婚，结婚的主语只能是人。", "转型": "转型：从一种模式或样子变成另一种，与“老工厂”和“今年开始”搭配自然。", "睡觉": "语义：工厂不睡觉，“睡觉”的主体不能是机器或企业。"}, "sentence_index": 0, "correct_answer": "转型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气忽然转型，下了一场大雨。", "explanation": "这里应该用〈变化〉。转型指产业、经济等整体模式的根本转变，天气的变化不说转型。"}, {"text": "这个软件可以把英文转型成中文。", "explanation": "这里应该用〈转换〉。转换用于语言、格式等的互相变换，转型强调整体模式的变化。"}, {"text": "病人的情况明显转型了。", "explanation": "这里应该用〈改善〉。转型指根本模式的转变，身体或状况的好转用改善。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”只说金属物件，不能用于“他们”。"}, {"text": "转型", "is_correct": true, "explanation": "转型：指整体模式的根本转变，“转型过一次”表示经历过一次这样的变化。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化只用于冰雪等物质，不能用于人。"}, {"text": "报废", "is_correct": false, "explanation": "搭配：“报废”说物品失去使用价值，不用于人。"}], "explanations": {"生锈": "语义：“生锈”只说金属物件，不能用于“他们”。", "转型": "转型：指整体模式的根本转变，“转型过一次”表示经历过一次这样的变化。", "融化": "语义：融化只用于冰雪等物质，不能用于人。", "报废": "搭配：“报废”说物品失去使用价值，不用于人。"}, "sentence_index": 6, "correct_answer": "转型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家具位置稍微转型以后，房间看起来宽敞多了。", "explanation": "这里应该用〈调整〉。转型指整体模式的根本转变，家具位置的小幅改动只说调整。"}, {"text": "电池转型以后，手机能用一整天了。", "explanation": "这里应该用〈更换〉。转型指模式或产业的根本变化，换一块电池只说更换。"}, {"text": "文章的结尾转型以后，整篇读起来顺多了。", "explanation": "这里应该用〈修改〉。转型强调整体模式的根本转变，改写结尾这类局部改动用修改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把传统业务转型了为网上服务。", "corrected_sentence": "公司把传统业务转型为网上服务。", "error_description": "体标错误：“转型为”中间不能加“了”，“了”不能插在“转型”和“为”之间。正确：“公司把传统业务转型为网上服务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店已经转型了过两次。", "corrected_sentence": "这家书店已经转型过两次。", "error_description": "体标错误：“转型过”表示经历过，“了”不能插在“转型”和“过”之间。正确说法是“这家书店已经转型过两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
