INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情发生或出现。", "primary_collocate": null, "pronunciation": "cuī shēng", "ipa": "tsʰweɪ̯˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "网络购物催生了快递行业。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术催生了许多新工作。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛催生了一批年轻球星。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的发展催生了更多的住房需求。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的出现催生了短视频。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好奇心催生了许多伟大的发明。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情催生了在线学习的热潮。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游热催生了很多小饭馆。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一句话催生了他写书的想法。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的需要催生了这家新书店。", "target_word": "催生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "催生了", "label": "完成体"}, {"form": "催生过", "label": "经历体"}, {"form": "催生出", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "催生：促使新事物出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "催生", "is_correct": true, "explanation": "正确。“催生”表示促使新事物出现，符合网络购物带来快递行业的语境。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”表示破坏，与快递行业兴起的语境相反，句子不合逻辑。"}, {"text": "扼杀", "is_correct": false, "explanation": "语义：“扼杀”指压制使之无法存在，用于快递行业与语境不符。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促”指催人快做，只用于人的行动，不能用于“快递行业”这样的事物。"}], "explanations": {"催生": "正确。“催生”表示促使新事物出现，符合网络购物带来快递行业的语境。", "摧毁": "语义：“摧毁”表示破坏，与快递行业兴起的语境相反，句子不合逻辑。", "扼杀": "语义：“扼杀”指压制使之无法存在，用于快递行业与语境不符。", "催促": "语义：“催促”指催人快做，只用于人的行动，不能用于“快递行业”这样的事物。"}, "sentence_index": 0, "correct_answer": "催生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈一直催生我赶快写作业。", "explanation": "这里应该用〈催促〉。催生指使新事物出现，催人快做事要用催促，不能用催生。"}, {"text": "这对夫妇催生了三个孩子。", "explanation": "这里应该用〈生育〉。催生指使新事物出现，医学上的催产只指促使一次分娩，说夫妇生养多个孩子要用生育。"}, {"text": "一阵哭声催生了正在睡觉的他。", "explanation": "这里应该用〈吵醒〉。催生指使新事物出现，使人醒来要用吵醒，不能用催生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "催生", "is_correct": true, "explanation": "正确。“催生”表示促使新事物出现，与疫情后在线学习热潮兴起的语境相合。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：“消灭”指彻底除去，与在线学习热潮兴起的语境相反。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”用于修好坏了的东西，不能说“修理了热潮”。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”是不及物动词，不能带“热潮”作宾语，句子不通。"}], "explanations": {"催生": "正确。“催生”表示促使新事物出现，与疫情后在线学习热潮兴起的语境相合。", "消灭": "语义：“消灭”指彻底除去，与在线学习热潮兴起的语境相反。", "修理": "语义：“修理”用于修好坏了的东西，不能说“修理了热潮”。", "发生": "配价：“发生”是不及物动词，不能带“热潮”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "催生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公园里催生了一个新朋友。", "explanation": "这里应该用〈结交〉。催生指使行业、需求等新事物出现，不能用来说交到朋友，交朋友要说结交。"}, {"text": "这位母亲催生了一桌好菜。", "explanation": "这里应该用〈做〉。催生指使新事物出现，做菜要用〈做〉，不能说催生一桌菜。"}, {"text": "老师催生了一道数学题。", "explanation": "这里应该用〈出〉。催生指使新事物出现，出题要用〈出〉，不说催生一道题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新药的研发催生了出一批新公司。", "corrected_sentence": "新药的研发催生出了一批新公司。", "error_description": "补语与体标顺序错误：趋向补语“出”应紧跟“催生”之后，体标“了”放在补语之后，说“催生出了”，不能说“催生了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项创新催生了了一个新的行业。", "corrected_sentence": "这项创新催生了一个新的行业。", "error_description": "体标重复错误：“催生”之后只用一个“了”，说“催生了一个”，不能说“催生了了一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反对：与“认同”（觉得别人说的对）相反，表示不赞成别人的看法，是这一义项的反义词。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏：表示喜爱、赞赏，不是认同的反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：指大家交换意见，与认同不构成反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考：指动脑筋想问题，与认同不构成反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "反对：与“认同”（觉得别人说的对）相反，表示不赞成别人的看法，是这一义项的反义词。", "欣赏": "欣赏：表示喜爱、赞赏，不是认同的反义词。", "讨论": "讨论：指大家交换意见，与认同不构成反义关系。", "思考": "思考：指动脑筋想问题，与认同不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反对：与“认同”（觉得别人说的对）相反，表示不赞成别人的看法，是这一义项的反义词。"}, {"text": "赞叹", "is_correct": false, "explanation": "赞叹：表示赞美、佩服，不是认同的反义词。"}, {"text": "嘲笑", "is_correct": false, "explanation": "嘲笑：用言语讥笑别人，与认同不构成反义关系。"}, {"text": "讨好", "is_correct": false, "explanation": "讨好：迎合别人以求喜欢，与认同不构成反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "反对：与“认同”（觉得别人说的对）相反，表示不赞成别人的看法，是这一义项的反义词。", "赞叹": "赞叹：表示赞美、佩服，不是认同的反义词。", "嘲笑": "嘲笑：用言语讥笑别人，与认同不构成反义关系。", "讨好": "讨好：迎合别人以求喜欢，与认同不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得别人说的对。", "primary_collocate": null, "pronunciation": "rèn tóng", "ipa": "ʐən˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我认同你说的话。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认同他的意见。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得对，我完全认同。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法，我不太认同。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认同我的看法吗？", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈认同了我的决定。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都认同这个办法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很有道理，大家都认同。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，我们都认同小李的做法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前认同过这种想法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认同了", "label": "体标（了）"}, {"form": "认同过", "label": "体标（过）"}, {"form": "认同感", "label": "复合词"}], "register": "中性", "sense_fingerprint": "觉得别人说的对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dab81e9-4fc4-4e85-8310-7a60964d0d47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认同", "is_correct": true, "explanation": "正确：“认同”表示赞成对方的看法，与“你说的话”搭配。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指用力使东西裂开，话不能被撕。"}, {"text": "捡", "is_correct": false, "explanation": "搭配：“捡”用于拾取具体的东西，不能说捡别人说的话。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃别人说的话。"}], "explanations": {"认同": "正确：“认同”表示赞成对方的看法，与“你说的话”搭配。", "撕": "语义：“撕”指用力使东西裂开，话不能被撕。", "捡": "搭配：“捡”用于拾取具体的东西，不能说捡别人说的话。", "吃": "搭配：“吃”的对象是食物，不能说吃别人说的话。"}, "sentence_index": 0, "correct_answer": "认同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于认同了自己犯下的错误。", "explanation": "这里应该用〈承认〉。认同指对看法、想法表示赞同；承认错误这类事实要用承认。"}, {"text": "我认同你的申请，马上帮你办。", "explanation": "这里应该用〈同意〉。认同用于对看法的赞同，对申请、请求表示答应要用同意。"}, {"text": "学校认同了他的学历。", "explanation": "这里应该用〈认可〉。认同指赞同看法，学历、资格的正式承认要用认可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认同", "is_correct": true, "explanation": "正确：“认同”表示大家都赞成这个办法，与“同学们都”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，办法不能喝。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱这个办法。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，这个办法不是可以用脚踢的东西。"}], "explanations": {"认同": "正确：“认同”表示大家都赞成这个办法，与“同学们都”搭配。", "喝": "搭配：“喝”的对象是饮品，办法不能喝。", "唱": "搭配：“唱”的对象是歌曲，不能说唱这个办法。", "踢": "语义：“踢”指用脚击打，这个办法不是可以用脚踢的东西。"}, "sentence_index": 6, "correct_answer": "认同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很认同他的不幸。", "explanation": "这里应该用〈同情〉。认同指赞同看法或身份认同，对别人遭遇的怜悯要用同情。"}, {"text": "他认同了这个邀请，下周就来。", "explanation": "这里应该用〈接受〉。认同用于对看法的赞同，邀请、礼物等要用接受。"}, {"text": "他一眼就认同了老朋友。", "explanation": "这里应该用〈认出〉。认同指赞同看法或身份上的认同，辨认人的面貌要用认出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不认同得你的做法。", "corrected_sentence": "我不认同你的做法。", "error_description": "错误：“认同”后不带补语“得”，应说“我不认同你的做法”，不说“我不认同得你的做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她以前认同了过这个观点。", "corrected_sentence": "她以前认同过这个观点。", "error_description": "错误：动词“认同”后已有表示经历的“过”，又加了“了”，形成“认同了过”，两个体标不能同时用。应为“认同过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
