INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱化", "is_correct": true, "explanation": "与“强化”构成反义，指使变弱。"}, {"text": "唤醒", "is_correct": false, "explanation": "语义：“唤醒”指叫醒或激发，不是“强化”的反义词。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使燃烧，不是“强化”的反义词。"}, {"text": "消毒", "is_correct": false, "explanation": "语义：“消毒”指杀灭细菌，与“强化”不构成反义。"}], "correct_answer": "弱化", "explanations": {"弱化": "与“强化”构成反义，指使变弱。", "唤醒": "语义：“唤醒”指叫醒或激发，不是“强化”的反义词。", "点燃": "语义：“点燃”指使燃烧，不是“强化”的反义词。", "消毒": "语义：“消毒”指杀灭细菌，与“强化”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某样东西变得更强。", "primary_collocate": null, "pronunciation": "qiáng huà", "ipa": "tɕʰiɑŋ˧˥ xuɑ˥˩", "syllable_count": 2, "sentences": [{"text": "老师经常考试，是为了强化学生的记忆。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开会，是想强化大家的安全意识。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多听几遍，可以强化你对新词的印象。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定强化对新员工的管理。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让队员每天多练，来强化基本功。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司想进一步强化合作关系。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校强化了对考试纪律的要求。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了强化自律能力，他每天坚持锻炼。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动强化了同学们的团队意识。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了强化环保意识，学校开了一节课。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强化了", "label": "体标"}, {"form": "强化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使记忆、意识、管理、关系等抽象事物变得更强更牢固", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b1c088-848e-452e-a53e-0280728c0626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强化", "is_correct": true, "explanation": "正确：“强化”表示使记忆更牢固，与句中的目的一致。"}, {"text": "弱化", "is_correct": false, "explanation": "语义：“弱化”指减弱，与“为了……强化记忆”的目的相反。"}, {"text": "消化", "is_correct": false, "explanation": "搭配：“消化”多接食物或知识，不说消化学生的记忆。"}, {"text": "美化", "is_correct": false, "explanation": "语义：“美化”指使事物变美观，与记忆无关。"}], "explanations": {"强化": "正确：“强化”表示使记忆更牢固，与句中的目的一致。", "弱化": "语义：“弱化”指减弱，与“为了……强化记忆”的目的相反。", "消化": "搭配：“消化”多接食物或知识，不说消化学生的记忆。", "美化": "语义：“美化”指使事物变美观，与记忆无关。"}, "sentence_index": 0, "correct_answer": "强化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目要强化进度。", "explanation": "这里应该用〈加快〉。说进度快慢要用“加快”，“强化”指使能力、意识等变得更牢固，不用来说速度。"}, {"text": "天气冷了，我想强化一下衣服。", "explanation": "这里应该用〈多穿〉。“强化”用于记忆、意识、管理等抽象事物，不能用于穿衣服。"}, {"text": "他的体重强化了三公斤。", "explanation": "这里应该用“增加”。强化只用于抽象的能力、意识、管理，体重这类数量要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强化", "is_correct": true, "explanation": "正确：“强化”表示使要求更严格，与学校对考试纪律的做法一致。"}, {"text": "唤醒", "is_correct": false, "explanation": "语义：“唤醒”指叫醒或激发，不能用于要求。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使燃烧，与纪律要求的句意不符。"}, {"text": "消毒", "is_correct": false, "explanation": "搭配：“消毒”接对象一般是物体或环境，不说消毒要求。"}], "explanations": {"强化": "正确：“强化”表示使要求更严格，与学校对考试纪律的做法一致。", "唤醒": "语义：“唤醒”指叫醒或激发，不能用于要求。", "点燃": "语义：“点燃”指使燃烧，与纪律要求的句意不符。", "消毒": "搭配：“消毒”接对象一般是物体或环境，不说消毒要求。"}, "sentence_index": 6, "correct_answer": "强化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间要强化噪音。", "explanation": "这里应该用〈降低〉。噪音要“降低”，“强化”表示让事物变得更强，不能用于噪音。"}, {"text": "这次工作强化了他的负担。", "explanation": "这里应该用〈减轻〉。负担要“减轻”，“强化”表示让事物变得更强，不能用于负担。"}, {"text": "周末我想强化一下心情。", "explanation": "这里应该用〈放松〉。心情要“放松”，“强化”不能用于心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训是为了强化了员工的服务意识。", "corrected_sentence": "这次培训是为了强化员工的服务意识。", "error_description": "错误形式：“强化了”。正确形式：“强化”。“为了”引出目的，后面的动词不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛强化了过队员们的信心。", "corrected_sentence": "这次比赛强化了队员们的信心。", "error_description": "错误形式：“强化了过”。正确形式：“强化了”。体标“了”和“过”不能连用，这里只用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
