INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让东西变得一样，大家都按一个规矩来。", "primary_collocate": null, "pronunciation": "guī fàn huà", "ipa": "kwei˥ fan˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "交通规范化后，大家都按规则走。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想让考试规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单的规范化让客人看得更清楚。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了工作流程的规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地名的写法需要规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在做表格的规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾分类的规范化很重要。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规范化可以减少错误。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求作业格式规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先做价格的规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "規範化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "让东西一样，大家按同一个规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e84b5b62-f832-4dbb-bc2a-7fd6d14aeece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规范化", "is_correct": true, "explanation": "正确：指交通统一规则，与“大家都按规则走”一致。"}, {"text": "多样化", "is_correct": false, "explanation": "语义：“多样化”与“大家都按规则走”的统一要求相反，句意矛盾。"}, {"text": "无序化", "is_correct": false, "explanation": "语义：“无序化”与“大家都按规则走”矛盾，句意不通。"}, {"text": "美化", "is_correct": false, "explanation": "搭配：“美化”多指环境或城市面貌，不能说“交通美化”。"}], "explanations": {"规范化": "正确：指交通统一规则，与“大家都按规则走”一致。", "多样化": "语义：“多样化”与“大家都按规则走”的统一要求相反，句意矛盾。", "无序化": "语义：“无序化”与“大家都按规则走”矛盾，句意不通。", "美化": "搭配：“美化”多指环境或城市面貌，不能说“交通美化”。"}, "sentence_index": 0, "correct_answer": "规范化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街道去年被规范化了，种了很多树。", "explanation": "这里应该用〈绿化〉。规范化指统一标准，不指种树增加绿色。"}, {"text": "妈妈每天都要给我规范化一次头发。", "explanation": "这里应该用〈梳〉。规范化指使事物统一标准，不指梳理头发。"}, {"text": "他是个规范化的孩子，很爱开玩笑。", "explanation": "这里应该用〈听话〉。规范化指使事物变得一样、按统一规矩来，不用来形容孩子的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规范化", "is_correct": true, "explanation": "正确：指垃圾分类统一标准、按规矩执行，与“很重要”搭配。"}, {"text": "娱乐化", "is_correct": false, "explanation": "语义：“娱乐化”指变得好玩、像娱乐，与垃圾分类要统一规矩的意思不符。"}, {"text": "复杂化", "is_correct": false, "explanation": "语义：“复杂化”会使分类更麻烦，不能说它本身“很重要”。"}, {"text": "口语化", "is_correct": false, "explanation": "语义：“口语化”指语言变得像说话，与垃圾分类无关。"}], "explanations": {"规范化": "正确：指垃圾分类统一标准、按规矩执行，与“很重要”搭配。", "娱乐化": "语义：“娱乐化”指变得好玩、像娱乐，与垃圾分类要统一规矩的意思不符。", "复杂化": "语义：“复杂化”会使分类更麻烦，不能说它本身“很重要”。", "口语化": "语义：“口语化”指语言变得像说话，与垃圾分类无关。"}, "sentence_index": 6, "correct_answer": "规范化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们先去公园规范化。", "explanation": "这里应该用〈散步〉。规范化指使事物变得一样、按统一规矩来，不指在公园里走动。"}, {"text": "他把这间屋子规范化成了一幅画。", "explanation": "这里应该用〈布置〉。规范化指使事物统一标准，不指把屋子变成画。"}, {"text": "这场雨把我们的心情规范化了。", "explanation": "这里应该用〈平复〉。规范化指使事物变得一样、按统一规矩来，不指心情的起伏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院已经把看病流程规范化着。", "corrected_sentence": "医院已经把看病流程规范化了。", "error_description": "“已经”表示动作已完成，要用“了”，不能用表示持续的“着”：应说“规范化了”，不说“规范化着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师正在规范化了作业格式。", "corrected_sentence": "老师正在规范化作业格式。", "error_description": "“正在”表示动作进行中，与表示完成的“了”不能同用；错误句“正在规范化了作业格式”应删去“了”，改为“正在规范化作业格式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
