INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一定范围的地区，通常指比一个地方更大的区域。", "primary_collocate": null, "pronunciation": "dì yù", "ipa": "ti⁵¹ y⁵¹", "syllable_count": 2, "sentences": [{"text": "不同地域的人，口音也不一样。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国很大，各个地域的天气不同。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地域冬天很冷，夏天很热。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己生活的地域很熟悉。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南北两个地域的饮食习惯不一样。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地域的人喜欢吃辣的菜。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地域不同，节日的习俗也不同。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了各个地域的文化。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的客人来自不同的地域。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地域很大，可是人很少。", "target_word": "地域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地域性", "label": "复合"}], "register": "中性", "sense_fingerprint": "有一定范围的地方、区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不决定人的口音，“不同天气的人，口音也不一样”与句意不符。"}, {"text": "地域", "is_correct": true, "explanation": "正确：地域指一定范围的地区，不同地域的人口音自然不同。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：字体是文字的样式，不用来区分人，不能说“不同字体的人”。"}, {"text": "体形", "is_correct": false, "explanation": "体貌：体形与口音无关，“不同体形的人，口音也不一样”说不通。"}], "explanations": {"天气": "语义：天气不决定人的口音，“不同天气的人，口音也不一样”与句意不符。", "地域": "正确：地域指一定范围的地区，不同地域的人口音自然不同。", "字体": "搭配：字体是文字的样式，不用来区分人，不能说“不同字体的人”。", "体形": "体貌：体形与口音无关，“不同体形的人，口音也不一样”说不通。"}, "sentence_index": 0, "correct_answer": "地域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的地域很大，可以坐五十个人。", "explanation": "这里应该用〈空间〉。地域指较大的地理区域，一间教室内部的范围要用空间。"}, {"text": "我想找一个安静的地域读书。", "explanation": "这里应该用〈地方〉。地域指较大范围的区域，不指可以读书的具体地点。"}, {"text": "这次会议的地域定在了图书馆。", "explanation": "这里应该用〈地点〉。地域指大范围的区域，会议具体在哪里举行要用地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色与节日习俗没有关系，“颜色不同，节日的习俗也不同”无法成立。"}, {"text": "地域", "is_correct": true, "explanation": "正确：地域指一定范围的地区，地域不同，节日习俗也就不同。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重不能决定习俗，“体重不同”与后半句搭不上。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格高低不影响节日习俗，这个说法不通。"}], "explanations": {"颜色": "语义：颜色与节日习俗没有关系，“颜色不同，节日的习俗也不同”无法成立。", "地域": "正确：地域指一定范围的地区，地域不同，节日习俗也就不同。", "体重": "体貌：体重不能决定习俗，“体重不同”与后半句搭不上。", "价格": "语义：价格高低不影响节日习俗，这个说法不通。"}, "sentence_index": 6, "correct_answer": "地域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在音乐地域很有名。", "explanation": "这里应该用〈领域〉。领域指某一专业或活动的范围，地域指地理上的大片地区，音乐方面要用领域。"}, {"text": "这所学校是一个学习的地域。", "explanation": "这里应该用〈场所〉。地域指较大的区域，学校这类具体的学习场所要用场所。"}, {"text": "我们在这个地域踢了一场足球。", "explanation": "这里应该用〈场地〉。地域指大范围的区域，踢球的具体场所要用场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一片地域们的人很热情。", "corrected_sentence": "这一片地域的人很热情。", "error_description": "错误在“地域”后面加了“们”。“们”只用于指人的名词，“地域”是地方，应说“这一片地域的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这个地域工作了十年。", "corrected_sentence": "他在这个地域工作了十年。", "error_description": "漏掉了地点介词“在”：“在”加“地域”作地点状语，应说“在这个地域工作”，不能省略“在”说“这个地域工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
