INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久以前，一些人觉得教会做的事情不对，就想要改变它，这叫做宗教改革。", "primary_collocate": null, "pronunciation": "zōng jiào gǎi gé", "ipa": "tsʊŋ˥˥ tɕjɑʊ̯˥˩ kai̯˨˩˦ kɤ˧˥", "syllable_count": 4, "sentences": [{"text": "宗教改革是欧洲很久以前的大事。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，宗教改革改变了教会。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人觉得教会不对，就开始了宗教改革。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读到了关于宗教改革的内容。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革以后，出现了新教。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事和宗教改革有关。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对宗教改革很有兴趣。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学了宗教改革。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革发生在很久以前。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革让很多人有了新想法。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宗教改革运动", "label": "复合"}], "register": "中性", "sense_fingerprint": "很久以前有人觉得教会不对而要改变教会的历史事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外卖", "is_correct": false, "explanation": "语义：外卖是近代以后才有的服务，与“很久以前”的时间矛盾。"}, {"text": "宗教改革", "is_correct": true, "explanation": "正确：指很久以前欧洲人反对教会、要求改变教会的历史事件，可以称为“大事”。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：八卦指闲话、传闻，不是可以称为“大事”的历史事件，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代产品，很久以前的欧洲并不存在，句子不通。"}], "explanations": {"外卖": "语义：外卖是近代以后才有的服务，与“很久以前”的时间矛盾。", "宗教改革": "正确：指很久以前欧洲人反对教会、要求改变教会的历史事件，可以称为“大事”。", "八卦": "语义：八卦指闲话、传闻，不是可以称为“大事”的历史事件，句子不通。", "手机": "语义：手机是现代产品，很久以前的欧洲并不存在，句子不通。"}, "sentence_index": 0, "correct_answer": "宗教改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书里读到了一只宗教改革。", "explanation": "这里应该用〈场〉。〈只〉用于动物，“宗教改革”这类运动要用〈场〉。"}, {"text": "我昨天吃了一顿宗教改革。", "explanation": "这里应该用〈饭〉。宗教改革是历史事件，不是食物，不能用“吃”。"}, {"text": "工厂今年进行了一场宗教改革。", "explanation": "这里应该用〈改革〉。宗教改革指对教会做法的变革，工厂的生产调整要用〈改革〉，不能用“宗教改革”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痛苦", "is_correct": false, "explanation": "语义：人一般不会对痛苦感兴趣，句子读起来自相矛盾。"}, {"text": "宗教改革", "is_correct": true, "explanation": "正确：历史事件可以成为人感兴趣的对象，与“很有兴趣”相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是值得感兴趣的对象，句子不通。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“对……有兴趣”后接学科、活动或事物，不搭配场所。"}], "explanations": {"痛苦": "语义：人一般不会对痛苦感兴趣，句子读起来自相矛盾。", "宗教改革": "正确：历史事件可以成为人感兴趣的对象，与“很有兴趣”相符。", "垃圾": "语义：垃圾不是值得感兴趣的对象，句子不通。", "厕所": "搭配：“对……有兴趣”后接学科、活动或事物，不搭配场所。"}, "sentence_index": 6, "correct_answer": "宗教改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很厉害，是宗教改革。", "explanation": "这里应该用〈宗教改革家〉。“宗教改革”是历史事件，不能直接当作人的身份。"}, {"text": "我今天去宗教改革买菜。", "explanation": "“宗教改革”是历史事件，不是地点，不能用“去”表示前往。"}, {"text": "妈妈在超市买了宗教改革。", "explanation": "“宗教改革”是历史事件，不是商品，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时候，欧洲发生了一只宗教改革。", "corrected_sentence": "那时候，欧洲发生了一场宗教改革。", "error_description": "错误：“一只宗教改革”，应为“一场宗教改革”。“只”用于动物，宗教改革应用量词“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们把宗教改革介绍很详细。", "corrected_sentence": "同学们把宗教改革介绍得很详细。", "error_description": "错误：补语“详细”前缺少“得”，应为“介绍得很详细”。动词与补语之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "喜欢想问题、有自己想法的人。", "primary_collocate": null, "pronunciation": "sī xiǎng jiā", "ipa": "sɿ˥ ɕjɑŋ˨˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "我弟弟是个小思想家，总爱问为什么。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱想问题，大家都叫她思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子像个小思想家，坐着想了一下午。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同桌是班里的思想家，什么事都有自己的看法。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他年纪小，已经是个思想家了。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着说我是家里的思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友是个思想家，遇到事总要先想一想。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她像个思想家一样，对每件事都有自己的想法。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不爱说话，却是我们班的思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做思想家很好，但也要多去外面玩。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "日常说法，指爱动脑筋、凡事有自己想法的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话、提问，不能指爱问为什么的孩子。"}, {"text": "思想家", "is_correct": true, "explanation": "“小思想家”口语指爱动脑筋、凡事有自己想法的孩子，与“总爱问为什么”一致。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：“总爱问为什么”要求有思考能力的人作主语，雨伞不能作施事。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，不能用“小思想家”指我弟弟。"}], "explanations": {"石头": "语义：石头不会说话、提问，不能指爱问为什么的孩子。", "思想家": "“小思想家”口语指爱动脑筋、凡事有自己想法的孩子，与“总爱问为什么”一致。", "雨伞": "配价：“总爱问为什么”要求有思考能力的人作主语，雨伞不能作施事。", "大象": "语义：大象是动物，不能用“小思想家”指我弟弟。"}, "sentence_index": 0, "correct_answer": "思想家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我同桌是班里的思想家，每次开车送我上学。", "explanation": "用词错误：这里应该用〈司机〉。思想家指爱动脑筋、有自己看法的人，不指开车的人。"}, {"text": "我同桌是班里的思想家，什么事都不愿动脑子，总是照着别人抄。", "explanation": "义项矛盾：“思想家”指爱动脑筋的人，与“什么事都不愿动脑子”直接相反；这里应说〈懒虫〉。"}, {"text": "我同桌是班里的思想家，凡事都不拿主意，总是跟着别人走。", "explanation": "义项矛盾：“思想家”指有自己想法的人，与“凡事都不拿主意”直接相反；这里应说〈跟屁虫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会“遇到事先想一想”。"}, {"text": "思想家", "is_correct": true, "explanation": "“思想家”指爱动脑筋、有自己想法的人，与后句“遇到事总要先想一想”一致。"}, {"text": "闹钟", "is_correct": false, "explanation": "配价：“想一想”要求有思考能力的人作主语，闹钟不能作施事。"}, {"text": "懒虫", "is_correct": false, "explanation": "语义：“懒虫”指懒惰的人，与“遇到事总要先想一想”的意思相反。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不会“遇到事先想一想”。", "思想家": "“思想家”指爱动脑筋、有自己想法的人，与后句“遇到事总要先想一想”一致。", "闹钟": "配价：“想一想”要求有思考能力的人作主语，闹钟不能作施事。", "懒虫": "语义：“懒虫”指懒惰的人，与“遇到事总要先想一想”的意思相反。"}, "sentence_index": 6, "correct_answer": "思想家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗是个小思想家，总爱汪汪叫。", "explanation": "语义：“思想家”只用于指人，不能用于小狗；这里应说〈淘气〉。"}, {"text": "这几个小思想家从来不愿想问题，只顾着玩游戏。", "explanation": "义项矛盾：“思想家”指爱想问题的人，“从来不愿想问题”与之直接相反；这里应说〈小玩家〉。"}, {"text": "周末我们去思想家玩。", "explanation": "语义：“思想家”指人，不能作为去玩的地点；去玩的地方应说〈公园〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友是个真正得思想家，凡事都要先弄明白。", "corrected_sentence": "我的朋友是个真正的思想家，凡事都要先弄明白。", "error_description": "助词错误：修饰“思想家”的定语应用“的”，不能用“得”。“得”引出补语，“真正得思想家”说不通，应说“真正的思想家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹像只小思想家一样，坐在窗前想了很久。", "corrected_sentence": "妹妹像个小思想家一样，坐在窗前想了很久。", "error_description": "量词错误：“思想家”指人，应用“个”计量；“只”只用于动物或成对物品中的一个，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻碍", "is_correct": true, "explanation": "反义：“阻碍”与“促进”意思相反，指使事情受到阻挡。"}, {"text": "吃饭", "is_correct": false, "explanation": "无反义关系：“吃饭”指进食，与“促进”没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发出乐音，与“促进”没有对立关系。"}, {"text": "看书", "is_correct": false, "explanation": "无反义关系：“看书”指阅读，与“促进”没有对立关系。"}], "correct_answer": "阻碍", "explanations": {"阻碍": "反义：“阻碍”与“促进”意思相反，指使事情受到阻挡。", "吃饭": "无反义关系：“吃饭”指进食，与“促进”没有对立关系。", "唱歌": "无反义关系：“唱歌”指发出乐音，与“促进”没有对立关系。", "看书": "无反义关系：“看书”指阅读，与“促进”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻碍", "is_correct": true, "explanation": "反义：“阻碍”与“促进”意思相反，指使事情受到阻挡。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”指舞蹈动作，与“促进”没有对立关系。"}, {"text": "写字", "is_correct": false, "explanation": "无反义关系：“写字”指书写，与“促进”没有对立关系。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”指修复器物，与“促进”没有对立关系。"}], "correct_answer": "阻碍", "explanations": {"阻碍": "反义：“阻碍”与“促进”意思相反，指使事情受到阻挡。", "跳舞": "无反义关系：“跳舞”指舞蹈动作，与“促进”没有对立关系。", "写字": "无反义关系：“写字”指书写，与“促进”没有对立关系。", "修理": "无反义关系：“修理”指修复器物，与“促进”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情变得更好。", "primary_collocate": null, "pronunciation": "cù jìn", "ipa": "tsʰu⁵¹ tɕin⁵¹", "syllable_count": 2, "sentences": [{"text": "运动可以促进身体健康。", "target_word": "促进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次比赛促进了两国的交流。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多喝水能促进消化。", "target_word": "促进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的老师会促进学生进步。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司希望促进与外国的合作。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读书可以促进孩子的语言发展。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅游促进了这个小城的发展。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的鼓励促进了他的学习。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡得好能促进身体长高。", "target_word": "促进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该促进不同国家人民的了解。", "target_word": "促进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "促进了", "label": "体标"}, {"form": "促进着", "label": "体标"}, {"form": "促进过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：推动事物更快、更好地发展或进步", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促进", "is_correct": true, "explanation": "正确：“促进”表示推动，与“运动可以……身体健康”的语境相符。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”表示妨碍，“运动可以阻碍身体健康”与常识相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“身体健康”搭配作宾语，句子不通。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”要求带动词性宾语，不能直接带“身体健康”。"}], "explanations": {"促进": "正确：“促进”表示推动，与“运动可以……身体健康”的语境相符。", "阻碍": "语义：“阻碍”表示妨碍，“运动可以阻碍身体健康”与常识相反。", "吃": "搭配：“吃”不能与“身体健康”搭配作宾语，句子不通。", "进行": "配价：“进行”要求带动词性宾语，不能直接带“身体健康”。"}, "sentence_index": 0, "correct_answer": "促进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司的利润促进了一倍。", "explanation": "这里应该用〈增加〉。促进表示推动事情发展与进步，不能用于利润等数量的增加。"}, {"text": "他促进我解决了难题。", "explanation": "这里应该用〈帮助〉。促进表示推动发展，不能直接表示帮人做某件事。"}, {"text": "他用力促进了那扇门。", "explanation": "这里应该用〈推〉。促进用于抽象的发展或进步，不用于具体的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促进", "is_correct": true, "explanation": "正确：“促进了”表示推动，与“旅游……这个小城的发展”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出乐音，不能用于“发展”，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对器物，不能修理“发展”，句子不通。"}, {"text": "扮演", "is_correct": false, "explanation": "搭配：“扮演”后接角色，不能接“发展”作宾语。"}], "explanations": {"促进": "正确：“促进了”表示推动，与“旅游……这个小城的发展”的语境相符。", "唱": "语义：“唱”指发出乐音，不能用于“发展”，句子不通。", "修理": "语义：“修理”针对器物，不能修理“发展”，句子不通。", "扮演": "搭配：“扮演”后接角色，不能接“发展”作宾语。"}, "sentence_index": 6, "correct_answer": "促进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个药能促进感冒。", "explanation": "这里应该用〈治疗〉。促进表示推动好的发展，不能用于疾病，应说“治疗感冒”。"}, {"text": "他总是促进困难，不敢面对。", "explanation": "这里应该用〈逃避〉。促进表示积极推动，不能用于回避困难的意思。"}, {"text": "这场雨促进了比赛。", "explanation": "这里应该用〈破坏〉。促进表示推动发展，不能表示损害比赛，应说“这场雨破坏了比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策促进的了经济发展。", "corrected_sentence": "这项政策促进了经济发展。", "error_description": "错误：“促进的了”；正确：“促进了”。“促进”后不能直接接“的”，动态助词“了”应紧跟在“促进”后面，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动促进的大家的友谊。", "corrected_sentence": "这次活动促进了大家的友谊。", "error_description": "错误：“促进的大家的友谊”；正确：“促进了大家的友谊”。“促进”后应接动态助词“了”表示完成，这里的“的”应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
