INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "耳朵能听到的东西，比如小鸟叫或者音乐。", "primary_collocate": null, "pronunciation": "shēng yīn", "ipa": "ʂɤŋ˥ in˥", "syllable_count": 2, "sentences": [{"text": "我听见楼下有很大的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟的声音很好听，我每天早上都听。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请小声一点，我听不清老师的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话的声音很大，我们都听到了。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话里的声音很小，我听不清楚。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐的声音太大了，邻居来敲门。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里很安静，只能听到风的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在厨房里叫我，我听出了她的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我好像在哪里听过这个声音。", "target_word": "声音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外传来一阵奇怪的声音，孩子有点害怕。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "聲音", "label": "繁体"}], "register": "中性", "sense_fingerprint": "耳朵听到的声响，如人声、鸟叫、音乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“听见”只能跟声音等听觉对象搭配，不能听见颜色。"}, {"text": "声音", "is_correct": true, "explanation": "“声音”指耳朵能听见的响声，与“听见”搭配，是正确答案。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能用耳朵听见。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形，与“听见”搭配不当，也不能在楼下听见。"}], "explanations": {"颜色": "搭配：“听见”只能跟声音等听觉对象搭配，不能听见颜色。", "声音": "“声音”指耳朵能听见的响声，与“听见”搭配，是正确答案。", "味道": "语义：“味道”指气味或滋味，不能用耳朵听见。", "身材": "体貌：“身材”指体形，与“听见”搭配不当，也不能在楼下听见。"}, "sentence_index": 0, "correct_answer": "声音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话的声音很香。", "explanation": "〈香〉是形容气味的词，“声音”是耳朵听到的，不能用“香”来形容。"}, {"text": "他把这个声音咬了一口。", "explanation": "这里把“声音”误当成可以咬的实物。“声音”是耳朵听到的响声，没有形状，不能咬。"}, {"text": "他说话的声音很咸。", "explanation": "〈咸〉是味觉形容词，“声音”不能有咸淡，这里误用了味觉的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "搭配：“听到”只能跟声音等听觉对象搭配，不能听到“形状”。"}, {"text": "声音", "is_correct": true, "explanation": "“声音”指风吹过时发出的响声，夜里安静时能听到，是正确答案。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热，不是耳朵能听到的东西。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”要用手掂量或称，不能用“听到”。"}], "explanations": {"形状": "搭配：“听到”只能跟声音等听觉对象搭配，不能听到“形状”。", "声音": "“声音”指风吹过时发出的响声，夜里安静时能听到，是正确答案。", "温度": "语义：“温度”指冷热，不是耳朵能听到的东西。", "重量": "搭配：“重量”要用手掂量或称，不能用“听到”。"}, "sentence_index": 6, "correct_answer": "声音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个声音很便宜，花两块钱就能买到。", "explanation": "〈便宜〉是价钱的形容词，“声音”不能用价钱来形容，这里误把声音当成了商品。"}, {"text": "这首歌的声音很红。", "explanation": "〈红〉是颜色词，“声音”不是颜色，这里误用了颜色的说法。"}, {"text": "窗外的声音很胖，孩子有点害怕。", "explanation": "〈胖〉形容人或动物的体形，“声音”不能用“胖”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我听见楼下有一只很大的声音。", "corrected_sentence": "我听见楼下有一阵很大的声音。", "error_description": "“声音”的量词应用“阵”或“个”，不用“只”。“只”一般用于动物或成对的东西，所以“一只声音”错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里传来一阵很低声音。", "corrected_sentence": "夜里传来一阵很低的声音。", "error_description": "“很低”修饰“声音”时要加“的”，应说“很低的声音”，不能说“很低声音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
