INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个东西动，另一个跟着动。", "primary_collocate": null, "pronunciation": "gòng zhèn", "ipa": "kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上的杯子因共振而发出了声音。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吉他弦一响，另一把吉他就产生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车开过，窗户出现了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲了一下鼓，旁边的鼓发生了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个钟摆挂在一起，会发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一响，桌子上的盒子发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在桥上跳，桥面出现了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器一开，墙就发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弹了一下琴弦，另一根弦发生了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车经过时，房子里的杯子发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共振频率", "label": "复合"}, {"form": "磁共振", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个物体振动，另一个物体跟着振动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b9e127-76e2-48c8-a316-ec41d410e34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：杯子因同频振动而跟着振动，才会发出声音，“共振”正合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色本身不会引起振动，“因颜色而发出声音”不符合事实。"}, {"text": "香气", "is_correct": false, "explanation": "搭配：“香气”不能作为杯子发出声音的原因，词语之间搭配不通。"}, {"text": "光照", "is_correct": false, "explanation": "语义：光照一般不会使杯子发出声音，句中的原因应指振动。"}], "explanations": {"共振": "正确：杯子因同频振动而跟着振动，才会发出声音，“共振”正合句意。", "颜色": "语义：颜色本身不会引起振动，“因颜色而发出声音”不符合事实。", "香气": "搭配：“香气”不能作为杯子发出声音的原因，词语之间搭配不通。", "光照": "语义：光照一般不会使杯子发出声音，句中的原因应指振动。"}, "sentence_index": 0, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我拿出钥匙一拧，门就共振开了。", "explanation": "这里应该用〈打〉。「打开」指让门开；共振指一个东西振动，另一个跟着振动，不表示把门打开。"}, {"text": "他敲了一下鼓，鼓槌共振飞了。", "explanation": "这里应该用〈弹飞〉。弹飞指被撞击后弹出去；共振指物体跟着同频振动，不表示位置的移动。"}, {"text": "我按下开关，灯就共振了。", "explanation": "这里应该用〈亮起〉。亮起指灯光开始发亮；共振指物体跟着振动，不表示灯光亮起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：小孩在桥上跳，桥面因同频振动而跟着振动，即共振。"}, {"text": "星光", "is_correct": false, "explanation": "语义：星光是天体发出的光，与桥面的振动无关，句中的现象不会因此出现。"}, {"text": "芳香", "is_correct": false, "explanation": "语义：桥面因小孩跳跃不会产生芳香，这一现象与振动无关。"}, {"text": "鸟鸣", "is_correct": false, "explanation": "搭配：“出现”一般不接“鸟鸣”，桥面也不会因跳跃而出现鸟的叫声。"}], "explanations": {"共振": "正确：小孩在桥上跳，桥面因同频振动而跟着振动，即共振。", "星光": "语义：星光是天体发出的光，与桥面的振动无关，句中的现象不会因此出现。", "芳香": "语义：桥面因小孩跳跃不会产生芳香，这一现象与振动无关。", "鸟鸣": "搭配：“出现”一般不接“鸟鸣”，桥面也不会因跳跃而出现鸟的叫声。"}, "sentence_index": 6, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子因为摔落而共振了。", "explanation": "这里应该用〈破碎〉。破碎指物体摔成碎块；共振是物体因同频振动而振幅增大，不会因摔落而使杯子碎裂，这里用错了。"}, {"text": "这台机器一开，桌子上的盒子共振到了地上。", "explanation": "这里应该用〈掉落〉。掉落指物体失去支撑而落下；共振指物体因同频振动而振幅增大，不表示位置的移动。"}, {"text": "他感冒了，一直共振。", "explanation": "这里应该用〈咳嗽〉。咳嗽指喉咙受刺激而急促地出气；共振指物体因同频振动而振幅增大，不能用来形容人的身体反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车经过时，窗户正在共振了。", "corrected_sentence": "卡车经过时，窗户正在共振。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用，应删去“了”。错误形式为“正在共振了”，正确形式为“正在共振”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卡车经过时，窗户就会很共振。", "corrected_sentence": "卡车经过时，窗户就会共振。", "error_description": "「共振」前不能用程度副词「很」，应删去「很」，说「窗户就会共振」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
