INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20992, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是很容易看出来。", "primary_collocate": null, "pronunciation": "xiǎn zhù", "ipa": "ɕjɛn˨˩˦ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他的进步很显著。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的效果非常显著。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的差别很显著。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷以后，变化很显著。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了一年，她的汉语有显著的提高。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法的效果不太显著。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最显著的特点是个子高。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的生活有了显著的变化。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，树的变化特别显著。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张照片的不同很显著，一眼就能看出来。", "target_word": "显著", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显著性", "label": "复合"}], "register": "书面", "sense_fingerprint": "变化、效果、差别等明显得很容易看出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20992, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显著", "is_correct": true, "explanation": "正确答案：显著，意思是很容易看出来。"}, {"text": "显示", "is_correct": false, "explanation": "shì 与 zhù 声母不同（sh 与 zh），整词意思是“表现出来，给人看”。"}, {"text": "显处", "is_correct": false, "explanation": "chù 与 zhù 声母不同（ch 与 zh），整词意思是“明显、容易被看见的地方”。"}, {"text": "现住", "is_correct": false, "explanation": "xiàn 与 xiǎn 声调不同（第四声与第三声），整词意思是“现在居住”。"}], "explanations": {"显著": "正确答案：显著，意思是很容易看出来。", "显示": "shì 与 zhù 声母不同（sh 与 zh），整词意思是“表现出来，给人看”。", "显处": "chù 与 zhù 声母不同（ch 与 zh），整词意思是“明显、容易被看见的地方”。", "现住": "xiàn 与 xiǎn 声调不同（第四声与第三声），整词意思是“现在居住”。"}, "sentence_index": null, "correct_answer": "显著"}, "level_3": {"options": [{"text": "显著", "is_correct": true, "explanation": "“显著”形容变化、差别等很容易看出来，符合“进步很___”的语境。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或状态，不能用来形容进步。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容态度，不能用来形容进步。"}, {"text": "充足", "is_correct": false, "explanation": "搭配：“充足”多用于资源、时间等，不说进步充足。"}], "explanations": {"显著": "“显著”形容变化、差别等很容易看出来，符合“进步很___”的语境。", "安静": "语义：“安静”形容环境或状态，不能用来形容进步。", "冷淡": "语义：“冷淡”形容态度，不能用来形容进步。", "充足": "搭配：“充足”多用于资源、时间等，不说进步充足。"}, "sentence_index": 0, "correct_answer": "显著"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出身于一个显著的家庭。", "explanation": "这里应该用〈显赫〉。显著指容易看出来，家世地位高、名望大要用显赫。"}, {"text": "他是这个班里最显著的学生。", "explanation": "这里应该用〈突出〉。显著用于变化、差别等，人的出色表现要用突出。"}, {"text": "他讲这件事讲得很显著。", "explanation": "这里应该用〈清楚〉。显著强调变化或差别明显，讲述是否清楚要用清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显著", "is_correct": true, "explanation": "“显著”修饰“特点”，表示特点很明显，与“个子高”相符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”与后文“个子高”正相反，句子自相矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容人的特点。"}, {"text": "严格", "is_correct": false, "explanation": "语义：“严格”指对要求的把握，不能用来形容个子高这样的外貌特点。"}], "explanations": {"显著": "“显著”修饰“特点”，表示特点很明显，与“个子高”相符。", "矮小": "体貌：“矮小”与后文“个子高”正相反，句子自相矛盾。", "清脆": "搭配：“清脆”形容声音，不能用来形容人的特点。", "严格": "语义：“严格”指对要求的把握，不能用来形容个子高这样的外貌特点。"}, "sentence_index": 6, "correct_answer": "显著"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市有一段显著的历史。", "explanation": "这里应该用〈悠久〉。显著指容易看出来，历史的长久要用悠久。"}, {"text": "他的酒量很显著。", "explanation": "这里应该用〈大〉。显著指容易看出来，酒量的大小要用大。"}, {"text": "他是一位显著的科学家。", "explanation": "这里应该用〈著名〉。显著用于变化、差别等，人的知名度要用著名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革的效果很地显著。", "corrected_sentence": "这次改革的效果很显著。", "error_description": "错误：「很地显著」。「很」修饰形容词「显著」后，不能再加「地」；「地」用于动词前作状语。正确说法是「很显著」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调整以后，产量显著了。", "corrected_sentence": "这次调整以后，产量显著提高了。", "error_description": "错误：「产量显著了」。这里「显著」要作状语修饰动词，说明产量怎样变化，缺少动词「提高」。正确说法是「产量显著提高了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "移动", "is_correct": false, "explanation": "不是反义词：“移动”指位置改变，与“上升”没有对立关系。"}, {"text": "下降", "is_correct": true, "explanation": "“下降”与“上升”互为反义词，指由高向低变化。"}, {"text": "停留", "is_correct": false, "explanation": "不是反义词：“停留”指暂时不动，与“上升”没有对立关系。"}, {"text": "漂浮", "is_correct": false, "explanation": "不是反义词：“漂浮”指浮在液体或空中，与“上升”没有反义关系。"}], "correct_answer": "下降", "explanations": {"移动": "不是反义词：“移动”指位置改变，与“上升”没有对立关系。", "下降": "“下降”与“上升”互为反义词，指由高向低变化。", "停留": "不是反义词：“停留”指暂时不动，与“上升”没有对立关系。", "漂浮": "不是反义词：“漂浮”指浮在液体或空中，与“上升”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "等待", "is_correct": false, "explanation": "不是反义词：“等待”指停下来期盼，与“上升”没有对立关系。"}, {"text": "下降", "is_correct": true, "explanation": "“下降”与“上升”互为反义词，指由高向低变化。"}, {"text": "行走", "is_correct": false, "explanation": "不是反义词：“行走”指步行移动，与“上升”没有反义关系。"}, {"text": "停靠", "is_correct": false, "explanation": "不是反义词：“停靠”指船或车停在某处，与“上升”没有对立关系。"}], "correct_answer": "下降", "explanations": {"等待": "不是反义词：“等待”指停下来期盼，与“上升”没有对立关系。", "下降": "“下降”与“上升”互为反义词，指由高向低变化。", "行走": "不是反义词：“行走”指步行移动，与“上升”没有反义关系。", "停靠": "不是反义词：“停靠”指船或车停在某处，与“上升”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从低处往高处去。", "primary_collocate": null, "pronunciation": "shàng shēng", "ipa": "ʂaŋ˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "气球慢慢上升到天上。", "target_word": "上升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮慢慢上升了。", "target_word": "上升", "complexity_tier": "T3", "furigana": "yuè liang màn man shàng shēng le", "sentence_source": "generated"}, {"text": "电梯正在上升。", "target_word": "上升", "complexity_tier": "T3", "furigana": "diàn tī zhèng zài shàng shēng", "sentence_source": "generated"}, {"text": "烟雾慢慢上升，飘向天空。", "target_word": "上升", "complexity_tier": "T3", "furigana": "yān wù màn man shàng shēng, piāo xiàng tiān kōng", "sentence_source": "generated"}, {"text": "飞机上升得很快。", "target_word": "上升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位上升了，大家要小心。", "target_word": "上升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气泡从杯底慢慢上升。", "target_word": "上升", "complexity_tier": "T3", "furigana": "qì pào cóng bēi dǐ màn man shàng shēng", "sentence_source": "generated"}, {"text": "热空气比冷空气轻，会上升。", "target_word": "上升", "complexity_tier": "T3", "furigana": "rè kōng qì bǐ lěng kōng qì qīng, huì shàng shēng", "sentence_source": "generated"}, {"text": "太阳从东方缓缓上升。", "target_word": "上升", "complexity_tier": "T3", "furigana": "tài yáng cóng dōng fāng huǎn huǎn shàng shēng", "sentence_source": "generated"}, {"text": "咖啡的热气慢慢上升。", "target_word": "上升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上升了", "label": "体标"}, {"form": "上升过", "label": "体标"}], "register": "中性", "sense_fingerprint": "位置、温度、数量等由低向高变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落", "is_correct": false, "explanation": "语义：“落”指向下掉落，与“到天上”的向上方向相矛盾。"}, {"text": "上升", "is_correct": true, "explanation": "“上升”指由低向高移动，与“慢慢……到天上”的语境相符。"}, {"text": "掉", "is_correct": false, "explanation": "语义：“掉”多指意外或突然地落下，与“慢慢”和“到天上”都不协调。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指猛烈跌落，不能与“慢慢”搭配，也不能说“摔到天上”。"}], "explanations": {"落": "语义：“落”指向下掉落，与“到天上”的向上方向相矛盾。", "上升": "“上升”指由低向高移动，与“慢慢……到天上”的语境相符。", "掉": "语义：“掉”多指意外或突然地落下，与“慢慢”和“到天上”都不协调。", "摔": "搭配：“摔”指猛烈跌落，不能与“慢慢”搭配，也不能说“摔到天上”。"}, "sentence_index": 0, "correct_answer": "上升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子今天上升了十页书。", "explanation": "这里应该用〈读〉。上升用于位置、温度、数量等整体变化，阅读的页数要说“读”。"}, {"text": "他一步一步上升到了七楼，累得不行。", "explanation": "这里应该用〈爬〉。上升用于位置、温度等整体变化，人自己沿楼梯往上走要说“爬”。"}, {"text": "他终于做完了题，表情慢慢上升了。", "explanation": "这里应该用〈放松〉。上升指位置、温度、数量等由低向高变化，表情由紧张变为松弛要说“放松”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "躺", "is_correct": false, "explanation": "搭配：“躺”指平卧，气泡不能说“躺”。"}, {"text": "上升", "is_correct": true, "explanation": "“上升”指由低向高运动，与“从杯底慢慢……”的语境相符。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”指快速跃起，与“慢慢”的语境不符。"}, {"text": "摆", "is_correct": false, "explanation": "语义：“摆”指来回摇动，不表示由低向高的运动。"}], "explanations": {"躺": "搭配：“躺”指平卧，气泡不能说“躺”。", "上升": "“上升”指由低向高运动，与“从杯底慢慢……”的语境相符。", "跳": "语义：“跳”指快速跃起，与“慢慢”的语境不符。", "摆": "语义：“摆”指来回摇动，不表示由低向高的运动。"}, "sentence_index": 6, "correct_answer": "上升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着陡峭的山路上升，终于到了山顶。", "explanation": "这里应该用〈攀登〉。上升用于位置、温度等整体变化，人沿山路往上走要说“攀登”。"}, {"text": "这个孩子一天天上升，越来越懂事。", "explanation": "这里应该用〈长大〉。上升指由低向高的位置或数量变化，人的成长要说“长大”。"}, {"text": "这盘菜放了辣椒，颜色一下子上升了。", "explanation": "这里应该用〈变红〉。上升指位置、温度、数量的向上变化，颜色变红要说“变红”，不能说“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温度被上升了五度。", "corrected_sentence": "温度上升了五度。", "error_description": "用法错误：“上升”是不及物动词，不能用“被”构成被动句，应说“温度上升了五度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在他的努力下，把成绩上升了。", "corrected_sentence": "在他的努力下，成绩上升了。", "error_description": "用法错误：“上升”是不及物动词，不能用于“把”字句，应说“成绩上升了”；表示使成绩提高时说“提高成绩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
