INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网络就像一张大网，把很多电脑连在一起，可以看动画片、找朋友。", "primary_collocate": null, "pronunciation": "wǎng luò", "ipa": "waŋ˨˩˦ lwo˥˩", "syllable_count": 2, "sentences": [{"text": "有了网络，我可以看动画片。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络像一张大网。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用网络和奶奶视频。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的网络坏了，我不能玩游戏。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网络上找到了新朋友。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络把很多电脑连在一起。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们在网络上查资料。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的网络很快。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥用网络学画画。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有网络，电脑就不能看视频。", "target_word": "网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "网络游戏", "label": "复合"}, {"form": "网络安全", "label": "复合"}], "register": "中性", "sense_fingerprint": "把很多电脑连在一起的大网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空调", "is_correct": false, "explanation": "语义：“空调”用来调节温度，不能用来播放动画片。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，与看动画片无关。"}, {"text": "网络", "is_correct": true, "explanation": "正确。“有了网络”指具备上网的条件，与“我可以看动画片”的语境一致。"}, {"text": "毛笔", "is_correct": false, "explanation": "语义：“毛笔”是书写用具，与看动画片无关。"}], "explanations": {"空调": "语义：“空调”用来调节温度，不能用来播放动画片。", "面包": "语义：“面包”是食物，与看动画片无关。", "网络": "正确。“有了网络”指具备上网的条件，与“我可以看动画片”的语境一致。", "毛笔": "语义：“毛笔”是书写用具，与看动画片无关。"}, "sentence_index": 0, "correct_answer": "网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家里的一台网络坏了，我不能玩游戏。", "explanation": "这里的量词不对，应该用〈个〉或〈套〉。“台”用于机器、设备，网络这类系统不用“台”。"}, {"text": "我想去网络买一双鞋。", "explanation": "这里应该用〈网店〉。买东西要去的是网店；“网络”是计算机相连的信息系统，不是可以前往的地方。"}, {"text": "爸爸用网络捞鱼。", "explanation": "“网络”指计算机相连的信息系统，不指渔网，此处的用法与词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲台", "is_correct": false, "explanation": "语义：“讲台”是老师讲课的台子，不是查资料的地方。"}, {"text": "窗台", "is_correct": false, "explanation": "语义：“窗台”是窗下的台面，与查资料无关。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“在……上查资料”要求信息载体，“墙”不能与“查资料”搭配。"}, {"text": "网络", "is_correct": true, "explanation": "正确。“在网络上查资料”是常见说法，“网络”指信息网，与句意一致。"}], "explanations": {"讲台": "语义：“讲台”是老师讲课的台子，不是查资料的地方。", "窗台": "语义：“窗台”是窗下的台面，与查资料无关。", "墙": "搭配：“在……上查资料”要求信息载体，“墙”不能与“查资料”搭配。", "网络": "正确。“在网络上查资料”是常见说法，“网络”指信息网，与句意一致。"}, "sentence_index": 6, "correct_answer": "网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一根网络，装在卧室里。", "explanation": "这里的量词不对，应该用〈套〉或〈个〉。“根”用于细长的东西，网络是系统，不用“根”。"}, {"text": "孩子们用网络抓蝴蝶。", "explanation": "“网络”指计算机相连的信息系统，不指捕蝶的网，此处的用法与词义不符。"}, {"text": "我的网络开在大街上，生意很好。", "explanation": "这里应该用〈店铺〉。店铺才能开在大街上；“网络”是计算机相连的信息系统，不是可以开设的实体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的电脑网络了，就能看动画片。", "corrected_sentence": "我的电脑连网了，就能看动画片。", "error_description": "错误：“网络”是名词，不能作动词说“电脑网络了”；应改用动词“连网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家里装了一条网络，孩子能看动画片。", "corrected_sentence": "家里装了网络，孩子能看动画片。", "error_description": "错误：“网络”不用量词“条”；“条”用于线状事物（如“一条网线”）。说安装网络时直接说“装了网络”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
