INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21001, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "识字率是指会认字的人占总人数的比例。", "primary_collocate": null, "pronunciation": "shí zì lǜ", "ipa": "ʂʅ˧˥ tsɹ̩˥˩ ly˥˩", "syllable_count": 3, "sentences": [{"text": "识字率就是会认字的人的比例。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村的识字率不太高。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，全国的识字率在上升。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "识字率低的地方，需要更多学校。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研究各国的识字率。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的识字率很高。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人多的地方，识字率常常比较低。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办夜校，是为了提高识字率。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这里的识字率是百分之八十。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店多的地方，识字率往往也高。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "識字率", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会认字的人占总人数的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "识字率", "is_correct": true, "explanation": "正确：定义句的主语，指会认字的人占总人数的比例。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数指文字的多少，与“会认字的人的比例”不是同一概念，句子不成立。"}, {"text": "出生率", "is_correct": false, "explanation": "语义：出生率指新生儿与总人口的比例，与“会认字的人”无关，句子不成立。"}, {"text": "人气", "is_correct": false, "explanation": "语义：人气指受欢迎的程度，与“会认字的人的比例”不同，句子不成立。"}], "explanations": {"识字率": "正确：定义句的主语，指会认字的人占总人数的比例。", "字数": "语义：字数指文字的多少，与“会认字的人的比例”不是同一概念，句子不成立。", "出生率": "语义：出生率指新生儿与总人口的比例，与“会认字的人”无关，句子不成立。", "人气": "语义：人气指受欢迎的程度，与“会认字的人的比例”不同，句子不成立。"}, "sentence_index": 0, "correct_answer": "识字率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的识字率增加了三个。", "explanation": "这里应该用〈识字人数〉。识字率是比例，不能用“增加了三个”这样的数量来计算。"}, {"text": "这次考试的识字率是百分之八十。", "explanation": "这里应该用〈及格率〉。识字率指会认字的人口比例，与考试无关，考试的比例应说“及格率”。"}, {"text": "他的识字率很高，经常看书。", "explanation": "这里应该用〈识字能力〉。识字率是对人口的统计，不能用来形容一个人，说个人应用“识字能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "识字率", "is_correct": true, "explanation": "正确：与“老人多的地方”相配，表示会认字的人口比例较低。"}, {"text": "死亡率", "is_correct": false, "explanation": "语义：老人多的地方死亡率往往较高，“比较低”与前半句的常识相矛盾。"}, {"text": "颜值", "is_correct": false, "explanation": "语义：颜值只用于形容人的外貌，不能用来描述一个地方的情况。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：老人多通常意味着寿命较长，寿命“比较低”与前半句相矛盾。"}], "explanations": {"识字率": "正确：与“老人多的地方”相配，表示会认字的人口比例较低。", "死亡率": "语义：老人多的地方死亡率往往较高，“比较低”与前半句的常识相矛盾。", "颜值": "语义：颜值只用于形容人的外貌，不能用来描述一个地方的情况。", "寿命": "语义：老人多通常意味着寿命较长，寿命“比较低”与前半句相矛盾。"}, "sentence_index": 6, "correct_answer": "识字率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所大学的识字率很低，每年只录取三百人。", "explanation": "这里应该用〈录取率〉。录取率指报名者中被录取的比例，识字率指会认字的人口比例，与大学招生无关。"}, {"text": "书店多的地方，识字率往往也旺盛。", "explanation": "这里应该用〈人气〉。“旺盛”多用于人气、生命力，识字率是比例，不能说“旺盛”。"}, {"text": "书店多的地方，识字率往往也丰富。", "explanation": "这里应该用〈知识〉。“丰富”多用于知识、资源，识字率是比例，不能说“丰富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村地识字率这几年提高了不少。", "corrected_sentence": "我们村的识字率这几年提高了不少。", "error_description": "错误在“识字率”前的修饰词。修饰名词要用“的”，“地”用于修饰动词，应为“我们村的识字率”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区一个识字率一年比一年高。", "corrected_sentence": "这个地区的识字率一年比一年高。", "error_description": "错误在“识字率”前多加了量词“一个”。识字率是统计指标，前面直接用“的”修饰即可，应为“这个地区的识字率”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
