INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21004, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "媒体是告诉大家消息的东西，比如电视和报纸。", "primary_collocate": null, "pronunciation": "méi tǐ", "ipa": "meɪ˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "很多媒体都说了这件事。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息今天上了各大媒体。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视和报纸都是媒体。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事引起了媒体的注意。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体每天告诉我们很多新消息。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多媒体来到比赛现场。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢接受媒体的采访。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家媒体每天早上发新闻。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体说明天会下大雨。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们别全信媒体的话。", "target_word": "媒体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家媒体", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词，向大众传递新闻和消息的工具或机构，如电视、报纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "媒体", "is_correct": true, "explanation": "正确：“很多媒体都说了这件事”指多家传媒报道了此事，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“说”需要能说话的施事，桌子不能说话，“很多桌子都说了这件事”不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水体，不能“说了这件事”，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "配价：“说”的主语应是人或机构，花园不能说话，句意不通。"}], "explanations": {"媒体": "正确：“很多媒体都说了这件事”指多家传媒报道了此事，符合语境。", "桌子": "配价：“说”需要能说话的施事，桌子不能说话，“很多桌子都说了这件事”不通。", "河流": "语义：河流是自然水体，不能“说了这件事”，句意不通。", "花园": "配价：“说”的主语应是人或机构，花园不能说话，句意不通。"}, "sentence_index": 0, "correct_answer": "媒体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名优秀的媒体。", "explanation": "这里应该用〈记者〉。媒体指机构或渠道，不指从事采访的人，人应说“记者”。"}, {"text": "媒体每天生产很多汽车。", "explanation": "这里应该用〈工厂〉。媒体的功能是传播消息，不生产汽车。"}, {"text": "媒体做了一顿很好吃的饭。", "explanation": "这里应该用〈厨师〉。做饭的是厨师，媒体是传播消息的机构，不做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媒体", "is_correct": true, "explanation": "正确：“接受媒体的采访”指接受新闻机构的访问，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会接受采访，“接受石头的采访”句意不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能作为采访的对象，“接受树的采访”句意不通。"}, {"text": "食物", "is_correct": false, "explanation": "配价：“采访”的对象需能回答问题，食物不能接受采访，搭配不当。"}], "explanations": {"媒体": "正确：“接受媒体的采访”指接受新闻机构的访问，符合语境。", "石头": "语义：石头不会接受采访，“接受石头的采访”句意不通。", "树": "语义：树不能作为采访的对象，“接受树的采访”句意不通。", "食物": "配价：“采访”的对象需能回答问题，食物不能接受采访，搭配不当。"}, "sentence_index": 6, "correct_answer": "媒体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "媒体给病人看病。", "explanation": "这里应该用〈医生〉。看病的是医生，媒体不能给病人看病。"}, {"text": "这家媒体的菜很好吃。", "explanation": "这里应该用〈饭店〉。菜是饭店提供的，媒体是传播消息的机构，不做菜。"}, {"text": "媒体在舞台上表演。", "explanation": "这里应该用〈演员〉。在舞台上表演的是演员，媒体不能在舞台上表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天有一名媒体来采访我们。", "corrected_sentence": "昨天有一家媒体来采访我们。", "error_description": "错误：“一名媒体”；正确：“一家媒体”。“名”用于人，媒体是机构，应用量词“家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条新闻在各大媒体的上都能看到。", "corrected_sentence": "这条新闻在各大媒体上都能看到。", "error_description": "错误：“媒体的上”；正确：“媒体上”。“媒体”后面不能加“的”再接方位词“上”，应直接说“媒体上”，表示在这个平台上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
