INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21006, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21006, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "范围只限于某个地方或某些方面，不能超出。", "primary_collocate": null, "pronunciation": "jú xiàn yú", "ipa": "tɕy˧˥ ɕjɛn˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "我的生活只局限于学校和家。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病只局限于南方的几个地方。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友不局限于本校的同学。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的讨论不应该局限于这一个问题。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的客人局限于附近的居民。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的兴趣局限于读书，不爱运动。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛局限于十八岁以下的学生。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习不能局限于课本，还要多了解外面的世界。", "target_word": "局限于", "complexity_tier": "T3", "furigana": "xué xí bù néng jú xiàn yú kè běn，hái yào duō liǎo jiě wài miàn de shì jiè。", "sentence_source": "generated"}, {"text": "这个习惯并不局限于老年人。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火只局限于一楼，没有烧到楼上。", "target_word": "局限于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "局限性", "label": "复合"}], "register": "中性", "sense_fingerprint": "范围只限制在某个地方或方面，不能超出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”表示期待，主语“生活”不能盼望，句子不通。"}, {"text": "局限于", "is_correct": true, "explanation": "“局限于”表示范围只限在某处，与“只……学校和家”相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的施事必须是人，“生活”不能批评学校和家。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，后面不能直接带“学校和家”作宾语。"}], "explanations": {"盼望": "语义：“盼望”表示期待，主语“生活”不能盼望，句子不通。", "局限于": "“局限于”表示范围只限在某处，与“只……学校和家”相符。", "批评": "语义：“批评”的施事必须是人，“生活”不能批评学校和家。", "出发": "配价：“出发”是不及物动词，后面不能直接带“学校和家”作宾语。"}, "sentence_index": 0, "correct_answer": "局限于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母局限于他的行为。", "explanation": "这里应该用〈限制〉。局限于表示范围只在某处，主语不能是施加限制的人，应说“父母限制他的行为”。"}, {"text": "他局限于所有对手。", "explanation": "这里应该用〈超越〉。局限于表示范围受限，不能表示超过对手，应说“他超越了所有对手”。"}, {"text": "这次比赛他局限于纪录。", "explanation": "这里应该用〈打破〉。局限于只表示范围受限，不能表示突破纪录，应说“他打破了纪录”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲述", "is_correct": false, "explanation": "搭配：“讲述”一般带故事、经历等内容作宾语，不能带“学生”。"}, {"text": "局限于", "is_correct": true, "explanation": "“局限于”表示范围只限在十八岁以下的学生，与句意相符。"}, {"text": "进入", "is_correct": false, "explanation": "配价：“进入”后面接的应是场所，“十八岁以下的学生”不能作“进入”的宾语。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是人主动躲开的行为，比赛不能“逃避”学生。"}], "explanations": {"讲述": "搭配：“讲述”一般带故事、经历等内容作宾语，不能带“学生”。", "局限于": "“局限于”表示范围只限在十八岁以下的学生，与句意相符。", "进入": "配价：“进入”后面接的应是场所，“十八岁以下的学生”不能作“进入”的宾语。", "逃避": "语义：“逃避”是人主动躲开的行为，比赛不能“逃避”学生。"}, "sentence_index": 6, "correct_answer": "局限于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他局限于朋友。", "explanation": "这里应该用〈说服〉。局限于表示范围，不能表示使人同意，应说“他说服了朋友”。"}, {"text": "妈妈局限于哭泣的孩子。", "explanation": "这里应该用〈安慰〉。局限于表示范围，不能表示让人平静下来，应说“妈妈安慰哭泣的孩子”。"}, {"text": "老师局限于他的努力。", "explanation": "这里应该用〈赞美〉。局限于表示范围，不能表示称赞，应说“老师赞美他的努力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划只局限于了城市里的老人。", "corrected_sentence": "这个计划只局限于城市里的老人。", "error_description": "动态助词位置错误：“局限于”后面直接带宾语，不能在“于”后加“了”。错误形式是“局限于了城市里的老人”，正确形式是“局限于城市里的老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个俱乐部只很局限于本市的年轻人。", "corrected_sentence": "这个俱乐部只局限于本市的年轻人。", "error_description": "程度副词位置错误：“局限于”前面不能加程度副词“很”，句中多用了“很”。错误形式是“只很局限于”，正确形式是“只局限于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
