INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作者自己写的稿子。", "primary_collocate": null, "pronunciation": "shǒu gǎo", "ipa": "ʂoʊ̯˨˩˦ kɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "手稿就是作者自己写的稿子。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是爷爷写的手稿，很珍贵。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家的手稿上有不少涂改。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她保存着母亲留下的手稿。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授的手稿都放在书柜里。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版前，作者先把手稿给朋友看。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手稿的字迹很清楚。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了三年才写完这份手稿。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说的手稿已经寄给编辑了。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧书店里有一份名人的手稿。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "作者自己写的稿子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21008, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确答案：手稿（shǒu gǎo），作者自己写的稿子。"}, {"text": "首脑", "is_correct": false, "explanation": "nǎo 与 gǎo 声母不同（n 与 g），“首脑”意思是领导人，与“手稿”区分开。"}, {"text": "收稿", "is_correct": false, "explanation": "shōu 与 shǒu 声调不同（第一声），“收稿”意思是收取稿件。"}, {"text": "寿糕", "is_correct": false, "explanation": "shòu 与 shǒu 声调不同，gāo 与 gǎo 声调也不同，“寿糕”意思是祝寿用的糕点。"}, {"text": "首考", "is_correct": false, "explanation": "kǎo 与 gǎo 声母不同（k 与 g），“首考”意思是第一次参加考试。"}], "explanations": {"手稿": "正确答案：手稿（shǒu gǎo），作者自己写的稿子。", "首脑": "nǎo 与 gǎo 声母不同（n 与 g），“首脑”意思是领导人，与“手稿”区分开。", "收稿": "shōu 与 shǒu 声调不同（第一声），“收稿”意思是收取稿件。", "寿糕": "shòu 与 shǒu 声调不同，gāo 与 gǎo 声调也不同，“寿糕”意思是祝寿用的糕点。", "首考": "kǎo 与 gǎo 声母不同（k 与 g），“首考”意思是第一次参加考试。"}, "sentence_index": null, "correct_answer": "手稿"}, "level_3": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确：手稿就是作者自己写的稿子，符合句子的定义。"}, {"text": "译文", "is_correct": false, "explanation": "语义：译文是译者翻译的，不是作者自己写的。"}, {"text": "印刷品", "is_correct": false, "explanation": "搭配：“写”的结果是稿子，“印刷品”不是作者亲手写出来的，搭配不当。"}, {"text": "代笔稿", "is_correct": false, "explanation": "语义：代笔稿是他人代为执笔的，不是作者自己写的，与定义相反。"}], "explanations": {"手稿": "正确：手稿就是作者自己写的稿子，符合句子的定义。", "译文": "语义：译文是译者翻译的，不是作者自己写的。", "印刷品": "搭配：“写”的结果是稿子，“印刷品”不是作者亲手写出来的，搭配不当。", "代笔稿": "语义：代笔稿是他人代为执笔的，不是作者自己写的，与定义相反。"}, "sentence_index": 0, "correct_answer": "手稿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，他打开手稿遮雨。", "explanation": "这里应该用〈雨伞〉。手稿是作者写的原稿，不是遮雨的用具。"}, {"text": "我每天骑着这份手稿上学。", "explanation": "这里应该用〈自行车〉。手稿是纸上的文字，不能骑，骑的应是自行车。"}, {"text": "这份手稿是超市打印的，我已经交给了会计。", "explanation": "这里应该用〈收据〉。手稿指作者自己写的原稿，超市打印的收据不能叫手稿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21008, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确答案：手稿（shǒu gǎo），作者自己写的稿子。"}, {"text": "收稿", "is_correct": false, "explanation": "shōu 与 shǒu 声调不同（第一声），“收稿”意思是收取稿件。"}, {"text": "首告", "is_correct": false, "explanation": "gào 与 gǎo 声调不同（第四声），“首告”意思是向有关部门告发。"}, {"text": "售稿", "is_correct": false, "explanation": "shòu 与 shǒu 声调不同（第四声），“售稿”意思是出售稿件。"}], "explanations": {"手稿": "正确答案：手稿（shǒu gǎo），作者自己写的稿子。", "收稿": "shōu 与 shǒu 声调不同（第一声），“收稿”意思是收取稿件。", "首告": "gào 与 gǎo 声调不同（第四声），“首告”意思是向有关部门告发。", "售稿": "shòu 与 shǒu 声调不同（第四声），“售稿”意思是出售稿件。"}, "sentence_index": null, "correct_answer": "手稿"}, "level_3": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确：字迹属于手稿，句中说的是手稿上的笔迹清楚。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞上没有需要辨认的字迹，“字迹很清楚”不成立。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不是书写载体，没有字迹可言。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是书写载体，没有字迹可言，句子不成立。"}], "explanations": {"手稿": "正确：字迹属于手稿，句中说的是手稿上的笔迹清楚。", "雨伞": "语义：雨伞上没有需要辨认的字迹，“字迹很清楚”不成立。", "手套": "语义：手套不是书写载体，没有字迹可言。", "空气": "语义：空气不是书写载体，没有字迹可言，句子不成立。"}, "sentence_index": 6, "correct_answer": "手稿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天冷了，他穿上了一件厚手稿。", "explanation": "这里应该用〈外套〉。手稿是作者写的原稿，不能穿在身上。"}, {"text": "他吃了一份手稿，还说很好吃。", "explanation": "这里应该用〈蛋糕〉。手稿是文字原稿，不是食物，不能吃。"}, {"text": "他每天用手稿给花浇水。", "explanation": "这里应该用〈水壶〉。手稿是文字原稿，不能当作浇花的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她找到了一块母亲写的手稿。", "corrected_sentence": "她找到了一篇母亲写的手稿。", "error_description": "量词错误：“手稿”是文稿，应用量词“篇”，“块”用于块状物，不能用来计量稿件。错误在“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份手稿写很清楚，老师很满意。", "corrected_sentence": "这份手稿写得很清楚，老师很满意。", "error_description": "补语错误：描述“写”的程度要用“得”连接补语，应说“写得很清楚”，漏掉“得”。错误在“写”与“很清楚”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
