INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群人因为一起做事情或一起玩而组成的团体。", "primary_collocate": null, "pronunciation": "shè tuán", "ipa": "ʂɤ˥˩ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "我想参加学校的足球社团。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社团里的同学一起打球、做饭。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的社团有二十个人。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，社团的同学约他一起玩游戏。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社团每个月出去玩一次。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在漫画社团认识了好朋友。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社团的老师帮我们找了教室。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们社团一起去公园。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大学里加入了登山社团。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想参加哪个社团？", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "学生社团", "label": "复合"}, {"form": "社團", "label": "繁体"}], "register": "口语", "sense_fingerprint": "一群人为了一起做事或玩而组成的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社团", "is_correct": true, "explanation": "正确：指一群人因共同爱好而组成的团体，可以说“参加”。"}, {"text": "足球场", "is_correct": false, "explanation": "语义：足球场是场地，不是可以“参加”的组织，句子不成立。"}, {"text": "足球鞋", "is_correct": false, "explanation": "语义：足球鞋是运动装备，不是可以“参加”的团体，与句意不符。"}, {"text": "足球门", "is_correct": false, "explanation": "语义：足球门是球场上的设施，不是可以“参加”的团体，句子不成立。"}], "explanations": {"社团": "正确：指一群人因共同爱好而组成的团体，可以说“参加”。", "足球场": "语义：足球场是场地，不是可以“参加”的组织，句子不成立。", "足球鞋": "语义：足球鞋是运动装备，不是可以“参加”的团体，与句意不符。", "足球门": "语义：足球门是球场上的设施，不是可以“参加”的团体，句子不成立。"}, "sentence_index": 0, "correct_answer": "社团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我加入了一只社团。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的东西，社团应用量词“个”。"}, {"text": "我们社团每周都开一次班会。", "explanation": "这里应该用〈班级〉。班会是班级的会议，社团是因一起玩或做事而组成的团体，不能开班会。"}, {"text": "我把社团放进了书包。", "explanation": "这里应该用〈书〉。社团是一群人组成的团体，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社团", "is_correct": true, "explanation": "正确：与“老师”和“帮我们找了教室”的语境相符，指一群人组成的团体。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行没有老师，也不负责帮人找教室，句子的语境不成立。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂不设老师，也不会去帮学生找教室，与句意不符。"}, {"text": "帮派", "is_correct": false, "explanation": "语域：帮派带有贬义，不能用在“老师帮我们”这样的友好语境中。"}], "explanations": {"社团": "正确：与“老师”和“帮我们找了教室”的语境相符，指一群人组成的团体。", "银行": "语义：银行没有老师，也不负责帮人找教室，句子的语境不成立。", "食堂": "语义：食堂不设老师，也不会去帮学生找教室，与句意不符。", "帮派": "语域：帮派带有贬义，不能用在“老师帮我们”这样的友好语境中。"}, "sentence_index": 6, "correct_answer": "社团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你想去哪个社团上班？", "explanation": "这里应该用〈单位〉。“上班”的地点应是单位，社团是业余组织，不能说“去社团上班”。"}, {"text": "你想吃哪种社团？", "explanation": "这里应该用〈饭〉。“吃”的对象应是食物，社团不能吃。"}, {"text": "这个社团很好喝。", "explanation": "这里应该用〈饮料〉。“好喝”用于饮料、汤等，社团不能形容为好喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个社团们都有自己的活动。", "corrected_sentence": "每个社团都有自己的活动。", "error_description": "错误在“社团”后多加了“们”。“们”主要用于指人的名词，社团是组织，应直接说“每个社团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他社团里认识了很多朋友。", "corrected_sentence": "他在社团里认识了很多朋友。", "error_description": "错误在“社团里”前漏掉了介词“在”。“社团里”表示地点，需要用“在”引出，应为“他在社团里认识了很多朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
