INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人一个讲给另一个，一个又讲给下一个，这样传下去。", "primary_collocate": null, "pronunciation": "kǒu ěr xiāng chuán", "ipa": "kʰoʊ̯˨˩˦ ɚ˨˩˦ ɕjɑŋ˥ ʈʂʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "老人们的故事一代又一代地口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "furigana": "lǎo rén men de gù shi yí dài yòu yí dài de kǒu ěr xiāng chuán", "sentence_source": "generated"}, {"text": "这首民歌没有谱子，全靠口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好办法在朋友之间口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的家规不写在纸上，而是口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的名气是口耳相传出来的。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间药方多半是口耳相传的。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些古老的习俗至今还靠口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笑话在学校里口耳相传，人人都知道。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅教徒弟时常常口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传说没有书面记载，只能口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "furigana": "zhè ge chuán shuō méi yǒu shū miàn jì zǎi, zhǐ néng kǒu ěr xiāng chuán。", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个人讲给另一个人，一代代传下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口耳相传", "is_correct": true, "explanation": "口耳相传：靠口头讲述、一代代传下去，与“一代又一代”相符。"}, {"text": "网络直播", "is_correct": false, "explanation": "语义：“一代又一代”强调世代延续，“网络直播”是即时播出，不能表示世代流传。"}, {"text": "暂时保存", "is_correct": false, "explanation": "语义：“暂时”与“一代又一代”的长久延续相矛盾。"}, {"text": "闭门研究", "is_correct": false, "explanation": "搭配：“故事”可以讲述、流传，不说“闭门研究”。"}], "explanations": {"口耳相传": "口耳相传：靠口头讲述、一代代传下去，与“一代又一代”相符。", "网络直播": "语义：“一代又一代”强调世代延续，“网络直播”是即时播出，不能表示世代流传。", "暂时保存": "语义：“暂时”与“一代又一代”的长久延续相矛盾。", "闭门研究": "搭配：“故事”可以讲述、流传，不说“闭门研究”。"}, "sentence_index": 0, "correct_answer": "口耳相传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份家规是他用毛笔口耳相传的。", "explanation": "这里应该用〈抄写〉。口耳相传是口头传递，用毛笔写下的家规不能用口耳相传来表示。"}, {"text": "他一个人在山上口耳相传。", "explanation": "这里应该用〈喊叫〉。口耳相传需要一人讲给另一人，不能形容一个人独自喊叫。"}, {"text": "这首曲子是他用钢琴口耳相传的。", "explanation": "这里应该用〈弹奏〉。曲子是通过乐器演奏的，不能用口耳相传来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口耳相传", "is_correct": true, "explanation": "口耳相传：靠口头讲述代代传下来，与“古老的习俗”相符。"}, {"text": "严禁传播", "is_correct": false, "explanation": "语义：“严禁传播”与“至今还靠……”的传承意思相矛盾。"}, {"text": "出口销售", "is_correct": false, "explanation": "搭配：“习俗”是可以传承的风俗，不能与“出口销售”搭配。"}, {"text": "拆除重建", "is_correct": false, "explanation": "语义：“拆除重建”是对建筑的处理，与习俗无关，不能靠它流传下来。"}], "explanations": {"口耳相传": "口耳相传：靠口头讲述代代传下来，与“古老的习俗”相符。", "严禁传播": "语义：“严禁传播”与“至今还靠……”的传承意思相矛盾。", "出口销售": "搭配：“习俗”是可以传承的风俗，不能与“出口销售”搭配。", "拆除重建": "语义：“拆除重建”是对建筑的处理，与习俗无关，不能靠它流传下来。"}, "sentence_index": 6, "correct_answer": "口耳相传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本教材是印刷厂口耳相传的。", "explanation": "这里应该用〈印刷〉。教材是印出来的书面材料，不能靠口耳相传。"}, {"text": "这段历史是用胶片口耳相传下来的。", "explanation": "这里应该用〈拍摄〉。胶片记录的是影像，口耳相传是靠口头讲述传递，二者不能互换。"}, {"text": "这份文件是用公章口耳相传的。", "explanation": "这里应该用〈盖〉。公章是盖在文件上的印记，不能用口耳相传来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些歌谣是祖辈口耳相传下来。", "corrected_sentence": "这些歌谣是祖辈口耳相传下来的。", "error_description": "句式错误：“是……的”强调句式中漏掉了“的”，应说“这些歌谣是祖辈口耳相传下来的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个故事在村里口耳相传得很多年。", "corrected_sentence": "这个故事在村里口耳相传了很多年。", "error_description": "助词错误：动词后接时段“很多年”要用“了”，不能用补语标记“得”。错误在“得”，应说“这个故事在村里口耳相传了很多年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "正确。离开指从某处走出去，与进入的方向相反，与“进入商店”相对。"}, {"text": "保持", "is_correct": false, "explanation": "保持指使某种状态持续，与进入的方向没有相对关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指动脑想问题，与进入没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使物品恢复正常，与进入没有反义关系。"}], "correct_answer": "离开", "explanations": {"离开": "正确。离开指从某处走出去，与进入的方向相反，与“进入商店”相对。", "保持": "保持指使某种状态持续，与进入的方向没有相对关系。", "思考": "思考指动脑想问题，与进入没有反义关系。", "修理": "修理指使物品恢复正常，与进入没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "正确。离开指从某处走出去，与“进入图书馆”的方向相反。"}, {"text": "完成", "is_correct": false, "explanation": "完成指做好某件事，与进入没有反义关系。"}, {"text": "记住", "is_correct": false, "explanation": "记住指把事情留在脑中，与进入没有反义关系。"}, {"text": "批评", "is_correct": false, "explanation": "批评指指出错误，与进入没有反义关系。"}], "correct_answer": "离开", "explanations": {"离开": "正确。离开指从某处走出去，与“进入图书馆”的方向相反。", "完成": "完成指做好某件事，与进入没有反义关系。", "记住": "记住指把事情留在脑中，与进入没有反义关系。", "批评": "批评指指出错误，与进入没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走进一个地方里面。", "primary_collocate": null, "pronunciation": "jìn rù", "ipa": "tɕin˥˩ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "请进入教室，坐好。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他慢慢进入了房间。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们进入公园玩儿。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "进入商店前，先关手机。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起进入电影院。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有票的人不能进入这里。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打开门，进入了客厅。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面太冷，我们进入屋子吧。", "target_word": "进入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从这个门进入。", "target_word": "进入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着书进入了图书馆。", "target_word": "进入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进入了", "label": "体标"}, {"form": "进入过", "label": "体标"}, {"form": "進入", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进入：从外面走到某地方里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进入", "is_correct": true, "explanation": "正确。进入读作 jìn rù，意思是走进某个地方里面。"}, {"text": "近日", "is_correct": false, "explanation": "近日 jìnrì：韵母 ì 与 ù 不同，意思是最近几天，与走进某处无关。"}, {"text": "沁入", "is_correct": false, "explanation": "沁入 qìnrù：声母 q 与 j 不同，意思是渗入，常用于气味或液体。"}, {"text": "近路", "is_correct": false, "explanation": "近路 jìnlù：声母 l 与 r 不同，意思是较短的路，不是走进。"}], "explanations": {"进入": "正确。进入读作 jìn rù，意思是走进某个地方里面。", "近日": "近日 jìnrì：韵母 ì 与 ù 不同，意思是最近几天，与走进某处无关。", "沁入": "沁入 qìnrù：声母 q 与 j 不同，意思是渗入，常用于气味或液体。", "近路": "近路 jìnlù：声母 l 与 r 不同，意思是较短的路，不是走进。"}, "sentence_index": null, "correct_answer": "进入"}, "level_3": {"options": [{"text": "进入", "is_correct": true, "explanation": "正确。“请进入教室，坐好”中，进入表示走进教室里面，与“坐好”的指令衔接。"}, {"text": "离开", "is_correct": false, "explanation": "语义：离开是“从某处出去”，与“坐好”的指令冲突，学生不会离开教室再坐下。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：讨论的宾语是问题或话题，不能直接以“教室”作宾语。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带“教室”作宾语。"}], "explanations": {"进入": "正确。“请进入教室，坐好”中，进入表示走进教室里面，与“坐好”的指令衔接。", "离开": "语义：离开是“从某处出去”，与“坐好”的指令冲突，学生不会离开教室再坐下。", "讨论": "配价：讨论的宾语是问题或话题，不能直接以“教室”作宾语。", "毕业": "配价：“毕业”是不及物动词，不能带“教室”作宾语。"}, "sentence_index": 0, "correct_answer": "进入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他进入了被窝。", "explanation": "这里应该用〈钻进〉。进入强调走到某个场所或范围里，被窝不是可以“进入”的场所，人钻进被子要说钻进。"}, {"text": "信进入了抽屉。", "explanation": "这里应该用〈放进〉。进入强调人或物自行走进某个场所或范围，信是人放进抽屉的，应说放进。"}, {"text": "我进入了一个苹果。", "explanation": "这里应该用〈吃了〉。进入指走进某个场所或范围，苹果不是场所，吃东西要说吃了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进入", "is_correct": true, "explanation": "正确。“她打开门，进入了客厅”中，进入表示走进客厅里面，与前半句衔接自然。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃是舍弃、不再坚持，与“打开门”之后走进房间的动作不符。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、灯或燃料，不能以“客厅”作宾语。"}, {"text": "撕碎", "is_correct": false, "explanation": "搭配：“撕碎”的对象是纸张等薄物，不能以“客厅”作宾语。"}], "explanations": {"进入": "正确。“她打开门，进入了客厅”中，进入表示走进客厅里面，与前半句衔接自然。", "放弃": "语义：放弃是舍弃、不再坚持，与“打开门”之后走进房间的动作不符。", "点燃": "搭配：“点燃”的对象是火、灯或燃料，不能以“客厅”作宾语。", "撕碎": "搭配：“撕碎”的对象是纸张等薄物，不能以“客厅”作宾语。"}, "sentence_index": 6, "correct_answer": "进入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书进入了书包。", "explanation": "这里应该用〈放进〉。“进入”不能与“把”字结构连用表示人主动放置东西，应说把书放进书包。"}, {"text": "我们终于进入了三点钟。", "explanation": "这里应该用〈到了〉。进入表示进到某个场所、阶段或较长的时段，具体时刻要说到了三点钟。"}, {"text": "他进入了一米的高度。", "explanation": "这里应该用〈升到〉。进入指走进某个场所或范围，高度不是场所，应说升到一米的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们陆续进入在礼堂。", "corrected_sentence": "学生们陆续进入礼堂。", "error_description": "错误：“进入在礼堂”，正确：“进入礼堂”。进入后面直接接处所，中间不能插入“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乘客们依次被进入了车厢。", "corrected_sentence": "乘客们依次进入了车厢。", "error_description": "错误：“被进入了车厢”，正确：“进入了车厢”。进入是表示移动的动词，不能用“被”构成被动句，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
