INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转过头去看已经走过的地方。", "primary_collocate": null, "pronunciation": "huí wàng", "ipa": "xuei̯˧˥ uaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他走到山顶，回望来时的路。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上车前回望了一眼家门。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子走出很远，又回望了一眼村口的老屋。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开村子时，他站在路口回望。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬了一天山，在山腰回望山下的小镇。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车开动了，她回望着渐渐远去的小站。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每走一段路，就回望一下身后。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船慢慢离开海岸，大家一起回望码头。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走出校门，她忍不住回望了学校一眼。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人回望着那条走过的小路，没有说话。", "target_word": "回望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回望了", "label": "体标"}, {"form": "回望着", "label": "体标"}, {"form": "回望过", "label": "体标"}], "register": "书面", "sense_fingerprint": "回望：转头看身后走过的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df6c5434-bf82-45b0-9904-96dfe8a36f91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回望", "is_correct": true, "explanation": "回望：转头看身后已经走过的路，与“走到山顶”后回看来路相符。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”是丢弃，走过的路不能被扔掉，句中只是转头看。"}, {"text": "占领", "is_correct": false, "explanation": "搭配：“占领”指强行占据地方或阵地，不能用来搭配“来时的路”。"}, {"text": "拆掉", "is_correct": false, "explanation": "语义：“拆掉”指拆毁建筑物，路不是建筑，句中说的是回头看路。"}], "explanations": {"回望": "回望：转头看身后已经走过的路，与“走到山顶”后回看来路相符。", "扔掉": "语义：“扔掉”是丢弃，走过的路不能被扔掉，句中只是转头看。", "占领": "搭配：“占领”指强行占据地方或阵地，不能用来搭配“来时的路”。", "拆掉": "语义：“拆掉”指拆毁建筑物，路不是建筑，句中说的是回头看路。"}, "sentence_index": 0, "correct_answer": "回望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院回望生病的奶奶。", "explanation": "这里应该用〈看望〉。回望指转头看身后已经走过的地方，探望病人要用看望。"}, {"text": "他把信回望了一遍，然后寄了出去。", "explanation": "这里应该用〈读〉。回望指转头看身后已经走过的地方，读信要用读。"}, {"text": "科学家在显微镜下回望细胞。", "explanation": "这里应该用〈观察〉。回望指看已经走过的地方，在显微镜下研究细胞要用观察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回望", "is_correct": true, "explanation": "回望：转头看身后，与“每走一段路就看一下身后”的动作相符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”指丢下不要，句中是看一看身后，并不是丢下。"}, {"text": "回避", "is_correct": false, "explanation": "搭配：“回避”多接问题、责任，不能说回避“身后”。"}, {"text": "躲开", "is_correct": false, "explanation": "语义：“躲开”指避开危险或人，与“看一下身后”的意思不合。"}], "explanations": {"回望": "回望：转头看身后，与“每走一段路就看一下身后”的动作相符。", "抛弃": "语义：“抛弃”指丢下不要，句中是看一看身后，并不是丢下。", "回避": "搭配：“回避”多接问题、责任，不能说回避“身后”。", "躲开": "语义：“躲开”指避开危险或人，与“看一下身后”的意思不合。"}, "sentence_index": 6, "correct_answer": "回望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在窗前回望报纸。", "explanation": "这里应该用〈阅读〉。回望指转头看身后已经走过的地方，看报纸要用阅读。"}, {"text": "医生仔细回望了化验单。", "explanation": "这里应该用〈查看〉。回望是看已经走过的地方，检查化验单要用查看。"}, {"text": "孩子在纸上回望了一棵树。", "explanation": "这里应该用〈画〉。回望指转头看走过的地方，在纸上画树要用画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她关上门，又回望了过一眼空荡荡的屋子。", "corrected_sentence": "她关上门，又回望了一眼空荡荡的屋子。", "error_description": "错误：“回望”后同时用了“了”和“过”，写成“回望了过”。正确：只用“了”，说“回望了一眼”。“了”和“过”不能连用在同一个动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚下车，就回望了一个来时的路。", "corrected_sentence": "他刚下车，就回望了一眼来时的路。", "error_description": "错误：“回望”的动量词用了“一个”。正确：说“回望了一眼”，看的次数要用“眼”来数，“个”不能数看的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
