INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21026, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大家一起做一件事。", "primary_collocate": null, "pronunciation": "gòng tóng", "ipa": "kʊŋ˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们共同努力，一定能做好。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家共同做这件事。", "target_word": "共同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们共同完成了这个作业。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友共同买了一辆车。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家共同决定明天去爬山。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们共同开了一家小店。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司和学校共同办了这次活动。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和学生共同做了一个大蛋糕。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家人共同庆祝春节，很热闹。", "target_word": "共同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居们共同把花园打扫干净了。", "target_word": "共同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共同的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "副词：大家一起做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共同", "is_correct": true, "explanation": "正确。共同表示大家一起努力，与“我们”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不常发生，与“一定能做好”的确定语气相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：随便表示不认真、随意，与“一定能做好”的认真态度不符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：白白指徒劳无功，与“一定能做好”的结果相矛盾。"}], "explanations": {"共同": "正确。共同表示大家一起努力，与“我们”搭配。", "偶尔": "语义：偶尔表示不常发生，与“一定能做好”的确定语气相矛盾。", "随便": "语义：随便表示不认真、随意，与“一定能做好”的认真态度不符。", "白白": "语义：白白指徒劳无功，与“一定能做好”的结果相矛盾。"}, "sentence_index": 0, "correct_answer": "共同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人共同做完了这份作业。", "explanation": "这里不能用〈共同〉。“一个人”与“共同”矛盾，应说“我一个人做完了这份作业”。"}, {"text": "校长一个人共同参加了这次会议。", "explanation": "这里不能用〈共同〉。“一个人”与“共同”矛盾，应说“校长一个人参加了这次会议”。"}, {"text": "他独自共同完成了这个项目。", "explanation": "这里不能用〈共同〉。“独自”与“共同”矛盾，应说“他独自完成了这个项目”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同", "is_correct": true, "explanation": "正确。共同表示公司和学校一起办了这次活动。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：偶然表示碰巧发生，与有计划地“办活动”不符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰“办了”这样的动作，不说“非常办了”。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：从不是否定副词，不能与表示完成的“办了”搭配。"}], "explanations": {"共同": "正确。共同表示公司和学校一起办了这次活动。", "偶然": "语义：偶然表示碰巧发生，与有计划地“办活动”不符。", "非常": "语法：“非常”是程度副词，不能直接修饰“办了”这样的动作，不说“非常办了”。", "从不": "搭配：从不是否定副词，不能与表示完成的“办了”搭配。"}, "sentence_index": 6, "correct_answer": "共同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们各自共同写完了作业。", "explanation": "这里不能用〈共同〉。共同表示大家一起做，而句子说每人单独做，两种意思自相矛盾。"}, {"text": "他一个人共同把花园打扫干净了。", "explanation": "这里不能用〈共同〉。“一个人”与“共同”矛盾，应说“他一个人把花园打扫干净了”。"}, {"text": "我独自共同解决了这个问题。", "explanation": "这里不能用〈共同〉。“独自”与“共同”矛盾，应说“我独自解决了这个问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们共同的完成了这个项目。", "corrected_sentence": "我们共同完成了这个项目。", "error_description": "错误：“共同”作副词时后面不加“的”，“共同的”是形容词形式。正确：共同完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很共同参加了这次比赛。", "corrected_sentence": "我们共同参加了这次比赛。", "error_description": "错误：“共同”是副词，前面不能加程度副词“很”修饰。正确：共同参加了这次比赛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
