INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时代就是有某种特点的一段较长的历史时期，比如我们生活的现在。", "primary_collocate": null, "pronunciation": "shí dài", "ipa": "ʂɻ̩˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们生活在一个新时代。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的那个时代，没有手机。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是网络时代。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首老歌是爷爷那个时代的。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时代，人人都有手机。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时代不同了，孩子的想法也不一样。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个好时代。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的父母那个时代很辛苦。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们生活的时代比我们那时候更好。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影让我们看到了另一个时代。", "target_word": "时代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网络时代", "label": "复合"}], "register": "中性", "sense_fingerprint": "有某种特点的一段较长的历史时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时代", "is_correct": true, "explanation": "正确：「时代」指一段历史时期，可以说「生活在一个新时代」。"}, {"text": "手机", "is_correct": false, "explanation": "语义：人不能「生活在」手机里，「手机」不是可以居住的环境。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「考试」是一次事件，不是人所处的历史时期或环境。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「生活在」之后不接「作业」，作业不能作为生活的环境。"}], "explanations": {"时代": "正确：「时代」指一段历史时期，可以说「生活在一个新时代」。", "手机": "语义：人不能「生活在」手机里，「手机」不是可以居住的环境。", "考试": "语义：「考试」是一次事件，不是人所处的历史时期或环境。", "作业": "搭配：「生活在」之后不接「作业」，作业不能作为生活的环境。"}, "sentence_index": 0, "correct_answer": "时代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这里等了很长的时代。", "explanation": "这里应该用〈时间〉。时代指一段历史时期，表示时长要用〈时间〉。"}, {"text": "他的时代是八十岁。", "explanation": "这里应该用〈年龄〉。时代不能表示人的岁数，说年纪要用〈年龄〉。"}, {"text": "这辆车的时代已经三年了。", "explanation": "这里应该用〈车龄〉。时代指历史时期，说车子用了多久要用〈车龄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时代", "is_correct": true, "explanation": "正确：「出生在」之后可以接「时代」，表示出生于某个历史时期。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：「比赛」是一次活动，人不能「出生在」比赛里。"}, {"text": "节目", "is_correct": false, "explanation": "语义：「节目」是演出内容，不能作为出生的时间或地点。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「出生在」不接「味道」，「一个好味道」的说法不能与之搭配。"}], "explanations": {"时代": "正确：「出生在」之后可以接「时代」，表示出生于某个历史时期。", "比赛": "语义：「比赛」是一次活动，人不能「出生在」比赛里。", "节目": "语义：「节目」是演出内容，不能作为出生的时间或地点。", "味道": "搭配：「出生在」不接「味道」，「一个好味道」的说法不能与之搭配。"}, "sentence_index": 6, "correct_answer": "时代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的时代很大。", "explanation": "这里应该用〈体积〉。时代指历史时期，形容物体的大小要用〈体积〉。"}, {"text": "这条河的时代很长。", "explanation": "这里应该用〈长度〉。时代不表示空间距离，河的长短要用〈长度〉。"}, {"text": "这部电影的时代是两小时。", "explanation": "这里应该用〈时长〉。时代指历史时期，电影的播放长度要用〈时长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一颗很特别的时代。", "corrected_sentence": "这是一个很特别的时代。", "error_description": "量词错误：「颗」用于小而圆的东西，「时代」应用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们生活这个时代。", "corrected_sentence": "我们生活在这个时代。", "error_description": "介词错误：「生活」后接表示地点或时期的成分时要用「生活在」，漏掉「在」，「我们生活这个时代」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
