INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说清楚一个词或一件东西是什么。", "primary_collocate": "下", "pronunciation": "dìng yì", "ipa": "tiŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这个词的定义是什么？", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给“幸福”下了一个定义。", "target_word": "定义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你读一下书上的定义。", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人对成功的定义都不一样。", "target_word": "定义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个定义太长，我记不住。", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "词典里有这个词的定义。", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对爱情的定义很简单。", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先看定义，再做题。", "target_word": "定义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你能给“朋友”下定义吗？", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上的定义和我想的不同。", "target_word": "定义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "定義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "定义：对词或事物含义的清楚说明", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定义", "is_correct": true, "explanation": "“定义”指对词义的清楚说明，与“这个词的……是什么”搭配。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说贵贱，不能作“词”的属性。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，与“词”无关。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指明暗程度，与“词”不相关。"}], "explanations": {"定义": "“定义”指对词义的清楚说明，与“这个词的……是什么”搭配。", "价格": "搭配：“价格”说贵贱，不能作“词”的属性。", "体重": "语义：“体重”指人或物的重量，与“词”无关。", "亮度": "语义：“亮度”指明暗程度，与“词”不相关。"}, "sentence_index": 0, "correct_answer": "定义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个定义很重。", "explanation": "这里应该用〈分量〉。轻重说分量，定义不能这样形容。"}, {"text": "这件商品的定义很高。", "explanation": "这里应该用〈定价〉。价格高低说定价，定义不能这样说。"}, {"text": "这位选手的定义很高。", "explanation": "这里应该用〈身高〉。高矮说身高，定义不能用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定义", "is_correct": true, "explanation": "“定义”指对事物含义的说明，与“他对爱情的……很简单”搭配。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指存在的时长，不能用来说明“爱情”的含义。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指空间大小，与“爱情”不搭。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说高低，不能用“简单”来形容。"}], "explanations": {"定义": "“定义”指对事物含义的说明，与“他对爱情的……很简单”搭配。", "寿命": "语义：“寿命”指存在的时长，不能用来说明“爱情”的含义。", "体积": "语义：“体积”指空间大小，与“爱情”不搭。", "温度": "搭配：“温度”说高低，不能用“简单”来形容。"}, "sentence_index": 6, "correct_answer": "定义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车的定义很快。", "explanation": "这里应该用〈速度〉。快慢说速度，定义不能这样形容。"}, {"text": "老师给我们吃了定义。", "explanation": "这里应该用〈食物〉。吃的是食物，定义是抽象的概念，不能吃。"}, {"text": "这朵花的定义很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳形容颜色，定义不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个词的定义的清楚。", "corrected_sentence": "这个词的定义很清楚。", "error_description": "“清楚”作谓语时，程度要用“很”，不能用“的”代替，应说“定义很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典里有五本定义。", "corrected_sentence": "这本词典里有五个定义。", "error_description": "量词错误：“本”用于书籍，“定义”要用量词“个”。正确：“五个定义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
