INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "媒介是让两个东西可以连在一起的中间物。", "primary_collocate": null, "pronunciation": "méi jiè", "ipa": "meɪ˧˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "空气是声音传播的媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子是这种病传播的媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属是热量传递的媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机成了人们联系的新媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言是人们交流的重要媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸、电视都是新闻媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱是买卖东西的媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络是两国青年交流的媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐是不同国家的人互相了解的媒介。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找个媒介来联系那家公司。", "target_word": "媒介", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传播媒介", "label": "复合"}, {"form": "大众媒介", "label": "复合"}], "register": "书面语", "sense_fingerprint": "连接两方的中间物或手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "媒介", "is_correct": true, "explanation": "媒介：连接两方的中间物，读作 méi jiè。"}, {"text": "煤价", "is_correct": false, "explanation": "煤价 méi jià：韵母不同（ia／ie），声调相同（均为第四声），意思是煤炭的价格。"}, {"text": "每届", "is_correct": false, "explanation": "每届 měi jiè：第一音节声调不同（第三声），意思是每一届。"}, {"text": "煤屑", "is_correct": false, "explanation": "煤屑 méi xiè：第二音节声母不同（x 与 j），意思是煤的碎末。"}], "explanations": {"媒介": "媒介：连接两方的中间物，读作 méi jiè。", "煤价": "煤价 méi jià：韵母不同（ia／ie），声调相同（均为第四声），意思是煤炭的价格。", "每届": "每届 měi jiè：第一音节声调不同（第三声），意思是每一届。", "煤屑": "煤屑 méi xiè：第二音节声母不同（x 与 j），意思是煤的碎末。"}, "sentence_index": null, "correct_answer": "媒介"}, "level_3": {"options": [{"text": "媒介", "is_correct": true, "explanation": "媒介：连接两方的中间物，符合空气传播声音的作用。"}, {"text": "对象", "is_correct": false, "explanation": "语义：声音传播的对象是被传到的人或物，空气不是对象。"}, {"text": "结果", "is_correct": false, "explanation": "语义：空气是声音传播的途径，不是传播的结果。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：不说空气是声音传播的方向。"}], "explanations": {"媒介": "媒介：连接两方的中间物，符合空气传播声音的作用。", "对象": "语义：声音传播的对象是被传到的人或物，空气不是对象。", "结果": "语义：空气是声音传播的途径，不是传播的结果。", "方向": "搭配：不说空气是声音传播的方向。"}, "sentence_index": 0, "correct_answer": "媒介"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的书包是媒介，每天装满了书。", "explanation": "这里用错了：「媒介」指连接两方的中间物，而不指装东西的「容器」，这里应说「容器」。"}, {"text": "这次考试的媒介很难，大家都做不完。", "explanation": "这里用错了：「媒介」不指题目的难度。"}, {"text": "妈妈把媒介买回家，做了一顿饭。", "explanation": "这里用错了：「媒介」不是食物，不能买回家做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媒介", "is_correct": true, "explanation": "媒介：连接两方的中间物，钱在买卖中起交换作用。"}, {"text": "货物", "is_correct": false, "explanation": "语义：钱不是买卖的货物，句意不通。"}, {"text": "场所", "is_correct": false, "explanation": "搭配：买卖东西的场所是市场，钱不是场所。"}, {"text": "商店", "is_correct": false, "explanation": "语义：钱不是商店，不能说「钱是买卖东西的商店」。"}], "explanations": {"媒介": "媒介：连接两方的中间物，钱在买卖中起交换作用。", "货物": "语义：钱不是买卖的货物，句意不通。", "场所": "搭配：买卖东西的场所是市场，钱不是场所。", "商店": "语义：钱不是商店，不能说「钱是买卖东西的商店」。"}, "sentence_index": 6, "correct_answer": "媒介"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的媒介是一只猫，很可爱。", "explanation": "这里用错了：媒介指连接两方的中间物，不指动物。"}, {"text": "他想找个媒介，睡一觉再说。", "explanation": "这里用错了：「媒介」不是可以睡觉的地方，也不指休息。"}, {"text": "他的媒介很高，篮球打得很好。", "explanation": "这里用错了：「媒介」不指身高或技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海水是声音传播的一只媒介。", "corrected_sentence": "海水是声音传播的一种媒介。", "error_description": "「媒介」是抽象名词，量词用「种」，「只」多用于动物，不能用来计量媒介。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想找个媒介的来联系买家。", "corrected_sentence": "我们想找个媒介来联系买家。", "error_description": "「来」表目的，直接接在名词「媒介」后面，中间不能加「的」，应说「找个媒介来联系买家」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
