INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个可以照着做的样子或模式。", "primary_collocate": null, "pronunciation": "fàn shì", "ipa": "fan˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这篇论文提供了一种新的研究范式。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们照着这个范式写了作文。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们一个写信的范式。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家改变了旧的研究范式。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个范式很简单，大家都能照着做。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种教学范式已经用了很多年。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找一个成功的管理范式。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画成了后来画家学习的范式。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以套用这个范式写别的文章。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的工作范式让大家更轻松。", "target_word": "范式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种范式", "label": "量词"}, {"form": "範式", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可以照着做的样子或模式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "范式", "is_correct": true, "explanation": "正确：“范式”读作 fàn shì（第四声）。"}, {"text": "凡事", "is_correct": false, "explanation": "声调：fán shì（第二声）与 fàn shì（第四声）声调不同，意思是“凡是的事情”。"}, {"text": "万事", "is_correct": false, "explanation": "声母：wàn shì 与 fàn shì 声母不同（w 与 f），意思是“所有的事”。"}, {"text": "办事", "is_correct": false, "explanation": "声母：bàn shì 与 fàn shì 声母不同（b 与 f），意思是“处理事情”。"}], "explanations": {"范式": "正确：“范式”读作 fàn shì（第四声）。", "凡事": "声调：fán shì（第二声）与 fàn shì（第四声）声调不同，意思是“凡是的事情”。", "万事": "声母：wàn shì 与 fàn shì 声母不同（w 与 f），意思是“所有的事”。", "办事": "声母：bàn shì 与 fàn shì 声母不同（b 与 f），意思是“处理事情”。"}, "sentence_index": null, "correct_answer": "范式"}, "level_3": {"options": [{"text": "大衣", "is_correct": false, "explanation": "语义：大衣不是研究的对象，不符合“研究……”的语境。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗不能作为研究的对象，句中的“新的研究”不能接“饭碗”。"}, {"text": "范式", "is_correct": true, "explanation": "正确：“研究范式”指研究时可以照着做的模式，与“提供了一种新的”搭配。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋不是论文提供的研究方向，与“研究”的语境不符。"}], "explanations": {"大衣": "语义：大衣不是研究的对象，不符合“研究……”的语境。", "饭碗": "语义：饭碗不能作为研究的对象，句中的“新的研究”不能接“饭碗”。", "范式": "正确：“研究范式”指研究时可以照着做的模式，与“提供了一种新的”搭配。", "皮鞋": "语义：皮鞋不是论文提供的研究方向，与“研究”的语境不符。"}, "sentence_index": 0, "correct_answer": "范式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学习了一头范式。", "explanation": "这里应该用〈种〉。〈头〉用于牲畜，“范式”是抽象的样子或模式，应该用〈种〉。"}, {"text": "昨天学校发生了一个范式。", "explanation": "这里应该用〈事件〉。“范式”指可以照着做的样子，不能指发生的事件。"}, {"text": "这个湖的范式很大。", "explanation": "这里应该用〈深度〉。“范式”不能指湖的深浅，它指可以照着做的样子或模式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能被“管理”，与“成功的管理”的语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“管理”，与“成功的管理”的语境不符。"}, {"text": "范式", "is_correct": true, "explanation": "正确：“管理范式”指管理时可以照着做的模式，与“成功的”搭配。"}, {"text": "雨滴", "is_correct": false, "explanation": "语义：雨滴不能被“管理”，与“成功的管理”的语境不符。"}], "explanations": {"饼干": "语义：饼干不能被“管理”，与“成功的管理”的语境不符。", "天气": "语义：天气不能被“管理”，与“成功的管理”的语境不符。", "范式": "正确：“管理范式”指管理时可以照着做的模式，与“成功的”搭配。", "雨滴": "语义：雨滴不能被“管理”，与“成功的管理”的语境不符。"}, "sentence_index": 6, "correct_answer": "范式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班买了一台范式。", "explanation": "这里应该用〈种〉。〈台〉用于机器，“范式”是抽象的模式，量词不对。"}, {"text": "他把范式吃了下去。", "explanation": "这里“范式”用错了：它是抽象的样子或模式，不是能吃的具体东西，不能说“吃了范式”。"}, {"text": "这个范式跑得很快。", "explanation": "这里“范式”用错了：它是抽象的样子或模式，不是能跑的具体事物，“跑得很快”只能用于人或物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书给我们提供了一只写作的范式。", "corrected_sentence": "这本书给我们提供了一种写作的范式。", "error_description": "量词错误：“范式”是抽象的模式，量词应为“种”，“只”用于动物或小件物品，应说“一种写作的范式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员找到了一个新地范式。", "corrected_sentence": "研究人员找到了一个新的范式。", "error_description": "结构助词错误：修饰名词“范式”的定语要用“的”，“地”用于修饰动词，应说“一个新的范式”，不能说“新地范式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遗忘", "is_correct": true, "explanation": "正确：“遗忘”与“记忆”相对，指忘掉过去的事情和印象。"}, {"text": "桌子", "is_correct": false, "explanation": "无反义关系：“桌子”是家具，与“记忆”不是相对的概念。"}, {"text": "河流", "is_correct": false, "explanation": "无反义关系：“河流”是自然事物，与“记忆”不是相对的概念。"}, {"text": "理想", "is_correct": false, "explanation": "无反义关系：“理想”指对未来的追求，与“记忆”指过去的印象不构成相对。"}], "correct_answer": "遗忘", "explanations": {"遗忘": "正确：“遗忘”与“记忆”相对，指忘掉过去的事情和印象。", "桌子": "无反义关系：“桌子”是家具，与“记忆”不是相对的概念。", "河流": "无反义关系：“河流”是自然事物，与“记忆”不是相对的概念。", "理想": "无反义关系：“理想”指对未来的追求，与“记忆”指过去的印象不构成相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遗忘", "is_correct": true, "explanation": "正确：“遗忘”与“记忆”相对，指忘掉过去的事情和印象。"}, {"text": "石头", "is_correct": false, "explanation": "无反义关系：“石头”是自然物，与“记忆”不是相对的概念。"}, {"text": "窗户", "is_correct": false, "explanation": "无反义关系：“窗户”是建筑部件，与“记忆”不是相对的概念。"}, {"text": "音乐", "is_correct": false, "explanation": "无反义关系：“音乐”是艺术形式，与“记忆”不是相对的概念。"}], "correct_answer": "遗忘", "explanations": {"遗忘": "正确：“遗忘”与“记忆”相对，指忘掉过去的事情和印象。", "石头": "无反义关系：“石头”是自然物，与“记忆”不是相对的概念。", "窗户": "无反义关系：“窗户”是建筑部件，与“记忆”不是相对的概念。", "音乐": "无反义关系：“音乐”是艺术形式，与“记忆”不是相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记忆就是脑子里记住的东西。", "primary_collocate": null, "pronunciation": "jì yì", "ipa": "tɕi˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "我对小时候的记忆很少。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首老歌唤起了我很多童年的记忆。", "target_word": "记忆", "complexity_tier": "T3", "furigana": "zhè shǒu lǎo gē huànqǐ le wǒ hěn duō tóngnián de jìyì。", "sentence_source": "generated"}, {"text": "这是我最美好的记忆。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这段记忆写进了日记里。", "target_word": "记忆", "complexity_tier": "T3", "furigana": "wǒ bǎ zhè duàn jìyì xiě jìn le rìjì lǐ。", "sentence_source": "generated"}, {"text": "那次旅行给我留下了深刻的记忆。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的记忆里还有那条老街。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片是我们共同的记忆。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的记忆有点乱，想不起来了。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那段痛苦的记忆，他一直不愿提起。", "target_word": "记忆", "complexity_tier": "T3", "furigana": "nà duàn tòngkǔ de jìyì, tā yìzhí bú yuàn tíqǐ。", "sentence_source": "generated"}, {"text": "小城的春天是我童年的记忆。", "target_word": "记忆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "记忆力", "label": "复合"}, {"form": "童年记忆", "label": "复合"}, {"form": "记忆犹新", "label": "复合"}], "register": "中性", "sense_fingerprint": "脑子里保存下来的过去的事情和印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记忆", "is_correct": true, "explanation": "正确：记忆（jì yì）指脑子里保存下来的过去的事情和印象。"}, {"text": "极易", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，极易意思是非常容易。"}, {"text": "致意", "is_correct": false, "explanation": "zh 与 j 声母不同，致意意思是向人表示问候或敬意。"}, {"text": "利益", "is_correct": false, "explanation": "l 与 j 声母不同，利益意思是好处或益处。"}], "explanations": {"记忆": "正确：记忆（jì yì）指脑子里保存下来的过去的事情和印象。", "极易": "jí（第二声）与 jì（第四声）声调不同，极易意思是非常容易。", "致意": "zh 与 j 声母不同，致意意思是向人表示问候或敬意。", "利益": "l 与 j 声母不同，利益意思是好处或益处。"}, "sentence_index": null, "correct_answer": "记忆"}, "level_3": {"options": [{"text": "记忆", "is_correct": true, "explanation": "正确：“记忆”指对小时候事情的印象，与“很少”搭配，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体型特征，不能说对小时候的身高“很少”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很少”修饰数量或印象，不能修饰“价格”。"}, {"text": "身份证", "is_correct": false, "explanation": "语义：“身份证”是证件，与“小时候的记忆”不同类，句意不通。"}], "explanations": {"记忆": "正确：“记忆”指对小时候事情的印象，与“很少”搭配，句意通顺。", "身高": "体貌：“身高”是人的体型特征，不能说对小时候的身高“很少”。", "价格": "搭配：“很少”修饰数量或印象，不能修饰“价格”。", "身份证": "语义：“身份证”是证件，与“小时候的记忆”不同类，句意不通。"}, "sentence_index": 0, "correct_answer": "记忆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心里有一颗深刻的记忆。", "explanation": "量词“颗”多用于圆粒状的东西，记忆这类抽象的过去印象应当用“段”。"}, {"text": "他每天认真做记忆。", "explanation": "这里应该用〈功课〉。做是指完成学习任务，记忆是保存下来的印象，不能说“做记忆”。"}, {"text": "他把记忆剪短了。", "explanation": "这里应该用〈头发〉。剪的是有形的东西，记忆是脑子里的印象，不能剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记忆", "is_correct": true, "explanation": "正确：“记忆”指共同经历留下的印象，与“共同的”相合，句意通顺。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，照片不能是“共同的工资”。"}, {"text": "公寓", "is_correct": false, "explanation": "语义：“公寓”是住所，照片不能成为“共同的公寓”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，与句中照片承载的共同经历不相干。"}], "explanations": {"记忆": "正确：“记忆”指共同经历留下的印象，与“共同的”相合，句意通顺。", "工资": "语义：“工资”是劳动报酬，照片不能是“共同的工资”。", "公寓": "语义：“公寓”是住所，照片不能成为“共同的公寓”。", "身材": "体貌：“身材”指人的体型，与句中照片承载的共同经历不相干。"}, "sentence_index": 6, "correct_answer": "记忆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨晚我做了一个奇怪的记忆。", "explanation": "这里应该用〈梦〉。做梦指睡眠中的幻象，记忆是保存下来的过去，不能说“做记忆”。"}, {"text": "我每天早上喝一杯记忆。", "explanation": "这里应该用〈茶〉。喝的是饮品，记忆是脑子里记住的东西，不能拿来喝。"}, {"text": "山谷里传来了记忆。", "explanation": "这里应该用〈回音〉。从山谷传来的是声音，记忆不是声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本童年的记忆让我很怀念。", "corrected_sentence": "这段童年的记忆让我很怀念。", "error_description": "错误形式：“这本”；正确形式：“这段”。量词“本”用于书册，“记忆”应当用量词“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我常常想起那段童年的记忆的。", "corrected_sentence": "我常常想起那段童年的记忆。", "error_description": "错误形式：句末多出“的”；正确形式：“我常常想起那段童年的记忆。”“记忆”是句子的中心语，句末不应再接“的”，去掉多余的“的”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
