INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一条线，把两个地方分开的地方。", "primary_collocate": null, "pronunciation": "biān jiè", "ipa": "pjɛn˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这条河是两个国家的边界。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开车到了边界，下车看了看。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的那边是两个省的边界。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界上有一道很高的墙。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的边界是一条红线。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在边界附近住了很多年。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过边界时，请带好护照。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个城市的边界在河边。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是边界，前面就是别的国家了。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界两边的人说话不一样。", "target_word": "边界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条边界", "label": "量词"}, {"form": "边界线", "label": "复合"}], "register": "中性", "sense_fingerprint": "两个地方、国家或区域之间的分界线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "边界", "is_correct": true, "explanation": "正确。边界指两个地方之间的分界线。"}, {"text": "便捷", "is_correct": false, "explanation": "biàn jié 与 biān jiè 的声调都不同（biàn 第四声，jié 第二声），意思是方便快捷。"}, {"text": "编结", "is_correct": false, "explanation": "biān jié 与 biān jiè 的第二个音节声调不同（jié 第二声），意思是编织打结。"}, {"text": "编辑", "is_correct": false, "explanation": "biān jí 与 biān jiè 的第二个音节韵母和声调都不同，意思是修改整理文稿。"}], "explanations": {"边界": "正确。边界指两个地方之间的分界线。", "便捷": "biàn jié 与 biān jiè 的声调都不同（biàn 第四声，jié 第二声），意思是方便快捷。", "编结": "biān jié 与 biān jiè 的第二个音节声调不同（jié 第二声），意思是编织打结。", "编辑": "biān jí 与 biān jiè 的第二个音节韵母和声调都不同，意思是修改整理文稿。"}, "sentence_index": null, "correct_answer": "边界"}, "level_3": {"options": [{"text": "城市", "is_correct": false, "explanation": "语义：“城市”指人口聚居的地方，与“这条河”所指的分界事物不符。"}, {"text": "首都", "is_correct": false, "explanation": "搭配：“首都”是一个国家的政治中心，不能用在两个国家之间的分界上。"}, {"text": "语言", "is_correct": false, "explanation": "语义：河是地理事物，不能是“语言”。"}, {"text": "边界", "is_correct": true, "explanation": "正确：“边界”指两个国家之间的分界线，与“这条河”相符。"}], "explanations": {"城市": "语义：“城市”指人口聚居的地方，与“这条河”所指的分界事物不符。", "首都": "搭配：“首都”是一个国家的政治中心，不能用在两个国家之间的分界上。", "语言": "语义：河是地理事物，不能是“语言”。", "边界": "正确：“边界”指两个国家之间的分界线，与“这条河”相符。"}, "sentence_index": 0, "correct_answer": "边界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的修养已经达到了很高的边界。", "explanation": "这里应该用〈境界〉。边界指地域或事物之间的分界线，修养、学问达到的程度要用“境界”。"}, {"text": "这次会议的边界是下午三点。", "explanation": "这里应该用〈截止〉。边界指空间上两地之间的分界，表示时间的终点要说“截止”或“结束”。"}, {"text": "桌子的边界上放着一杯水。", "explanation": "这里应该用〈边上〉。边界指两个地方之间的分界线，桌子等物体的边缘要说“边上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边界", "is_correct": true, "explanation": "正确：“过边界”指越过两国的分界线，需要检查护照。"}, {"text": "公园", "is_correct": false, "explanation": "语义：过公园一般不需要检查护照，与“护照”的语境不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是需要核验护照的地方，与“护照”的语境冲突。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“过”多用于穿越路段或关口，不说“过房间”，应说“进房间”。"}], "explanations": {"边界": "正确：“过边界”指越过两国的分界线，需要检查护照。", "公园": "语义：过公园一般不需要检查护照，与“护照”的语境不符。", "厨房": "语义：厨房不是需要核验护照的地方，与“护照”的语境冲突。", "房间": "搭配：“过”多用于穿越路段或关口，不说“过房间”，应说“进房间”。"}, "sentence_index": 6, "correct_answer": "边界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子的边界有一个小缺口。", "explanation": "这里应该用〈杯沿〉。边界指两个地方之间的分界线，杯子的边缘要说“杯沿”。"}, {"text": "这把刀的边界很锋利，小心别割伤手。", "explanation": "这里应该用〈刀刃〉。边界指地域之间的分界线，刀的锋利部分要说“刀刃”。"}, {"text": "这块地板的边界翘起来了，需要重新钉牢。", "explanation": "这里应该用〈边角〉。边界指两地之间的分界线，地板的角落要说“边角”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个省之间有一只很长的边界。", "corrected_sentence": "两个省之间有一条很长的边界。", "error_description": "量词错误：“边界”是一条线状的分界，应该用量词“条”（一条边界），不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在地图上把边界划了好。", "corrected_sentence": "他们在地图上把边界划好了。", "error_description": "补语位置错误：结果补语“好”应紧接动词“划”，句末再用“了”，应说“划好了”，不能说“划了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
