INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人在一起，像一家人一样。", "primary_collocate": null, "pronunciation": "jí tǐ", "ipa": "tɕi˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们班是一个很团结的集体。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很热爱我们这个集体。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人要为集体着想。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在集体里，大家互相帮助。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚进这个集体，还不认识人。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集体的力量比一个人大。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，要爱护我们的集体。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个集体里的每个人都很努力。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为集体拿了第一名。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想为这个集体做点事。", "target_word": "集体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "集體", "label": "繁体"}], "register": "通用", "sense_fingerprint": "许多人组成的、互相关心的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b05fab6d-52c3-4f0b-9cb0-3e12924a3383') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集体", "is_correct": true, "explanation": "“集体”指许多人组成的整体，与“很团结”的说法相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手是竞争关系，与“很团结”相反。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人与“团结”的意思相反。"}, {"text": "个人", "is_correct": false, "explanation": "搭配：“团结”说的是群体，不能用来修饰个人。"}], "explanations": {"集体": "“集体”指许多人组成的整体，与“很团结”的说法相符。", "对手": "语义：对手是竞争关系，与“很团结”相反。", "敌人": "语义：敌人与“团结”的意思相反。", "个人": "搭配：“团结”说的是群体，不能用来修饰个人。"}, "sentence_index": 0, "correct_answer": "集体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他集体去了图书馆。", "explanation": "这里应该用〈单独〉。集体指许多人一起，他一个人去，不能用“集体”。"}, {"text": "这家餐厅的集体很好吃，大家都爱去。", "explanation": "这里应该用〈饭菜〉。饭菜是具体的食物，可以好吃；集体指许多人组成的整体，不能用来形容食物的味道。"}, {"text": "他是我最好的集体。", "explanation": "这里应该用〈朋友〉。朋友指一个人，集体是许多人组成的整体，不能指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集体", "is_correct": true, "explanation": "“集体”指群体，是“爱护”的对象，与句子相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不值得爱护，与“爱护”的感情不合。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：仇人与“爱护”的感情正好相反。"}, {"text": "污垢", "is_correct": false, "explanation": "搭配：“爱护”的对象一般是人或物，不能用于污垢。"}], "explanations": {"集体": "“集体”指群体，是“爱护”的对象，与句子相符。", "垃圾": "语义：垃圾不值得爱护，与“爱护”的感情不合。", "仇人": "语义：仇人与“爱护”的感情正好相反。", "污垢": "搭配：“爱护”的对象一般是人或物，不能用于污垢。"}, "sentence_index": 6, "correct_answer": "集体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们是一对恩爱的集体。", "explanation": "这里应该用〈夫妻〉。夫妻指两个人，集体指许多人组成的整体，不能用“一对”来计量。"}, {"text": "他是我的好集体。", "explanation": "这里应该用〈同学〉。同学指一个人，集体是许多人组成的整体，不能指一个人。"}, {"text": "他一个人住，常常觉得很集体。", "explanation": "这里应该用〈孤独〉。集体指许多人组成的整体，不能用来形容一个人的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一位很有活力的集体。", "corrected_sentence": "这是一个很有活力的集体。", "error_description": "量词错误：“集体”是许多人组成的整体，应用量词“个”。“位”只用于单个的人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多集体们都在努力改善生活。", "corrected_sentence": "很多集体都在努力改善生活。", "error_description": "“集体”是集合名词，后面不能加“们”。“很多”已表示数量，直接说“很多集体”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结实", "is_correct": true, "explanation": "反义：“结实”指东西不容易坏，与“脆弱”相对，正好说明旧纸要小心拿。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌好看，与“脆弱”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”指明白或分明，与“脆弱”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "无关：“温暖”指温度或感觉舒服，与“脆弱”没有反义关系。"}], "correct_answer": "结实", "explanations": {"结实": "反义：“结实”指东西不容易坏，与“脆弱”相对，正好说明旧纸要小心拿。", "漂亮": "无关：“漂亮”形容外貌好看，与“脆弱”没有反义关系。", "清楚": "无关：“清楚”指明白或分明，与“脆弱”没有反义关系。", "温暖": "无关：“温暖”指温度或感觉舒服，与“脆弱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚强", "is_correct": true, "explanation": "反义：“坚强”指意志或身体不易被打倒，与“脆弱”相对。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”形容好看，与“脆弱”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”指光线充足或发亮，与“脆弱”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：“热闹”形容人多、有声音，与“脆弱”没有反义关系。"}], "correct_answer": "坚强", "explanations": {"坚强": "反义：“坚强”指意志或身体不易被打倒，与“脆弱”相对。", "美丽": "无关：“美丽”形容好看，与“脆弱”没有反义关系。", "明亮": "无关：“明亮”指光线充足或发亮，与“脆弱”没有反义关系。", "热闹": "无关：“热闹”形容人多、有声音，与“脆弱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西容易坏，或者人心理不坚强、经不起打击。", "primary_collocate": null, "pronunciation": "cuì ruò", "ipa": "tsʰweɪ˥˩ ʐwo˥˩", "syllable_count": 2, "sentences": [{"text": "玻璃杯很脆弱。", "target_word": "脆弱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的心很脆弱。", "target_word": "脆弱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她看起来很脆弱。", "target_word": "脆弱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "旧纸很脆弱，请小心拿。", "target_word": "脆弱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "生病的时候，人会变得脆弱。", "target_word": "脆弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟的骨头非常脆弱。", "target_word": "脆弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他太脆弱了，一点小事就哭。", "target_word": "脆弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些花很脆弱，别用力碰。", "target_word": "脆弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的身体很脆弱，要多休息。", "target_word": "脆弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他表面很平静，心里却很脆弱。", "target_word": "脆弱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：东西不结实容易坏，或人的心理不坚强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "正确：脆弱表示东西容易坏，玻璃杯正是这样。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容人的品质，玻璃杯不能勇敢。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指人想吃东西，玻璃杯不会饿。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”形容人或动物的身体结实，不用来说玻璃杯。"}], "explanations": {"脆弱": "正确：脆弱表示东西容易坏，玻璃杯正是这样。", "勇敢": "语义：“勇敢”形容人的品质，玻璃杯不能勇敢。", "饿": "语义：“饿”指人想吃东西，玻璃杯不会饿。", "健壮": "语义：“健壮”形容人或动物的身体结实，不用来说玻璃杯。"}, "sentence_index": 0, "correct_answer": "脆弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字写得很脆弱。", "explanation": "这里应该用〈工整〉。脆弱形容东西易坏或人心理不坚强，不用来说字迹的整齐。"}, {"text": "这道题很脆弱。", "explanation": "这里应该用〈简单〉。脆弱不用来形容题目的难易。"}, {"text": "这碗饭很脆弱。", "explanation": "这里应该用〈软〉。脆弱不用来形容饭的软硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "正确：脆弱形容人容易哭、心理不坚强，与“一点小事就哭”相符。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”形容人遇事镇定，与“一点小事就哭”矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人风趣，与“一点小事就哭”矛盾，句子说不通。"}, {"text": "刚毅", "is_correct": false, "explanation": "语义：“刚毅”指意志坚定、不软弱，与“一点小事就哭”矛盾。"}], "explanations": {"脆弱": "正确：脆弱形容人容易哭、心理不坚强，与“一点小事就哭”相符。", "冷静": "语义：“冷静”形容人遇事镇定，与“一点小事就哭”矛盾。", "幽默": "语义：“幽默”形容人风趣，与“一点小事就哭”矛盾，句子说不通。", "刚毅": "语义：“刚毅”指意志坚定、不软弱，与“一点小事就哭”矛盾。"}, "sentence_index": 6, "correct_answer": "脆弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块牛排很脆弱。", "explanation": "这里应该用〈嫩〉。说肉质柔软用“嫩”，脆弱不用来形容肉的口感。"}, {"text": "这杯茶很脆弱。", "explanation": "这里应该用〈烫〉。脆弱不用来形容茶的温度。"}, {"text": "这个笑话很脆弱。", "explanation": "这里应该用〈好笑〉。脆弱不用来形容笑话的效果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种瓷器太很脆弱。", "corrected_sentence": "这种瓷器很脆弱。", "error_description": "程度副词叠用：“太”和“很”不能同时修饰形容词，应只用一个，说“这种瓷器很脆弱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种玻璃脆弱很，搬运时要小心。", "corrected_sentence": "这种玻璃脆弱得很，搬运时要小心。", "error_description": "补语结构错误：程度补语要用“得”连接，应说“脆弱得很”，不能说“脆弱很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
