INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21046, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "再做一次。", "primary_collocate": null, "pronunciation": "chóng xīn", "ipa": "ʈʂʰʊŋ˧˥ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "这个字写错了，我要重新写。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，我只好重新买一个。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，请重新开机。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业不对，老师让我重新做。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到新城市，重新开始生活。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表错了，请重新填。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜太咸了，妈妈重新做了一道菜。", "target_word": "重新", "complexity_tier": "T3", "furigana": "chóngxīn", "sentence_source": "generated"}, {"text": "比赛没有结果，明天重新比。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到门口，重新检查了一遍房间。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太乱，我们重新放了桌子。", "target_word": "重新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示把做过的事再从头做一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重新", "is_correct": true, "explanation": "正确答案：重新，意思是再做一次。"}, {"text": "同心", "is_correct": false, "explanation": "tóng 与 chóng 声母不同（t 与 ch），整词意思是“心意一致”。"}, {"text": "重现", "is_correct": false, "explanation": "xiàn 与 xīn 韵母和声调都不同（多一个 a，且为第四声），整词意思是“再次出现”。"}, {"text": "重心", "is_correct": false, "explanation": "zhòng 与 chóng 声母和声调都不同，整词意思是“物体重量集中的一点”。"}], "explanations": {"重新": "正确答案：重新，意思是再做一次。", "同心": "tóng 与 chóng 声母不同（t 与 ch），整词意思是“心意一致”。", "重现": "xiàn 与 xīn 韵母和声调都不同（多一个 a，且为第四声），整词意思是“再次出现”。", "重心": "zhòng 与 chóng 声母和声调都不同，整词意思是“物体重量集中的一点”。"}, "sentence_index": null, "correct_answer": "重新"}, "level_3": {"options": [{"text": "重新", "is_correct": true, "explanation": "“重新”表示再从头做一次，符合“写错了，要再写一遍”的语境。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求两人以上共同做事，自己改正错字不能说一起写。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗中做，改正错字并不需要隐瞒。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意去做，与“写错了”后再改正的语境相反。"}], "explanations": {"重新": "“重新”表示再从头做一次，符合“写错了，要再写一遍”的语境。", "一起": "搭配：“一起”要求两人以上共同做事，自己改正错字不能说一起写。", "偷偷": "语义：“偷偷”表示暗中做，改正错字并不需要隐瞒。", "故意": "语义：“故意”表示有意去做，与“写错了”后再改正的语境相反。"}, "sentence_index": 0, "correct_answer": "重新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从没学过这个字，却重新写了一遍。", "explanation": "“从没学过”说明之前从未写过，与“重新”（再做一次）相矛盾，应去掉“重新”。"}, {"text": "他一直在北京工作，却重新搬到了北京。", "explanation": "“一直在北京工作”说明他没有离开过，与“重新搬到”（再次搬入）相矛盾，应去掉“重新”。"}, {"text": "他刚搬来，就重新住进了这栋楼。", "explanation": "“刚搬来”说明他是首次住进这栋楼，与“重新”（再做一次）相矛盾，应去掉“重新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重新", "is_correct": true, "explanation": "“重新”表示把菜再从头做一次，符合“菜太咸了”后重做的语境。"}, {"text": "一块儿", "is_correct": false, "explanation": "搭配：“一块儿”要求两人以上共同做，妈妈一个人做菜不能说一块儿。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示很少发生，与“菜太咸了”后马上做的语境不符。"}, {"text": "千万", "is_correct": false, "explanation": "语法：「千万」用于劝告、叮嘱（如「千万别忘了」），不能用来叙述已经做了的事。"}], "explanations": {"重新": "“重新”表示把菜再从头做一次，符合“菜太咸了”后重做的语境。", "一块儿": "搭配：“一块儿”要求两人以上共同做，妈妈一个人做菜不能说一块儿。", "偶尔": "语义：“偶尔”表示很少发生，与“菜太咸了”后马上做的语境不符。", "千万": "语法：「千万」用于劝告、叮嘱（如「千万别忘了」），不能用来叙述已经做了的事。"}, "sentence_index": 6, "correct_answer": "重新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从没结过婚，却重新结了婚。", "explanation": "“从没结过婚”说明之前未曾结过婚，与“重新”（再做一次）相矛盾，应去掉“重新”。"}, {"text": "这颗星星是刚发现的，天文学家却重新发现了它。", "explanation": "“刚发现”说明此前未曾被发现，与“重新发现”（再次发现）相矛盾，应去掉“重新”。"}, {"text": "这家餐厅刚开业，就重新开业了。", "explanation": "“刚开业”说明餐厅此前未营业过，与“重新开业”（再次开业）相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告的数据错了，我要的重新算一遍。", "corrected_sentence": "这份报告的数据错了，我要重新算一遍。", "error_description": "错误：“我要的重新算一遍”，“的”多余。正确：“我要重新算一遍”。“重新”是副词，修饰动词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把房间的重新布置了。", "corrected_sentence": "他们把房间重新布置了。", "error_description": "错误：“把房间的重新布置了”，“重新”前面多加了“的”。正确：“把房间重新布置了”。“重新”是副词，修饰动词，前面不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
