INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "认知就是你知道和了解东西。", "primary_collocate": null, "pronunciation": "rèn zhī", "ipa": "ʐən˥˩ ʈʂɨ˥", "syllable_count": 2, "sentences": [{"text": "孩子的认知能力会慢慢提高。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书可以改变我们对世界的认知。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让我对他有了新的认知。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩对颜色的认知从两岁开始。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的认知很清楚。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行能帮助我们加深对不同文化的认知。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，认知水平不同，学习方法也不同。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人对这种病的认知还不够。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了这本书，我对历史的认知多了一些。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年龄越大，人对生活的认知越深。", "target_word": "认知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "認知", "label": "繁体"}, {"form": "认知能力", "label": "复合"}, {"form": "认知水平", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事物的知道和了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b26b9a-9d68-4360-8cd8-e1c05a934069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认知", "is_correct": true, "explanation": "“认知能力”指认识、理解事物的能力，与“能力”搭配自然，句子通顺。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”指视觉的清晰度，不说“视力能力”，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高度，与“能力”无关，“身高能力”说不通。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”指书写的痕迹，不是能力，“字迹能力”句意不通。"}], "explanations": {"认知": "“认知能力”指认识、理解事物的能力，与“能力”搭配自然，句子通顺。", "视力": "搭配：“视力”指视觉的清晰度，不说“视力能力”，句子不通。", "身高": "语义：“身高”指身体的高度，与“能力”无关，“身高能力”说不通。", "字迹": "语义：“字迹”指书写的痕迹，不是能力，“字迹能力”句意不通。"}, "sentence_index": 0, "correct_answer": "认知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们学了很多数学认知。", "explanation": "这里应该用〈知识〉。“学”的对象是知识，认知指认识、理解事物的能力或过程，不能说“学认知”。"}, {"text": "他的行动表明他有一条新的认知。", "explanation": "这里量词应该用〈种〉（一种认知）。“条”用于细长的东西，不能用来数“认知”。"}, {"text": "她掌握了很多医学认知。", "explanation": "这里应该用〈常识〉。“掌握”的对象是常识或知识，“认知”不能这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认知", "is_correct": true, "explanation": "“认知水平”指认识和理解事物的能力高低，与“水平”搭配，句意通顺。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“水平”用于能力或程度，不说“脾气水平”，句子不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不与“水平”搭配，不说“性格水平”，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指体形，与“学习方法”无关，句意不通。"}], "explanations": {"认知": "“认知水平”指认识和理解事物的能力高低，与“水平”搭配，句意通顺。", "脾气": "搭配：“水平”用于能力或程度，不说“脾气水平”，句子不通。", "性格": "搭配：“性格”不与“水平”搭配，不说“性格水平”，句子不通。", "身材": "语义：“身材”指体形，与“学习方法”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "认知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小在国外长大，认知很广。", "explanation": "这里应该用〈见识〉。“很广”修饰“见识”（见识广），“认知”不说“认知很广”。"}, {"text": "他经历了很多事，认知丰富。", "explanation": "这里应该用〈阅历〉。“丰富”修饰“阅历”（阅历丰富），“认知”不这样搭配。"}, {"text": "他对历史有一块认知。", "explanation": "这里量词应该用〈种〉（一种认知）。“块”用于成块的东西，不能用来数“认知”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习心理学让我对自己有了一片更清楚的认知。", "corrected_sentence": "学习心理学让我对自己有了一种更清楚的认知。", "error_description": "量词错误：“认知”应用量词“种”（一种认知），不能用“片”。“片”用于面状或平展的东西，“一片认知”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对历史有了更深地认知。", "corrected_sentence": "他对历史有了更深的认知。", "error_description": "结构助词错误：“更深”修饰名词“认知”，应该用“的”，不能用“地”。“地”用来修饰动词，所以要说“更深的认知”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取出", "is_correct": true, "explanation": "反义：“储存”是放入留用，“取出”是把放好的东西拿出来，二者互为相反的动作。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是快速移动身体，与“储存”没有反义关系。"}, {"text": "缝补", "is_correct": false, "explanation": "“缝补”是用针线修补衣物，与“储存”没有反义关系。"}, {"text": "争论", "is_correct": false, "explanation": "“争论”是各自表达不同意见，与“储存”在任何义项上都不构成反义。"}], "correct_answer": "取出", "explanations": {"取出": "反义：“储存”是放入留用，“取出”是把放好的东西拿出来，二者互为相反的动作。", "跑步": "“跑步”是快速移动身体，与“储存”没有反义关系。", "缝补": "“缝补”是用针线修补衣物，与“储存”没有反义关系。", "争论": "“争论”是各自表达不同意见，与“储存”在任何义项上都不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取用", "is_correct": true, "explanation": "反义：“储存”是放好备用，“取用”是把存放的东西拿来使用，二者是相反的动作。"}, {"text": "打扫", "is_correct": false, "explanation": "“打扫”是清除脏物，与“储存”没有反义关系。"}, {"text": "说话", "is_correct": false, "explanation": "“说话”是用语言表达意思，与“储存”没有反义关系。"}, {"text": "烧水", "is_correct": false, "explanation": "“烧水”是把水加热，与“储存”在任何义项上都没有反义关系。"}], "correct_answer": "取用", "explanations": {"取用": "反义：“储存”是放好备用，“取用”是把存放的东西拿来使用，二者是相反的动作。", "打扫": "“打扫”是清除脏物，与“储存”没有反义关系。", "说话": "“说话”是用语言表达意思，与“储存”没有反义关系。", "烧水": "“烧水”是把水加热，与“储存”在任何义项上都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放好留着以后用。", "primary_collocate": null, "pronunciation": "chǔ cún", "ipa": "ʈʂʰu˨˩˦ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶在地下室储存了很多大米。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要储存一些药，家里有事时能用。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "松鼠在秋天储存松子，准备过冬。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间小屋是用来储存工具的。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧书储存在箱子里，以后再看。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的冷库可以储存肉和牛奶。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水可以储存起来浇花。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，他储存了足够的食物。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家储存着一箱面条，不怕下雪。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小店在夏天储存了很多冰。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "储存了", "label": "体标"}, {"form": "储存着", "label": "体标"}, {"form": "储存过", "label": "体标"}, {"form": "儲存", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把食物、物品等放好留着日后使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b7ca80-ae1c-4e7c-a5ec-daf599d2e99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "储存", "is_correct": true, "explanation": "正确：“储存”表示把大米放在地下室备用，与句意相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于农作物，大米是加工后的食物，不能说“种了很多大米”。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”需要阳光，与“地下室”的场所互相矛盾，句意不通。"}, {"text": "发霉", "is_correct": false, "explanation": "配价：“发霉”是不及物动词，不能带“大米”做宾语。"}], "explanations": {"储存": "正确：“储存”表示把大米放在地下室备用，与句意相符。", "种植": "搭配：“种植”用于农作物，大米是加工后的食物，不能说“种了很多大米”。", "晒": "语义：“晒”需要阳光，与“地下室”的场所互相矛盾，句意不通。", "发霉": "配价：“发霉”是不及物动词，不能带“大米”做宾语。"}, "sentence_index": 0, "correct_answer": "储存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份友谊很珍贵，我们要把它储存下去。", "explanation": "这里应该用〈保存〉。储存针对可以放置的物品或信息，友谊这类抽象的东西要说保存下去。"}, {"text": "这一年里，我储存了很多次旅行。", "explanation": "这里应该用〈经历〉。旅行是一次次发生的事，不是可以放好留着用的东西；要说经历。"}, {"text": "这段美好的时光，我想永远储存在箱子里。", "explanation": "这里应该用〈珍藏〉。时光无法装进箱子，不能说“储存在箱子里”；想长久留念要说珍藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "储存", "is_correct": true, "explanation": "正确：“储存起来”表示把雨水存放下来留着浇花，符合句意。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”是白白耗用，与“留着浇花”的用途相反。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：雨水蒸发成水汽散失后就无法用来浇花，与句意矛盾。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”指用来喝，不能与“浇花”搭配表示用途，句子不通。"}], "explanations": {"储存": "正确：“储存起来”表示把雨水存放下来留着浇花，符合句意。", "浪费": "语义：“浪费”是白白耗用，与“留着浇花”的用途相反。", "蒸发": "语义：雨水蒸发成水汽散失后就无法用来浇花，与句意矛盾。", "饮用": "搭配：“饮用”指用来喝，不能与“浇花”搭配表示用途，句子不通。"}, "sentence_index": 6, "correct_answer": "储存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座老房子储存了很多台阶，一点都没变。", "explanation": "这里应该用〈有〉。台阶是建筑本身的结构，不是放进去留着用的东西；储存只用于可以放置、留着备用的物品或信息。"}, {"text": "他从小储存了很好的阅读习惯。", "explanation": "这里应该用〈培养〉。习惯要靠长期练习形成，说培养；储存针对可以放置的东西或信息。"}, {"text": "他一直储存着良好的身体状态，很少生病。", "explanation": "这里应该用〈维持〉。身体状态要靠持续的照顾才能维持，说维持；储存只用于可以放置、留着备用的物品或信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些粮食要储存起，留着过冬。", "corrected_sentence": "这些粮食要储存起来，留着过冬。", "error_description": "补语不完整：趋向补语「起来」缺少「来」，不能只说「储存起」。正确说法是「储存起来」，表示把粮食收存起来留用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车库里储存了着一箱旧书。", "corrected_sentence": "车库里储存着一箱旧书。", "error_description": "体标叠用错误：“了”与“着”不能同时用在动词后，应只用“着”，说“储存着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
