INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21052, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一直做，没有停。", "primary_collocate": null, "pronunciation": "bù duàn", "ipa": "pu˥˩ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "他每天不断练习写汉字。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要不断学习新东西。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨不断地下，路上都是水。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机不断响，他还是不接。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不断努力，成绩越来越好。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不断问问题，妈妈很有耐心。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市不断变大，人也越来越多。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不断地看表，好像在等人。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不断做出新的产品。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友不断给我打电话，我才知道他很着急。", "target_word": "不断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：动作一直进行，没有中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不断", "is_correct": true, "explanation": "正确：“不断”表示动作接连进行、没有停止，与“每天练习”相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指间或发生，与“每天”的习惯性练习矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指事情刚发生，不能与表示习惯的“每天”连用。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去发生过，与“每天”的习惯性练习矛盾。"}], "explanations": {"不断": "正确：“不断”表示动作接连进行、没有停止，与“每天练习”相符。", "偶尔": "语义：“偶尔”指间或发生，与“每天”的习惯性练习矛盾。", "刚刚": "语义：“刚刚”指事情刚发生，不能与表示习惯的“每天”连用。", "曾经": "语义：“曾经”指过去发生过，与“每天”的习惯性练习矛盾。"}, "sentence_index": 0, "correct_answer": "不断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每月不断去一次银行。", "explanation": "这里应该用〈定期〉。“不断”表示接连不停、没有间隔；每月去一次有固定间隔，要用“定期”。"}, {"text": "这根绳子很结实，拉了半天都不断。", "explanation": "这里的“不断”是“没有断开”的意思，指绳子没有断裂；本词“持续不停”的用法不是这个意思。"}, {"text": "我不断去过一次那家医院。", "explanation": "这里应该用〈曾经〉。“不断”表示接连不停，只发生过一次的过去经历要说“曾经去过”，不能用“不断”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不断", "is_correct": true, "explanation": "正确：“不断”表示持续变化，与“越来越多”的增长趋势相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去发生过，与仍在进行的变化趋势不合。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”指偶尔发生，与“越来越多”的持续增长矛盾。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“越来越多”所描述的持续变化矛盾。"}], "explanations": {"不断": "正确：“不断”表示持续变化，与“越来越多”的增长趋势相符。", "曾经": "语义：“曾经”指过去发生过，与仍在进行的变化趋势不合。", "偶然": "语义：“偶然”指偶尔发生，与“越来越多”的持续增长矛盾。", "从未": "语义：“从未”表示从来没有，与“越来越多”所描述的持续变化矛盾。"}, "sentence_index": 6, "correct_answer": "不断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子不断很大。", "explanation": "这里应该用〈一直〉。“不断”只修饰表示动作或变化的动词，描述状态的“很大”不能与之搭配；“一直”可以用于状态。"}, {"text": "他不断来我家借书，每年只来一次。", "explanation": "这里应该用〈偶尔〉。“不断”表示接连不停，后面的“每年只来一次”是间隔很长的情况，二者矛盾；这种间或发生的事要用“偶尔”。"}, {"text": "她不断去看望外婆，一次也没去过。", "explanation": "这里应该用〈从未〉。“不断”表示接连不停，“一次也没去过”说明从未发生，二者矛盾；这里应表达为“从未去看望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们不断得搬货，很辛苦。", "corrected_sentence": "工人们不断地搬货，很辛苦。", "error_description": "助词错误：修饰动词的状语“不断”后应用“地”，写成“得”是错的；“得”用于动词或形容词之后引出补语。正确写法为“不断地搬货”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师不断了提醒我们注意安全。", "corrected_sentence": "老师不断提醒我们注意安全。", "error_description": "助词错误：副词“不断”后不能直接加“了”，“了”表示完成，与“不断”的持续义不合，且“不断”作状语时不带“了”。正确为“老师不断提醒我们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
