INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声音出去后又回来。", "primary_collocate": null, "pronunciation": "huí xiǎng", "ipa": "xu̯eɪ˧˥ ɕi̯ɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他对着山谷大喊，声音在山里回响。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大教堂里，钟声一遍遍回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在空房间里大声说话，声音会在墙壁间回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山洞很深，我们的笑声一直在洞里回响。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喊完之后，山谷里的声音很快又回响起来。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车经过时，声音在长长的通道里回响。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声在大厅里回响着。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对着井口喊一声，声音会在井里回响。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜很静，远处的狗叫声在山间回响。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室很小，唱歌时声音回响得特别厉害。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回响着", "label": "体标"}, {"form": "回响了", "label": "体标"}, {"form": "回响过", "label": "体标"}, {"form": "回響", "label": "繁体"}], "register": "中性", "sense_fingerprint": "回响：声音发出后遇到墙壁或山壁，又传回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3701140-a2a2-4137-8b61-b34e446ee27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回响", "is_correct": true, "explanation": "正确答案：回响（huí xiǎng），指声音发出后遇到墙壁或山壁又传回来。"}, {"text": "回乡", "is_correct": false, "explanation": "huíxiāng（第一声）与 huíxiǎng（第三声）声调不同，意思是回到家乡。"}, {"text": "回向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是佛教用语“把功德转向他处”。"}, {"text": "回显", "is_correct": false, "explanation": "xiǎn 与 xiǎng 韵母不同（-n 与 -ng），意思是重新显示。"}], "explanations": {"回响": "正确答案：回响（huí xiǎng），指声音发出后遇到墙壁或山壁又传回来。", "回乡": "huíxiāng（第一声）与 huíxiǎng（第三声）声调不同，意思是回到家乡。", "回向": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是佛教用语“把功德转向他处”。", "回显": "xiǎn 与 xiǎng 韵母不同（-n 与 -ng），意思是重新显示。"}, "sentence_index": null, "correct_answer": "回响"}, "level_3": {"options": [{"text": "回响", "is_correct": true, "explanation": "正确答案：“声音在山里回响”指声音碰到山壁后反射回来，与前句“大喊”相合。"}, {"text": "回复", "is_correct": false, "explanation": "语义：“回复”指答复别人，声音不能答复。"}, {"text": "回嘴", "is_correct": false, "explanation": "语域：“回嘴”是口语，指顶撞别人，用来描写山谷声音很不协调。"}, {"text": "回绝", "is_correct": false, "explanation": "语义：“回绝”指拒绝别人的请求或邀约，声音不能拒绝任何人。"}], "explanations": {"回响": "正确答案：“声音在山里回响”指声音碰到山壁后反射回来，与前句“大喊”相合。", "回复": "语义：“回复”指答复别人，声音不能答复。", "回嘴": "语域：“回嘴”是口语，指顶撞别人，用来描写山谷声音很不协调。", "回绝": "语义：“回绝”指拒绝别人的请求或邀约，声音不能拒绝任何人。"}, "sentence_index": 0, "correct_answer": "回响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿饭让我回响无穷。", "explanation": "这里应该用〈回味〉。回味指事后细细体会，回响只用于声音被反射回来。"}, {"text": "妈妈昨天从外地回响了。", "explanation": "这里应该用〈回来〉。回来指人回到原处，回响只指声音被反射回来。"}, {"text": "这次会议我们回响了一年的工作。", "explanation": "这里应该用〈回顾〉。回顾指回头看、总结过去的事，回响只指声音被反射回来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回响", "is_correct": true, "explanation": "正确答案：“歌声在大厅里回响着”指声音在空间中反射传播，符合本义项。"}, {"text": "回头", "is_correct": false, "explanation": "语义：“回头”指转过身，歌声不能转身。"}, {"text": "回击", "is_correct": false, "explanation": "语义：“回击”指还击，歌声不能还击任何人。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”指躲开或避免，歌声不能躲避任何事物。"}], "explanations": {"回响": "正确答案：“歌声在大厅里回响着”指声音在空间中反射传播，符合本义项。", "回头": "语义：“回头”指转过身，歌声不能转身。", "回击": "语义：“回击”指还击，歌声不能还击任何人。", "回避": "语义：“回避”指躲开或避免，歌声不能躲避任何事物。"}, "sentence_index": 6, "correct_answer": "回响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "企业应该回响社会。", "explanation": "这里应该用〈回馈〉。回馈指以实际行动报答社会，回响只用于声音被反射回来。"}, {"text": "他在会上很快回响了大家的意见。", "explanation": "这里应该用〈回应〉。回应指对意见或问题作出答复，回响只指声音被反射回来。"}, {"text": "工厂每周都回响废纸。", "explanation": "这里应该用〈回收〉。回收指把废品收集起来再利用，回响只指声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喊完之后，山谷里的声音一直回响过着。", "corrected_sentence": "喊完之后，山谷里的声音一直回响着。", "error_description": "“过”与“着”不能同时表示同一动作的体，应只用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大厅里的掌声一下子回响下来。", "corrected_sentence": "大厅里的掌声一下子回响起来。", "error_description": "表示“声音开始出现并扩散”要用趋向补语“起来”，说“回响起来”，不说“回响下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "长与短是反义词，指两端距离的长短相反。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与长没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚指物体的厚度，与长不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线，与长没有反义关系。"}], "correct_answer": "短", "explanations": {"短": "长与短是反义词，指两端距离的长短相反。", "快": "快指速度，与长没有反义关系。", "厚": "厚指物体的厚度，与长不构成反义。", "亮": "亮指光线，与长没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "长与短是反义词，指两端距离的长短相反。"}, {"text": "宽", "is_correct": false, "explanation": "宽指宽度，与长不构成反义，宽的反义是窄。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与长没有反义关系。"}, {"text": "暖", "is_correct": false, "explanation": "暖指温度，与长没有反义关系。"}], "correct_answer": "短", "explanations": {"短": "长与短是反义词，指两端距离的长短相反。", "宽": "宽指宽度，与长不构成反义，宽的反义是窄。", "轻": "轻指重量，与长没有反义关系。", "暖": "暖指温度，与长没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西离得很远。", "primary_collocate": null, "pronunciation": "cháng", "ipa": "ʈʂʰaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "从我家到学校的路很长，要坐一个小时车。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路太长了，我走不动了。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个城市之间的路很长，开车要十个小时。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在山的那一边，来一次要走很长的路。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥很长，走过去要十分钟。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河很长，从山里一直流到海边。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁路线很长，从北京一直到广州。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回家的路很长，我们走了一整天。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街不长，两分钟就走完了。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场到市中心的路有点长，最好坐地铁。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "長", "label": "繁体"}, {"form": "长长的", "label": "重叠"}], "register": "通用", "sense_fingerprint": "形容词，读 cháng，指道路、桥、河等两端相距远、空间距离大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长", "is_correct": true, "explanation": "cháng，意思是两个东西之间的距离远。"}, {"text": "唱", "is_correct": false, "explanation": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。"}, {"text": "厂", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。"}, {"text": "成", "is_correct": false, "explanation": "chéng 与 cháng 韵母不同（eng／ang），意思是成功。"}, {"text": "昌", "is_correct": false, "explanation": "chāng（第一声）与 cháng（第二声）只差声调，意思是昌盛。"}], "explanations": {"长": "cháng，意思是两个东西之间的距离远。", "唱": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。", "厂": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。", "成": "chéng 与 cháng 韵母不同（eng／ang），意思是成功。", "昌": "chāng（第一声）与 cháng（第二声）只差声调，意思是昌盛。"}, "sentence_index": null, "correct_answer": "长"}, "level_3": {"options": [{"text": "长", "is_correct": true, "explanation": "长：说两端相距远，与“要坐一个小时车”的句意相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：路不说高矮，“高”与“路”不搭配。"}, {"text": "亮", "is_correct": false, "explanation": "语义：亮形容光线或颜色，与路的远近无关。"}, {"text": "轻", "is_correct": false, "explanation": "语义：轻指重量，与两地之间的距离无关。"}], "explanations": {"长": "长：说两端相距远，与“要坐一个小时车”的句意相符。", "高": "搭配：路不说高矮，“高”与“路”不搭配。", "亮": "语义：亮形容光线或颜色，与路的远近无关。", "轻": "语义：轻指重量，与两地之间的距离无关。"}, "sentence_index": 0, "correct_answer": "长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很长，站在人群里很显眼。", "explanation": "这里应该用〈高〉。长说两端相距远，人的身高要用高。"}, {"text": "这口井很长，打水要很久。", "explanation": "这里应该用〈深〉。长说两端的距离，竖向的深度要用深。"}, {"text": "他家离公司很长，每天要坐地铁。", "explanation": "这里应该用〈远〉。“离……”之后要说“很远”，不说“离……很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "长", "is_correct": true, "explanation": "cháng，意思是两个东西之间的距离远。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 cháng 韵母不同（an／ang），意思是蝉。"}, {"text": "潮", "is_correct": false, "explanation": "cháo 与 cháng 韵母不同（ao／ang），意思是潮水。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong／ang），意思是虫子。"}, {"text": "场", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）只差声调，意思是场地。"}], "explanations": {"长": "cháng，意思是两个东西之间的距离远。", "蝉": "chán 与 cháng 韵母不同（an／ang），意思是蝉。", "潮": "cháo 与 cháng 韵母不同（ao／ang），意思是潮水。", "虫": "chóng 与 cháng 韵母不同（ong／ang），意思是虫子。", "场": "chǎng（第三声）与 cháng（第二声）只差声调，意思是场地。"}, "sentence_index": null, "correct_answer": "长"}, "level_3": {"options": [{"text": "长", "is_correct": true, "explanation": "长：说铁路线两端相距远，与“从北京一直到广州”的句意相符。"}, {"text": "深", "is_correct": false, "explanation": "语义：深指竖向的深度，铁路线不能用深来形容。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：厚形容物体的厚薄，不能说铁路线厚。"}, {"text": "暗", "is_correct": false, "explanation": "体貌：暗形容光线，与铁路线的长短无关。"}], "explanations": {"长": "长：说铁路线两端相距远，与“从北京一直到广州”的句意相符。", "深": "语义：深指竖向的深度，铁路线不能用深来形容。", "厚": "搭配：厚形容物体的厚薄，不能说铁路线厚。", "暗": "体貌：暗形容光线，与铁路线的长短无关。"}, "sentence_index": 6, "correct_answer": "长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的工人很长，需要再招一些。", "explanation": "这里应该用〈多〉。长说两端距离远，人数要用多。"}, {"text": "他的反应很长，大家都在等他。", "explanation": "这里应该用〈慢〉。反应的快慢要用“慢”，“长”不能形容反应。"}, {"text": "这个国家的面积很长。", "explanation": "这里应该用〈大〉。长说两端的距离，面积要用大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座大桥长很，走过去要二十分钟。", "corrected_sentence": "这座大桥很长，走过去要二十分钟。", "error_description": "错误：“长很”，应为“很长”。副词“很”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段山路比那段长得，我们走了两个钟头。", "corrected_sentence": "这段山路比那段长，我们走了两个钟头。", "error_description": "错误：“长得”，应为“长”。“得”引出补语，这里没有补语，应去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
