INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21060, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21060, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度更深，比如“更加”的意思。", "primary_collocate": null, "pronunciation": "gèng shì", "ipa": "kɤŋ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他数学很好，物理更是第一名。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱吃辣，弟弟更是天天吃。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的冬天很冷，哈尔滨更是冷得厉害。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时就很忙，今天更是一刻也没停。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景很美，秋天更是漂亮。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很高兴，孩子们更是又唱又跳。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天本来就热，今年更是热得受不了。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说英语，法语更是说得很好。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很爱看书，哥哥更是书不离手。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的菜好吃，她做的鱼更是好吃。", "target_word": "更是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在已有程度上进一步强调，比前面更加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59cd57e6-a11a-4731-b10a-b0c4705d2478') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更是", "is_correct": true, "explanation": "正确答案：更是，表示在前面的基础上程度更深，「物理更是第一名」指物理比数学还突出。"}, {"text": "只是", "is_correct": false, "explanation": "语义：「只是」表示仅仅，与「数学很好」后的递进语气不合。"}, {"text": "一起", "is_correct": false, "explanation": "语义：「一起」表示共同做某事，不能修饰「是第一名」，「物理一起是第一名」说不通。"}, {"text": "互相", "is_correct": false, "explanation": "语义：「互相」要求两方彼此作用，「物理互相是第一名」说不通。"}], "explanations": {"更是": "正确答案：更是，表示在前面的基础上程度更深，「物理更是第一名」指物理比数学还突出。", "只是": "语义：「只是」表示仅仅，与「数学很好」后的递进语气不合。", "一起": "语义：「一起」表示共同做某事，不能修饰「是第一名」，「物理一起是第一名」说不通。", "互相": "语义：「互相」要求两方彼此作用，「物理互相是第一名」说不通。"}, "sentence_index": 0, "correct_answer": "更是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很贵，书包更是很便宜。", "explanation": "这里应该用〈却〉。「更是」表示程度加深，前后要顺着说，不能用来表示转折。"}, {"text": "他平时不太忙，今天更是很闲。", "explanation": "这里应该用〈也〉或改用顺接句。「更是」要接在已有的明显程度之后加深，「不太忙」程度很弱，用「更是」不自然。"}, {"text": "我今天很开心，更是很难过。", "explanation": "这里误把「更是」当作〈可是〉来用；「更是」表示同方向的程度加深，「开心」与「难过」方向相反，不能连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更是", "is_correct": true, "explanation": "正确答案：更是，表示在「夏天本来就热」的基础上程度更深。"}, {"text": "稍微", "is_correct": false, "explanation": "语义：「稍微」表示程度轻，与「热得受不了」的极端程度矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "语义：「刚」表示刚刚发生，与「夏天本来就热」的程度递进不合。"}, {"text": "略", "is_correct": false, "explanation": "语域：「略」偏书面，表示稍微，与「热得受不了」的程度冲突。"}], "explanations": {"更是": "正确答案：更是，表示在「夏天本来就热」的基础上程度更深。", "稍微": "语义：「稍微」表示程度轻，与「热得受不了」的极端程度矛盾。", "刚": "语义：「刚」表示刚刚发生，与「夏天本来就热」的程度递进不合。", "略": "语域：「略」偏书面，表示稍微，与「热得受不了」的程度冲突。"}, "sentence_index": 6, "correct_answer": "更是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天更是去了超市。", "explanation": "这个词不这么用。这里误把「更是」当作〈还〉来用；「更是」需要前文有可比较的程度，单独一句不能用。"}, {"text": "这条路很宽，更是很窄。", "explanation": "这个词不这么用。这里误把「更是」当作〈偏偏〉来用；「宽」与「窄」方向相反，「更是」只能加深同方向的意思。"}, {"text": "他会游泳，更是不会游泳。", "explanation": "这个词不这么用。这里误把「更是」当作〈其实〉来用；「会游泳」与「不会游泳」互相矛盾，「更是」不能连接这样的句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他汉语说得很好，英语很更是说得很流利。", "corrected_sentence": "他汉语说得很好，英语更是说得很流利。", "error_description": "叠用错误：「很」与「更是」都表示程度，不能叠用，应删去「很」，说「英语更是说得很流利」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的妹妹唱歌很好听，跳舞更是的很厉害。", "corrected_sentence": "我的妹妹唱歌很好听，跳舞更是很厉害。", "error_description": "助词错误：副词「更是」后不能加结构助词「的」，应说「跳舞更是很厉害」，删去「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
