INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把手里没有用的东西丢开。", "primary_collocate": null, "pronunciation": "rēng diào", "ipa": "ɻɤŋ˥ tjɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这些旧报纸可以扔掉了。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把没用的纸条扔掉了。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把旧衣服扔掉，可以送人。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭后，我把垃圾扔掉。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔没水了，扔掉吧。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她舍不得扔掉那双旧鞋。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过期的药要马上扔掉。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩坏的玩具扔掉了。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太乱，我扔掉了很多东西。", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么把这张照片扔掉？", "target_word": "扔掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔掉了", "label": "体标"}, {"form": "扔不掉", "label": "可能补语"}, {"form": "扔", "label": "单音节形式"}], "register": "口语", "sense_fingerprint": "把没有用的东西丢开、不再要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔掉", "is_correct": true, "explanation": "正确。扔掉指把没用的旧报纸丢开，符合“可以……了”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：报纸不能喝，与句中的“旧报纸”冲突。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能与“报纸”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：报纸不能吃，与句中的语境完全不符。"}], "explanations": {"扔掉": "正确。扔掉指把没用的旧报纸丢开，符合“可以……了”的语境。", "喝": "语义：报纸不能喝，与句中的“旧报纸”冲突。", "穿": "搭配：“穿”的对象是衣物，不能与“报纸”搭配。", "吃": "语义：报纸不能吃，与句中的语境完全不符。"}, "sentence_index": 0, "correct_answer": "扔掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他竟然扔掉了多年的朋友。", "explanation": "这里应该用〈抛弃〉。扔掉用于没用的物品，对人要用抛弃。"}, {"text": "这次比赛因为下雨扔掉了。", "explanation": "这里应该用〈取消〉。扔掉指丢弃物品，比赛停办要用取消。"}, {"text": "他把客人扔掉了。", "explanation": "这里应该用〈送走〉。扔掉只用于物品，不能用于客人，请客人离开要用送走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔掉", "is_correct": true, "explanation": "正确。过期的药应当丢弃，扔掉符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或器具，不能与“药”搭配。"}, {"text": "烤", "is_correct": false, "explanation": "语义：药不能烤，烤药与“过期的药要马上……”的处理要求不合。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”针对器物或机器，药不能修理。"}], "explanations": {"扔掉": "正确。过期的药应当丢弃，扔掉符合句意。", "洗": "搭配：“洗”的对象是衣物或器具，不能与“药”搭配。", "烤": "语义：药不能烤，烤药与“过期的药要马上……”的处理要求不合。", "修": "搭配：“修”针对器物或机器，药不能修理。"}, "sentence_index": 6, "correct_answer": "扔掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向空中扔掉了一个球。", "explanation": "这里应该用〈抛〉。扔掉表示丢弃不要的东西，把球抛向空中要用抛。"}, {"text": "她把脸上的汗扔掉了。", "explanation": "这里应该用〈擦掉〉。扔掉指丢弃物品，除去脸上的汗要用擦掉。"}, {"text": "他把书扔掉给了朋友。", "explanation": "这里应该用〈送〉。扔掉表示丢弃不要的东西，把书送给朋友要用送，不能用扔掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那个旧箱子扔掉着。", "corrected_sentence": "他把那个旧箱子扔掉了。", "error_description": "体标错误：句意是动作已经完成，应用动态助词“了”。“着”表示状态的持续，与“扔掉”的完成义不合。错误形式“扔掉着”，正确形式“扔掉了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那个旧箱子扔了掉。", "corrected_sentence": "他把那个旧箱子扔掉了。", "error_description": "错误形式：“扔了掉”；正确形式：“扔掉了”。“掉”是结果补语，“了”应放在“扔掉”之后，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
