INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21066, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21066, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示不需要做某件事。", "primary_collocate": null, "pronunciation": "bù yòng", "ipa": "pu⁵¹ jʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "你不用等我，先走吧。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不用上课，我想在家休息。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很简单，不用担心。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，不用带伞。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我自己来就行，你不用帮我。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有饭，你不用买。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不用谢，这是我应该做的。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是周末，不用早起。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用着急，时间还很多。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有地图，不用问路。", "target_word": "不用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不用了", "label": "体标（了）"}, {"form": "不用说", "label": "复合"}], "register": "口语", "sense_fingerprint": "情态动词，表示没有必要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应该", "is_correct": false, "explanation": "语义：“应该等我”表示必要，与“先走吧”的意思相反。"}, {"text": "不用", "is_correct": true, "explanation": "正确：“不用”表示没有必要，与“先走吧”相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须等我”是强制要求，与“先走吧”冲突。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”后要接表示必须完成的动作，“得等我，先走吧”前后语气矛盾。"}], "explanations": {"应该": "语义：“应该等我”表示必要，与“先走吧”的意思相反。", "不用": "正确：“不用”表示没有必要，与“先走吧”相符。", "必须": "语义：“必须等我”是强制要求，与“先走吧”冲突。", "得": "配价：“得”后要接表示必须完成的动作，“得等我，先走吧”前后语气矛盾。"}, "sentence_index": 0, "correct_answer": "不用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里不用乱扔垃圾，请大家注意。", "explanation": "这里应该用〈不许〉。禁止乱扔要用“不许”，“不用”只表示没有必要。"}, {"text": "这里不用吸烟，请大家注意。", "explanation": "这里应该用〈不能〉。表示禁止吸烟要用“不能”，“不用”只表示不需要做某事。"}, {"text": "我不用喜欢吃鱼。", "explanation": "这里应该用〈不〉。表示不喜欢要说“不喜欢”，“不用”表示没有必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不能", "is_correct": false, "explanation": "搭配：“不能谢”不是常见说法，不能用来回应感谢。"}, {"text": "要", "is_correct": false, "explanation": "语义：“要谢”表示想要表达感谢，与“这是我应该做的”的推辞语境相反。"}, {"text": "不用", "is_correct": true, "explanation": "正确：“不用谢”是推辞感谢的常用回应，与后半句相符。"}, {"text": "会", "is_correct": false, "explanation": "语义：“会谢”不符合推辞感谢的语境，句子语气不通。"}], "explanations": {"不能": "搭配：“不能谢”不是常见说法，不能用来回应感谢。", "要": "语义：“要谢”表示想要表达感谢，与“这是我应该做的”的推辞语境相反。", "不用": "正确：“不用谢”是推辞感谢的常用回应，与后半句相符。", "会": "语义：“会谢”不符合推辞感谢的语境，句子语气不通。"}, "sentence_index": 6, "correct_answer": "不用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校不用大声喧哗。", "explanation": "这里应该用〈不许〉。表示禁止要用“不许”，“不用”表示没有必要，句子会变成学校不需要人们大声喧哗。"}, {"text": "上课的时候，学生不用迟到。", "explanation": "这里应该用〈不要〉。表示劝阻要用“不要”，“不用”表示没有必要，句子会变成学生没有必要迟到。"}, {"text": "考场上不用作弊，请大家遵守规则。", "explanation": "这里应该用〈不得〉。表示禁止作弊要用“不得”，“不用”只表示没有必要，与“请大家遵守规则”的语气不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天不用着早起，可以多睡一会儿。", "corrected_sentence": "明天不用早起，可以多睡一会儿。", "error_description": "“不用”后面不能加“着”，情态动词后不接“着”。正确是“明天不用早起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天没用上学。", "corrected_sentence": "我们明天不用上学。", "error_description": "用词错误：表示没有必要做某事要说“不用”，“没用”是“没有用处”的意思。正确是“我们明天不用上学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
