INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "垃圾是不要的、脏的东西。", "primary_collocate": null, "pronunciation": "lā jī", "ipa": "la˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "请把垃圾扔到外面。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有很多垃圾，真脏。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上出门时带走垃圾。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些垃圾要分类。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我去倒垃圾。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有人在捡垃圾。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的垃圾已经很多了，该倒了。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在公园里乱扔垃圾。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把没用的旧东西都当垃圾扔了。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾很臭，快拿出去吧。", "target_word": "垃圾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆垃圾", "label": "量词搭配"}, {"form": "垃圾桶", "label": "复合"}, {"form": "垃圾袋", "label": "复合"}, {"form": "垃圾分类", "label": "复合"}], "register": "中性", "sense_fingerprint": "不要的、脏的废弃东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大象", "is_correct": false, "explanation": "体貌：大象体形庞大，不能被“扔到外面”。"}, {"text": "垃圾", "is_correct": true, "explanation": "正确。“把垃圾扔到外面”是日常说法，“垃圾”是要扔掉的东西。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能被“扔到外面”，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”无形无质，不能被“扔”出去，句意不通。"}], "explanations": {"大象": "体貌：大象体形庞大，不能被“扔到外面”。", "垃圾": "正确。“把垃圾扔到外面”是日常说法，“垃圾”是要扔掉的东西。", "月亮": "语义：月亮是天体，不能被“扔到外面”，句意不通。", "空气": "语义：“空气”无形无质，不能被“扔”出去，句意不通。"}, "sentence_index": 0, "correct_answer": "垃圾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他留下了一笔巨额垃圾。", "explanation": "这里应该用〈财产〉。“垃圾”没有价值，不能用“巨额”修饰，值钱的钱财应说〈财产〉。"}, {"text": "路边放着一只垃圾。", "explanation": "这里应该用〈堆〉。垃圾按“堆”计量，“只”用于单个的物件或动物，不用于垃圾。"}, {"text": "箱子里装着贵重的垃圾。", "explanation": "这里应该用〈财物〉。“垃圾”指没有用的脏东西，不能说“贵重”；贵重的东西要说〈财物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人", "is_correct": false, "explanation": "语义：“人”不是可以倒掉的东西，与“该倒了”的语境不符。"}, {"text": "房子", "is_correct": false, "explanation": "体貌：“房子”体积庞大，放不进厨房，也没法倒掉。"}, {"text": "垃圾", "is_correct": true, "explanation": "正确。“厨房里的垃圾已经很多了，该倒了”符合日常语境。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”在天上，不会堆在厨房里，与“很多了，该倒了”不符。"}], "explanations": {"人": "语义：“人”不是可以倒掉的东西，与“该倒了”的语境不符。", "房子": "体貌：“房子”体积庞大，放不进厨房，也没法倒掉。", "垃圾": "正确。“厨房里的垃圾已经很多了，该倒了”符合日常语境。", "星星": "语义：“星星”在天上，不会堆在厨房里，与“很多了，该倒了”不符。"}, "sentence_index": 6, "correct_answer": "垃圾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些垃圾要放进冰箱保存。", "explanation": "这里应该用〈食物〉。食物需要保存以便食用，“垃圾”没有食用价值，不需要放进冰箱。"}, {"text": "路边有一群垃圾。", "explanation": "这里应该用〈堆〉。垃圾成堆，按“堆”计量；“群”只用于聚在一起的人或动物。"}, {"text": "这碗垃圾很香，我想尝尝。", "explanation": "这里应该用〈饭菜〉。“垃圾”是没用的脏东西，不能说香，也不能拿来尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口放着一张垃圾。", "corrected_sentence": "门口放着一袋垃圾。", "error_description": "错误形式：「一张垃圾」。正确形式：「一袋垃圾」。“张”用于平展的物件，“垃圾”应按“袋”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街道上扔着很多垃圾们。", "corrected_sentence": "街道上扔着很多垃圾。", "error_description": "错误形式：「垃圾们」。正确形式：「垃圾」。“们”只加在指人的名词后面，不能用于“垃圾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
