INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "能够长期保持、一直做下去的特点。", "primary_collocate": null, "pronunciation": "kě chí xù xìng", "ipa": "kʰɤ˨˩˦ ʈʂʰɻ̩˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个项目很注重可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要考虑农业的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法缺少可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保公司很看重产品的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市发展要有可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂提高了生产的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说这个计划没有可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用旧瓶子做花盆，有很好的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家讨论能源的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的方法有可持续性，不是一时的办法。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可持续", "label": "形容词形式"}, {"form": "可持续发展", "label": "复合"}], "register": "书面语", "sense_fingerprint": "能够长期保持、一直做下去的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b26b9a-9d68-4360-8cd8-e1c05a934069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可持续性", "is_correct": true, "explanation": "正确：“可持续性”指能长期保持的特点，与“很注重”搭配，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷暖阴晴，不是项目注重的对象，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是具体的物体，“注重”后接的应是抽象的重点，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“注重”通常接“质量、效果、安全”等抽象重点，“脚步”不能作注重的对象。"}], "explanations": {"可持续性": "正确：“可持续性”指能长期保持的特点，与“很注重”搭配，句意通顺。", "天气": "语义：“天气”指冷暖阴晴，不是项目注重的对象，句意不通。", "石头": "语义：“石头”是具体的物体，“注重”后接的应是抽象的重点，句意不通。", "脚步": "搭配：“注重”通常接“质量、效果、安全”等抽象重点，“脚步”不能作注重的对象。"}, "sentence_index": 0, "correct_answer": "可持续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的可持续性很甜。", "explanation": "这里应该用〈气氛〉之类的词。“甜”形容味道，不能用来形容可持续性。"}, {"text": "这种牛奶的可持续性很酸。", "explanation": "这里应该用〈味道〉。“酸”形容味道，不能用来形容可持续性。"}, {"text": "这只猫的可持续性很硬。", "explanation": "这里应该用〈毛〉之类的词。“硬”形容质地，不能用来形容可持续性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可持续性", "is_correct": true, "explanation": "正确：“可持续性”指计划能长期维持的特点，“没有”后接它，句意通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物身体的热度，计划没有体温，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，计划不能说没有身高，句意不通。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”只用于人或动植物，不能用来说计划有没有性别。"}], "explanations": {"可持续性": "正确：“可持续性”指计划能长期维持的特点，“没有”后接它，句意通顺。", "体温": "语义：“体温”指人或动物身体的热度，计划没有体温，句意不通。", "身高": "语义：“身高”指人的高矮，计划不能说没有身高，句意不通。", "性别": "搭配：“性别”只用于人或动植物，不能用来说计划有没有性别。"}, "sentence_index": 6, "correct_answer": "可持续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的可持续性很快。", "explanation": "这里应该用〈速度〉。可持续性不用来说快慢，车跑得快不快要用速度。"}, {"text": "这块石头的可持续性很重。", "explanation": "这里应该用〈重量〉。可持续性指能长期维持下去的特点，不能用来说轻重，石头有多重要用重量。"}, {"text": "这件衣服的可持续性很便宜。", "explanation": "这里应该用〈价格〉。可持续性不用来说价钱，衣服贵不贵要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场很重视土地的一个可持续性。", "corrected_sentence": "农场很重视土地的可持续性。", "error_description": "错误：“一个可持续性”。“可持续性”表示能长期维持的特点，是不能直接计数的属性，不说“一个可持续性”，应直接说“土地的可持续性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案得可持续性很强。", "corrected_sentence": "这个方案的可持续性很强。", "error_description": "错误：“得可持续性”。“得”是补语标记，不能用来修饰名词，应用结构助词“的”，写作“方案的可持续性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：一人单独使用，与“共享”意思相反，构成反义。"}, {"text": "购买", "is_correct": false, "explanation": "与“共享”无反义关系：“购买”是付钱取得东西，与共同使用无关。"}, {"text": "搬运", "is_correct": false, "explanation": "与“共享”无反义关系：“搬运”指搬动物品，与共同使用无关。"}, {"text": "烧毁", "is_correct": false, "explanation": "与“共享”无反义关系：“烧毁”指烧坏、毁掉，与共同使用无关。"}], "correct_answer": "独享", "explanations": {"独享": "独享：一人单独使用，与“共享”意思相反，构成反义。", "购买": "与“共享”无反义关系：“购买”是付钱取得东西，与共同使用无关。", "搬运": "与“共享”无反义关系：“搬运”指搬动物品，与共同使用无关。", "烧毁": "与“共享”无反义关系：“烧毁”指烧坏、毁掉，与共同使用无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：一人单独使用，与“共享”意思相反，构成反义。"}, {"text": "修建", "is_correct": false, "explanation": "与“共享”无反义关系：“修建”指建造房屋、道路等，与共同使用无关。"}, {"text": "翻译", "is_correct": false, "explanation": "与“共享”无反义关系：“翻译”指把一种语言转换成另一种语言，与共同使用无关。"}, {"text": "调查", "is_correct": false, "explanation": "与“共享”无反义关系：“调查”指查问、考察情况，与共同使用无关。"}], "correct_answer": "独享", "explanations": {"独享": "独享：一人单独使用，与“共享”意思相反，构成反义。", "修建": "与“共享”无反义关系：“修建”指建造房屋、道路等，与共同使用无关。", "翻译": "与“共享”无反义关系：“翻译”指把一种语言转换成另一种语言，与共同使用无关。", "调查": "与“共享”无反义关系：“调查”指查问、考察情况，与共同使用无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "几个人一起用同一样东西。", "primary_collocate": null, "pronunciation": "gòng xiǎng", "ipa": "kʊŋ˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我和同学共享一把伞。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们共享一个房间。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐愿意和我共享电脑。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们共享一个充电宝。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室友共享一台洗衣机。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和朋友共享着一本书。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以和我共享网络。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子共享一个玩具。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们共享过一间小办公室。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厨房，三家人共享。", "target_word": "共享", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共享了", "label": "体标"}, {"form": "共享着", "label": "体标"}, {"form": "共享过", "label": "体标"}], "register": "中性", "sense_fingerprint": "几个人一起使用同一样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共享", "is_correct": true, "explanation": "共享：两个人或几个人一起用同一样东西，即本词条的意思。"}, {"text": "贡献", "is_correct": false, "explanation": "gòngxiàn 与 gòngxiǎng 韵母与声调不同（ian／iang，第四声／第三声），意思是为某事出力。"}, {"text": "共性", "is_correct": false, "explanation": "gòngxìng 与 gòngxiǎng 韵母与声调不同（ing／iang，第四声／第三声），意思是共同的性质。"}, {"text": "空想", "is_correct": false, "explanation": "kōngxiǎng 与 gòngxiǎng 声母与声调不同（k／g，第一声／第四声），意思是不切实际地想象。"}], "explanations": {"共享": "共享：两个人或几个人一起用同一样东西，即本词条的意思。", "贡献": "gòngxiàn 与 gòngxiǎng 韵母与声调不同（ian／iang，第四声／第三声），意思是为某事出力。", "共性": "gòngxìng 与 gòngxiǎng 韵母与声调不同（ing／iang，第四声／第三声），意思是共同的性质。", "空想": "kōngxiǎng 与 gòngxiǎng 声母与声调不同（k／g，第一声／第四声），意思是不切实际地想象。"}, "sentence_index": null, "correct_answer": "共享"}, "level_3": {"options": [{"text": "共享", "is_correct": true, "explanation": "共享：几人一起使用同一样东西，与“我和同学……一把伞”相符。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者（送给谁），“送一把伞”缺少接受者，句子不成立。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”需要处所（放在某处），“放一把伞”缺少处所，不成句。"}, {"text": "玩", "is_correct": false, "explanation": "搭配：“玩”多搭配游戏、玩具，不说“玩一把伞”。"}], "explanations": {"共享": "共享：几人一起使用同一样东西，与“我和同学……一把伞”相符。", "送": "配价：“送”需要接受者（送给谁），“送一把伞”缺少接受者，句子不成立。", "放": "配价：“放”需要处所（放在某处），“放一把伞”缺少处所，不成句。", "玩": "搭配：“玩”多搭配游戏、玩具，不说“玩一把伞”。"}, "sentence_index": 0, "correct_answer": "共享"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这块饼干共享给了弟弟。", "explanation": "这里应该用〈分享〉。饼干吃掉后不能同时使用，只能分开吃；共享指几人一起使用同一样东西。"}, {"text": "这间房间我一个人共享。", "explanation": "这里应该用〈独享〉。共享需要两人或以上一起使用，“一个人”不能共享。"}, {"text": "我们共享完成了这个项目。", "explanation": "这里应该用〈合作〉。“共享”不能和“完成”搭配作谓语，应说合作完成项目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共享", "is_correct": true, "explanation": "共享：几人一起使用同一样东西，与“你可以和我……网络”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：网络不能被吃，“吃网络”不成立。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，网络不能被喂。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”搭配桌面、玻璃等表面，不说“擦网络”。"}], "explanations": {"共享": "共享：几人一起使用同一样东西，与“你可以和我……网络”相符。", "吃": "语义：网络不能被吃，“吃网络”不成立。", "喂": "语义：“喂”的对象是人或动物，网络不能被喂。", "擦": "搭配：“擦”搭配桌面、玻璃等表面，不说“擦网络”。"}, "sentence_index": 6, "correct_answer": "共享"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们共享了一场期末考试。", "explanation": "这里应该用〈参加〉。考试是一次性活动，不能被几人一起使用，应说参加考试。"}, {"text": "这个夏天，我们共享了一场暴雨。", "explanation": "这里应该用〈遭遇〉。暴雨是自然现象，不是可以共同使用的东西，应说遭遇暴雨。"}, {"text": "他们共享了一次意外。", "explanation": "这里应该用〈遇到〉。意外不能被几人共同使用，应说遇到意外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起很共享一台电脑。", "corrected_sentence": "我们一起共享一台电脑。", "error_description": "程度副词“很”不能修饰动词“共享”，去掉“很”，应说“我们一起共享一台电脑。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们共享着过一个房间。", "corrected_sentence": "他们共享过一个房间。", "error_description": "体标误用：「着」和「过」不能同时跟在「共享」后面。表示过去的经历用「过」，应说「共享过一个房间」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
