INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装东西的小盒子。", "primary_collocate": null, "pronunciation": "xiǎo xiāng zi", "ipa": "ɕiɑʊ˨˩ ɕiɑŋ˥ tsɿ", "syllable_count": 3, "sentences": [{"text": "孩子把玩具装进小箱子里。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小箱子用来放我的铅笔和尺子。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小箱子掉在地上，里面的东西都出来了。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一个金属小箱子放工具。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把项链放在小箱子里，锁好了。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子下面有一个蓝色的小箱子。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的小箱子里有什么？", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用小箱子装零钱。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小箱子很重，我一个人拿不动。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把信和照片都放进了那个小箱子里。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小箱子", "label": "量词"}, {"form": "一只小箱子", "label": "量词"}], "register": "口语", "sense_fingerprint": "装东西的小盒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小箱子", "is_correct": true, "explanation": "正确：小箱子是装东西的小盒子，孩子可以把玩具装进去。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是可以装东西的容器，“装进……里”后不能接它。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不是能装东西的器具，“装进”后不能接它。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“装进”后接的应是可以装东西的容器，大海不能用来装玩具。"}], "explanations": {"小箱子": "正确：小箱子是装东西的小盒子，孩子可以把玩具装进去。", "阳光": "语义：阳光不是可以装东西的容器，“装进……里”后不能接它。", "云朵": "语义：云朵不是能装东西的器具，“装进”后不能接它。", "大海": "搭配：“装进”后接的应是可以装东西的容器，大海不能用来装玩具。"}, "sentence_index": 0, "correct_answer": "小箱子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸把小箱子当作车子，一路骑着去上班。", "explanation": "这里应该用〈自行车〉。自行车可以骑行；小箱子是装东西的容器，不能骑。"}, {"text": "妈妈用小箱子烧水，水很快就开了。", "explanation": "这里应该用〈水壶〉。水壶能放在火上烧水；小箱子不能用来烧水。"}, {"text": "他把小箱子穿在身上，当作雨衣挡雨。", "explanation": "这里应该用〈雨衣〉。雨衣可以穿在身上挡雨；小箱子不能穿在身上挡雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小箱子", "is_correct": true, "explanation": "正确：小箱子是装东西的容器，可以问“小箱子里有什么”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是能装东西的容器，“影子里有什么”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能用来装东西，这里问的是容器里装的东西。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“里”后接的应是可以装东西的地方，“脚步”不是。"}], "explanations": {"小箱子": "正确：小箱子是装东西的容器，可以问“小箱子里有什么”。", "影子": "语义：影子不是能装东西的容器，“影子里有什么”说不通。", "名字": "语义：名字不能用来装东西，这里问的是容器里装的东西。", "脚步": "搭配：“里”后接的应是可以装东西的地方，“脚步”不是。"}, "sentence_index": 6, "correct_answer": "小箱子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把小箱子系在腰上，当作围裙围着做饭。", "explanation": "这里应该用〈围裙〉。围裙系在身上挡油污；小箱子是容器，不能当围裙用。"}, {"text": "她把小箱子穿在脚上，穿着它在雨里走路。", "explanation": "这里应该用〈鞋子〉。鞋子穿在脚上走路；小箱子是容器，不能当鞋穿。"}, {"text": "她把小箱子放在火上，烧起了一锅热汤。", "explanation": "这里应该用〈锅〉。锅能放在火上煮汤；小箱子不能放在火上烧汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把钥匙放进了一块小箱子里。", "corrected_sentence": "妈妈把钥匙放进了一个小箱子里。", "error_description": "量词错误：箱子应用“个”或“只”，不能用“块”；“块”多用于块状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有三小箱子放在柜子上。", "corrected_sentence": "我家有三个小箱子放在柜子上。", "error_description": "量词缺失：数词后应加量词，应说“三个小箱子”，不能直接说“三小箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
