INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以赚钱的钱或东西。", "primary_collocate": null, "pronunciation": "zī běn", "ipa": "tsɨ˥˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想开店，可是没有资本。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开公司需要一大笔资本。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的资本只有五万元。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把资本都投到新工厂里了。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意资本不够，只好找朋友借。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张用自己的资本开了一家饭馆。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用多年存下的资本买了两台机器。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本大的公司，一年能开十家新店。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司资本少，不敢买太贵的机器。", "target_word": "资本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人一起投入资本，开了一家茶店。", "target_word": "资本", "complexity_tier": "T3", "furigana": "tā men sān gè rén yìqǐ tóurù zīběn kāi le yì jiā chá diàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔资本", "label": "量词"}, {"form": "资本家", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指做生意、办企业用来赚钱的钱和财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资本", "is_correct": true, "explanation": "“资本”指可以赚钱的钱或财物，符合“想开店却没有钱”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，与开店缺少的条件无关，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来说开店缺少什么。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：“树叶”是植物的一部分，与开店无关，句子说不通。"}], "explanations": {"资本": "“资本”指可以赚钱的钱或财物，符合“想开店却没有钱”的语境。", "天气": "语义：“天气”指冷热阴晴，与开店缺少的条件无关，句子说不通。", "身材": "体貌：“身材”指人的体形，不能用来说开店缺少什么。", "树叶": "语义：“树叶”是植物的一部分，与开店无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "资本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为违章，交给交警一笔资本。", "explanation": "这里应该用〈罚款〉。资本指可以赚钱的钱或财物，因违章交的钱要用罚款。"}, {"text": "他的资本很高兴地回家了。", "explanation": "这里应该用〈员工〉。资本指可以赚钱的钱或财物，不指人，不能说“资本很高兴地回家”。"}, {"text": "他们在公园里资本了一下午。", "explanation": "这里应该用〈玩〉。资本是名词，指可以赚钱的钱或财物，不能作动词表示玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资本", "is_correct": true, "explanation": "“资本”指用来赚钱的钱，符合“用多年存下的钱买机器”的语境。"}, {"text": "经验", "is_correct": false, "explanation": "搭配：“经验”是知识和阅历，不能用来购买东西，不说用经验买机器。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：“笑声”是声音，不能存下来用于买机器。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能像钱一样用来买机器，句子说不通。"}], "explanations": {"资本": "“资本”指用来赚钱的钱，符合“用多年存下的钱买机器”的语境。", "经验": "搭配：“经验”是知识和阅历，不能用来购买东西，不说用经验买机器。", "笑声": "语义：“笑声”是声音，不能存下来用于买机器。", "时间": "语义：“时间”不能像钱一样用来买机器，句子说不通。"}, "sentence_index": 6, "correct_answer": "资本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国的资本是北京。", "explanation": "这里应该用〈首都〉。资本指可以赚钱的钱或财物，一个国家的政治中心城市要用首都。"}, {"text": "我们在超市买了一公斤资本。", "explanation": "这里应该用〈大米〉。资本指可以赚钱的钱或财物，不是食品，不能用“公斤”来计量购买。"}, {"text": "他每个月拿到的资本很多。", "explanation": "这里应该用〈工资〉。资本指用来赚钱的钱或财物，每月发放的收入要用工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们拿出一个资本，开了一家书店。", "corrected_sentence": "他们拿出一笔资本，开了一家书店。", "error_description": "错误：“一个资本”。正确：“一笔资本”。“资本”指一笔钱款，量词要用“笔”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一笔不小资本。", "corrected_sentence": "他有一笔不小的资本。", "error_description": "错误：“不小资本”，缺少“的”。正确：“不小的资本”。“不小”是形容词，修饰“资本”时中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
