INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21080, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一样东西变成另一样东西。", "primary_collocate": null, "pronunciation": "zhuǎn huà", "ipa": "ʈʂwan˨˩˦ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "水可以转化成冰。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能可以转化为电。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物把阳光转化成能量。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物在身体里会转化为能量。", "target_word": "转化", "complexity_tier": "T3", "furigana": "shí wù zài shēn tǐ lǐ huì zhuǎnhuà wéi néng liàng", "sentence_source": "generated"}, {"text": "他想把压力转化成动力。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器能把垃圾转化成电。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好事有时会转化成坏事。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水冷了以后，会转化为冰。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把失败转化为经验。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，雨常常转化成雪。", "target_word": "转化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转化了", "label": "体标"}, {"form": "转化过", "label": "体标"}, {"form": "转化着", "label": "体标"}, {"form": "转化率", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物从一种形态变成另一种形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转化", "is_correct": true, "explanation": "正确答案：转化，意思是事物从一种形态变成另一种形态。"}, {"text": "软化", "is_correct": false, "explanation": "ruǎn 与 zhuǎn 声母不同（r 与 zh），整词意思是“变软”。"}, {"text": "暖化", "is_correct": false, "explanation": "nuǎn 与 zhuǎn 声母不同（n 与 zh），整词意思是“变暖”。"}, {"text": "转会", "is_correct": false, "explanation": "huì 与 huà 韵母不同（i 与 a），整词意思是“转到另一支球队”。"}], "explanations": {"转化": "正确答案：转化，意思是事物从一种形态变成另一种形态。", "软化": "ruǎn 与 zhuǎn 声母不同（r 与 zh），整词意思是“变软”。", "暖化": "nuǎn 与 zhuǎn 声母不同（n 与 zh），整词意思是“变暖”。", "转会": "huì 与 huà 韵母不同（i 与 a），整词意思是“转到另一支球队”。"}, "sentence_index": null, "correct_answer": "转化"}, "level_3": {"options": [{"text": "转化", "is_correct": true, "explanation": "“转化”表示事物变成另一种形态，符合“水可以变成冰”的语境。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体变成液体，与水变成冰的方向相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说水吃成冰。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”用于语言之间的转换，不能用于水和冰。"}], "explanations": {"转化": "“转化”表示事物变成另一种形态，符合“水可以变成冰”的语境。", "融化": "语义：“融化”指固体变成液体，与水变成冰的方向相反。", "吃": "搭配：“吃”的对象是食物，不能说水吃成冰。", "翻译": "搭配：“翻译”用于语言之间的转换，不能用于水和冰。"}, "sentence_index": 0, "correct_answer": "转化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人已经被转化到另一家医院了。", "explanation": "这里应该用〈转移〉。转化指事物形态的改变，人从一处被送到另一处要用转移。"}, {"text": "我把这封信转化给了老师。", "explanation": "这里应该用〈转交〉。转化指事物形态的改变，把东西交给别人要用转交。"}, {"text": "电视台转化了这场比赛。", "explanation": "这里应该用〈转播〉。转化指事物形态的改变，把比赛传送给观众要用转播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转化", "is_correct": true, "explanation": "“转化”表示事物变成另一种形态，这里指好事变成坏事，符合语境。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变成固体，不能用来说好事变成坏事。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的对象是布或网，不能说织成坏事。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，不能用来说好事变成坏事。"}], "explanations": {"转化": "“转化”表示事物变成另一种形态，这里指好事变成坏事，符合语境。", "凝固": "语义：“凝固”指液体变成固体，不能用来说好事变成坏事。", "织": "搭配：“织”的对象是布或网，不能说织成坏事。", "烧": "语义：“烧”指燃烧或加热，不能用来说好事变成坏事。"}, "sentence_index": 6, "correct_answer": "转化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的公司转化给了朋友。", "explanation": "这里应该用〈转让〉。转化指事物形态的改变，把公司、产权交给别人要用转让。"}, {"text": "这种病毒会转化给很多人。", "explanation": "这里应该用〈传染〉。转化指事物形态的改变，疾病从一人传给另一人要用传染。"}, {"text": "两家公司转化了各自的员工。", "explanation": "这里应该用〈交换〉。转化指事物形态的改变，人员互相调换要用交换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器能把废纸转化纸浆。", "corrected_sentence": "这台机器能把废纸转化成纸浆。", "error_description": "错误：“转化纸浆”，缺少结果补语。正确：“转化成纸浆”。“转化”后要用“成”或“为”引出结果，不能直接接结果宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些冷水到了半夜会转化了为冰。", "corrected_sentence": "这些冷水到了半夜会转化为冰。", "error_description": "错误：“转化了为冰”，在“转化”后多用了“了”。正确：“转化为冰”。句中有“会”表示将要发生，不用“了”，“转化”后直接接“为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
