INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家人就是和你住在一起的人，比如爸爸、妈妈。", "primary_collocate": null, "pronunciation": "jiā rén", "ipa": "tɕia˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "我和家人住在一个小城市。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我和家人一起包饺子。", "target_word": "家人", "complexity_tier": "T3", "furigana": "guò nián de shí hou，wǒ hé jiārén yì qǐ bāo jiǎozi。", "sentence_source": "generated"}, {"text": "他每天晚上陪家人看电视。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家人很喜欢吃妈妈做的饭。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们带着家人去公园玩。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人生病了，他很担心。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的家人今年夏天去过北京吗？", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想买一个礼物送给家人。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天和家人一起吃晚饭。", "target_word": "家人", "complexity_tier": "T3", "furigana": "tā měi tiān hé jiārén yì qǐ chī wǎnfàn。", "sentence_source": "generated"}, {"text": "家人的健康比什么都重要。", "target_word": "家人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "家庭里住在一起的亲人，如父母", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "搭配：“住在一个小城市”的主语应是人或动物，“课本”不能与“我和”并列同住。"}, {"text": "家人", "is_correct": true, "explanation": "“家人”指和你住在一起的亲人，与“我和……住在一个小城市”相符。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”不是能与“我”一同居住的人，“我和公司住在一个小城市”不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是无生命的物品，不能与人一同住在城市里。"}], "explanations": {"课本": "搭配：“住在一个小城市”的主语应是人或动物，“课本”不能与“我和”并列同住。", "家人": "“家人”指和你住在一起的亲人，与“我和……住在一个小城市”相符。", "公司": "语义：“公司”不是能与“我”一同居住的人，“我和公司住在一个小城市”不通。", "电脑": "语义：电脑是无生命的物品，不能与人一同住在城市里。"}, "sentence_index": 0, "correct_answer": "家人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课的时候，家人站在讲台上教我们数学。", "explanation": "这里应该用〈老师〉。家人指和你住在一起的亲人，在讲台上教课的是老师。"}, {"text": "在路上，家人主动帮我捡起了掉在地上的书，我们素不相识。", "explanation": "这里应该用〈陌生人〉。家人指亲近、住在一起的人，与“素不相识”矛盾，应说“陌生人主动帮我捡起了书”。"}, {"text": "教室里的家人都在认真听课。", "explanation": "这里应该用〈同学〉。家人指和你住在一起的亲人，教室里的同学不是家人，应说“同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能去北京。"}, {"text": "家人", "is_correct": true, "explanation": "“家人”指亲人，与“你的……去过北京吗”相符。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“去过北京”的主语须是能出行的人，“你的手机”不搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能外出去北京。"}], "explanations": {"作业": "语义：作业是学习任务，不能去北京。", "家人": "“家人”指亲人，与“你的……去过北京吗”相符。", "手机": "搭配：“去过北京”的主语须是能出行的人，“你的手机”不搭配。", "冰箱": "语义：冰箱是家用电器，不能外出去北京。"}, "sentence_index": 6, "correct_answer": "家人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教练说，家人的实力很强，我们要小心。", "explanation": "这里应该用〈对手〉。家人指亲人，不能指比赛中的对方。"}, {"text": "家人在夜里偷袭了城镇。", "explanation": "这里应该用〈敌军〉。家人指亲人，不能指发动偷袭的作战一方。"}, {"text": "家人抢走了商船上的货物。", "explanation": "这里应该用〈海盗〉。家人指亲人，不能指抢劫商船的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只家人在北京工作。", "corrected_sentence": "我有一个家人在北京工作。", "error_description": "“家人”的量词错误。“家人”指人，量词应用“个”（或“位”），“只”用于动物，应写作“一个家人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有三个家人们在北京。", "corrected_sentence": "我有三个家人在北京。", "error_description": "数量词“三个”后面的名词不能再加“们”。应删去“们”，写作“三个家人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "正确：在“好玩”表示有趣的意义上，“无聊”与之意思相对，是反义词。"}, {"text": "严格", "is_correct": false, "explanation": "无关：“严格”形容要求或态度，与“好玩”没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "无关：“陌生”指不熟悉，与“好玩”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "无关：“简单”指不复杂，与“好玩”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "正确：在“好玩”表示有趣的意义上，“无聊”与之意思相对，是反义词。", "严格": "无关：“严格”形容要求或态度，与“好玩”没有反义关系。", "陌生": "无关：“陌生”指不熟悉，与“好玩”没有反义关系。", "简单": "无关：“简单”指不复杂，与“好玩”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "正确：在“好玩”表示开心有趣的意义上，“无聊”与之意思相对，是反义词。"}, {"text": "热情", "is_correct": false, "explanation": "无关：“热情”形容态度，与“好玩”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容声音或环境，与“好玩”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力，与“好玩”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "正确：在“好玩”表示开心有趣的意义上，“无聊”与之意思相对，是反义词。", "热情": "无关：“热情”形容态度，与“好玩”没有反义关系。", "安静": "无关：“安静”形容声音或环境，与“好玩”没有反义关系。", "聪明": "无关：“聪明”形容智力，与“好玩”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好玩就是做事情很开心，像玩游戏一样。", "primary_collocate": null, "pronunciation": "hǎo wán", "ipa": "xɑʊ˨˩ wan˧˥", "syllable_count": 2, "sentences": [{"text": "我们一起做饼干，太好玩了。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学画画很好玩，孩子们都喜欢。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机拍照片好玩极了。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做科学小实验好玩又有用。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一起堆雪人真好玩！", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫房间也可以很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用唱歌的方式学汉字，很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车去海边，一路上都很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样学数学，好玩多了。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和朋友一起做手工，真好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好玩儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "做事情开心、像玩游戏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。"}, {"text": "考完", "is_correct": false, "explanation": "声母不同（k 与 h），kǎo wán 意思是考试结束，与 hǎo wán 只差声母。"}, {"text": "搞完", "is_correct": false, "explanation": "声母不同（g 与 h），gǎo wán 意思是做完，与 hǎo wán 只差声母。"}, {"text": "炒完", "is_correct": false, "explanation": "声母不同（ch 与 h），chǎo wán 意思是炒完，与 hǎo wán 只差声母。"}], "explanations": {"好玩": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。", "考完": "声母不同（k 与 h），kǎo wán 意思是考试结束，与 hǎo wán 只差声母。", "搞完": "声母不同（g 与 h），gǎo wán 意思是做完，与 hǎo wán 只差声母。", "炒完": "声母不同（ch 与 h），chǎo wán 意思是炒完，与 hǎo wán 只差声母。"}, "sentence_index": null, "correct_answer": "好玩"}, "level_3": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：“好玩”说做事情很开心，与“一起做饼干”相符。"}, {"text": "孤单", "is_correct": false, "explanation": "语义：“一起做”却感到孤单，句意自相矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没有人气，与“一起做饼干”矛盾。"}, {"text": "难看", "is_correct": false, "explanation": "体貌：“难看”形容外表，不能用来评价做饼干的过程。"}], "explanations": {"好玩": "正确：“好玩”说做事情很开心，与“一起做饼干”相符。", "孤单": "语义：“一起做”却感到孤单，句意自相矛盾。", "冷清": "语义：“冷清”指没有人气，与“一起做饼干”矛盾。", "难看": "体貌：“难看”形容外表，不能用来评价做饼干的过程。"}, "sentence_index": 0, "correct_answer": "好玩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试前，我的手心出汗，心里很好玩。", "explanation": "这里应该用〈紧张〉。紧张形容心理状态；好玩说事情有趣，不能用来形容心里的感觉。"}, {"text": "这个消息让他心里很好玩。", "explanation": "这里应该用〈难过〉。难过表示伤心；好玩表示有趣，不能用来形容伤心的心情。"}, {"text": "吃了太多油炸食品，我的身体很好玩。", "explanation": "这里应该用〈不舒服〉。“不舒服”说身体有不适；“好玩”说事情有趣，不能用来形容身体状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。"}, {"text": "跑完", "is_correct": false, "explanation": "声母不同（p 与 h），pǎo wán 意思是跑完全程，与 hǎo wán 只差声母。"}, {"text": "倒完", "is_correct": false, "explanation": "声母不同（d 与 h），dǎo wán 意思是倒完，与 hǎo wán 只差声母。"}, {"text": "扫完", "is_correct": false, "explanation": "声母不同（s 与 h），sǎo wán 意思是扫完，与 hǎo wán 只差声母。"}], "explanations": {"好玩": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。", "跑完": "声母不同（p 与 h），pǎo wán 意思是跑完全程，与 hǎo wán 只差声母。", "倒完": "声母不同（d 与 h），dǎo wán 意思是倒完，与 hǎo wán 只差声母。", "扫完": "声母不同（s 与 h），sǎo wán 意思是扫完，与 hǎo wán 只差声母。"}, "sentence_index": null, "correct_answer": "好玩"}, "level_3": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：“好玩”说学习方式让人开心，与句意相符。"}, {"text": "冷酷", "is_correct": false, "explanation": "语义：“冷酷”形容人的态度，不用来评价学习方式。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不用来评价用唱歌学汉字的方式。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型或外形，不用来评价学习方式。"}], "explanations": {"好玩": "正确：“好玩”说学习方式让人开心，与句意相符。", "冷酷": "语义：“冷酷”形容人的态度，不用来评价学习方式。", "寒冷": "语义：“寒冷”形容温度，不用来评价用唱歌学汉字的方式。", "高大": "体貌：“高大”形容体型或外形，不用来评价学习方式。"}, "sentence_index": 6, "correct_answer": "好玩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子很好玩，四条腿都摇摇晃晃。", "explanation": "这里应该用〈结实〉。结实说东西牢固；好玩说有趣，不能用来形容桌子牢不牢固。"}, {"text": "这台电脑很好玩，开机要等半个小时。", "explanation": "这里应该用〈慢〉。慢说速度低；好玩说有趣，不能用来形容速度。"}, {"text": "这碗汤很好玩，咸得没法喝。", "explanation": "这里应该用〈难喝〉。难喝说味道不好；好玩说有趣，不能用来形容汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个好玩活动，大家都愿意参加。", "corrected_sentence": "这是一个好玩的活动，大家都愿意参加。", "error_description": "结构助词缺失：“好玩”修饰名词时要加“的”，应说“好玩的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种活动一点也好玩，我不想参加。", "corrected_sentence": "这种活动一点也不好玩，我不想参加。", "error_description": "否定缺失：“一点也”后要用“不”，应说“一点也不好玩”，不能说“一点也好玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
