INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从过去到现在。", "primary_collocate": null, "pronunciation": "zhì jīn", "ipa": "ʈʂɻ̩˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "他十年前去了国外，至今没回来。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题至今没有答案。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店至今还在。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我至今记得第一次见她的样子。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她至今一个人住。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书我至今没看完。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥建于明代，至今还能用。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的话我至今忘不了。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的名字我至今记得很清楚。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谜至今没人能解开。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从过去某时一直到现在，常与没、还、记得等连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至今", "is_correct": true, "explanation": "正确：“至今没回来”表示从过去到现在一直没回来，与“十年前去了国外”相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指很近的时间，与“十年前”矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“十年前去了国外”这种长期情况不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，不能与“没回来”的完结否定搭配，不说“正在没回来”。"}], "explanations": {"至今": "正确：“至今没回来”表示从过去到现在一直没回来，与“十年前去了国外”相符。", "刚刚": "语义：“刚刚”指很近的时间，与“十年前”矛盾。", "立刻": "语义：“立刻”表示马上，与“十年前去了国外”这种长期情况不合。", "正在": "搭配：“正在”表示进行中，不能与“没回来”的完结否定搭配，不说“正在没回来”。"}, "sentence_index": 0, "correct_answer": "至今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我至今去北京。", "explanation": "这里应该用〈将〉。“至今”只能指从过去持续到现在，不能用于将来的“明天”；说将来要用“将”。"}, {"text": "他昨天至今回家了。", "explanation": "这里应该用〈已经〉。“至今”强调持续到现在，不能与“昨天……回家了”这种过去完成的事件搭配。"}, {"text": "我至今的朋友都在北京。", "explanation": "“至今”是副词，不能直接修饰名词；这里应说“直到现在认识的朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至今", "is_correct": true, "explanation": "正确：“至今还能用”表示桥从建成到现在仍可以用，与“建于明代”相符。"}, {"text": "最近", "is_correct": false, "explanation": "语义：“最近”指不久以前，与“建于明代”的久远历史矛盾。"}, {"text": "不久", "is_correct": false, "explanation": "语义：“不久”表示时间很近，与“建于明代”的语境不合。"}, {"text": "尽快", "is_correct": false, "explanation": "搭配：“尽快”表示快速完成某事，不用于描述桥的持续状态。"}], "explanations": {"至今": "正确：“至今还能用”表示桥从建成到现在仍可以用，与“建于明代”相符。", "最近": "语义：“最近”指不久以前，与“建于明代”的久远历史矛盾。", "不久": "语义：“不久”表示时间很近，与“建于明代”的语境不合。", "尽快": "搭配：“尽快”表示快速完成某事，不用于描述桥的持续状态。"}, "sentence_index": 6, "correct_answer": "至今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你至今把门关上。", "explanation": "“至今”表示从过去持续到现在，不能用于命令；这里应说“从现在起”。"}, {"text": "这个方法至今是在去年发明的。", "explanation": "这里应该用〈早在〉。“至今”指持续到现在，不能与指过去某一时点的“去年”搭配；说过去某时已经发生，要用“早在”。"}, {"text": "我至今昨天到家了。", "explanation": "这里应该用〈就〉。“至今”指从过去持续到现在，不能与具体的过去时间“昨天”搭配；说昨天已到家，应说“我昨天就到家了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个秘密很至今没有人知道。", "corrected_sentence": "这个秘密至今没有人知道。", "error_description": "“至今”是时间副词，不能受程度副词“很”修饰，应去掉“很”，说“这个秘密至今没有人知道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的病至今了还没好。", "corrected_sentence": "他的病至今还没好。", "error_description": "“至今”后面不能直接加“了”，应去掉，说“至今还没好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无用", "is_correct": true, "explanation": "无用：不能帮到人，与“有用”意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌好看，与“有用”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”说声音或环境少，与“有用”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”说场面红火，与“有用”没有反义关系。"}], "correct_answer": "无用", "explanations": {"无用": "无用：不能帮到人，与“有用”意思相反。", "漂亮": "“漂亮”形容外貌好看，与“有用”没有反义关系。", "安静": "“安静”说声音或环境少，与“有用”没有反义关系。", "热闹": "“热闹”说场面红火，与“有用”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无用", "is_correct": true, "explanation": "无用：不能帮到人，与“有用”意思相反。"}, {"text": "冷清", "is_correct": false, "explanation": "“冷清”说的是人少、不热闹，与“有用”没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "“干燥”说的是水分少，与“有用”没有反义关系。"}, {"text": "湿润", "is_correct": false, "explanation": "“湿润”说的是有水分，与“有用”没有反义关系。"}], "correct_answer": "无用", "explanations": {"无用": "无用：不能帮到人，与“有用”意思相反。", "冷清": "“冷清”说的是人少、不热闹，与“有用”没有反义关系。", "干燥": "“干燥”说的是水分少，与“有用”没有反义关系。", "湿润": "“湿润”说的是有水分，与“有用”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能帮到别人，或对做事情有帮助。", "primary_collocate": null, "pronunciation": "yǒu yòng", "ipa": "jou˨˩˦ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这本书很有用。", "target_word": "有用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法有用吗？", "target_word": "有用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机地图对旅行很有用。", "target_word": "有用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他给我的建议非常有用。", "target_word": "有用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学好英语以后，会很有用。", "target_word": "有用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些旧报纸还有用，别扔。", "target_word": "有用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教的方法对考试很有用。", "target_word": "有用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说的话对我很有用，谢谢你。", "target_word": "有用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这个手机软件特别有用，你也下载一个吧。", "target_word": "有用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送我的这本词典真有用，我每天都带着。", "target_word": "有用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有用的", "label": "定语形式"}, {"form": "没有用", "label": "否定"}], "register": "中性", "sense_fingerprint": "有用|能帮到人或对做事有帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有用", "is_correct": true, "explanation": "有用：能帮到人，或对做事情有帮助。可以用来形容书。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”说的是食物的味道，不能用来形容书。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或地方，不能用来形容书。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：书没有情绪，不会“高兴”，句子说不通。"}], "explanations": {"有用": "有用：能帮到人，或对做事情有帮助。可以用来形容书。", "好吃": "搭配：“好吃”说的是食物的味道，不能用来形容书。", "热闹": "搭配：“热闹”形容场面或地方，不能用来形容书。", "高兴": "语义：书没有情绪，不会“高兴”，句子说不通。"}, "sentence_index": 0, "correct_answer": "有用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的头发很有用，又黑又亮。", "explanation": "这里应该用〈漂亮〉。“有用”说的是能帮到人；形容头发好看、有光泽，要用〈漂亮〉。"}, {"text": "他的心情很有用，一直很高兴。", "explanation": "这里应该用〈好〉。“有用”说的是能帮到人；形容心情好，要用〈好〉。"}, {"text": "这家店的饭很有用，所以客人很多。", "explanation": "这里应该用〈好吃〉。形容饭菜味道好，要用〈好吃〉，不能用“有用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有用", "is_correct": true, "explanation": "有用：能帮到人，对做事有帮助。“老师教的方法对考试很有用”是正确的说法。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：方法没有软硬之分，句子说不通。"}, {"text": "甜", "is_correct": false, "explanation": "语义：方法不能有甜的味道，句子说不通。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”说的是人或环境，不能用来形容方法。"}], "explanations": {"有用": "有用：能帮到人，对做事有帮助。“老师教的方法对考试很有用”是正确的说法。", "柔软": "语义：方法没有软硬之分，句子说不通。", "甜": "语义：方法不能有甜的味道，句子说不通。", "安静": "搭配：“安静”说的是人或环境，不能用来形容方法。"}, "sentence_index": 6, "correct_answer": "有用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个味道很有用，闻起来很香。", "explanation": "这里应该用〈好闻〉。“有用”说的是能帮到人；形容味道好闻，要用〈好闻〉。"}, {"text": "这位画家的名字很有用，很多人都知道他。", "explanation": "这里应该用〈响亮〉。“有用”说的是能帮到人；形容名字有名气，要用〈响亮〉。"}, {"text": "这件衣服的颜色很有用，很鲜艳。", "explanation": "这里应该用〈鲜艳〉。“有用”说的是能帮到人；形容颜色好看、明亮，要用〈鲜艳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法对学习很的有用。", "corrected_sentence": "这个方法对学习很有用。", "error_description": "错误：“很的有用”。正确：“很有用”。程度副词“很”后面不能加“的”，应直接接形容词“有用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧书对我的研究不有用。", "corrected_sentence": "这些旧书对我的研究没有用。", "error_description": "错误：“不有用”。正确：“没有用”。否定“有”要用“没”，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
