INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做一下看看。", "primary_collocate": null, "pronunciation": "shì shi", "ipa": "ʂɻ̩˥˩ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "这双鞋很好看，你试试吧。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想试试这个新手机。", "target_word": "试试", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以试试我做的菜。", "target_word": "试试", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不会游泳也没关系，试试看吧。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想试试用中文写日记。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服太大了，你试试小一点的。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天我们试试坐地铁去，好吗？", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不信的话，可以自己试试。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让我试试新买的帽子。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次来这里，想试试这里的面条。", "target_word": "试试", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "试一试", "label": "重叠"}, {"form": "试了试", "label": "体标"}], "register": "中性", "sense_fingerprint": "做一下看看效果或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试试", "is_correct": true, "explanation": "正确。试试 shì shi 表示做一下看看。"}, {"text": "柿子", "is_correct": false, "explanation": "shìzi 第二个音节声母不同（z 与 sh），意思是柿子。"}, {"text": "事实", "is_correct": false, "explanation": "shìshí 第二个音节声调不同（第二声与轻声），意思是事实。"}, {"text": "时事", "is_correct": false, "explanation": "shíshì 两个音节的声调都不同，意思是时事。"}, {"text": "实施", "is_correct": false, "explanation": "shíshī 两个音节的声调都不同，意思是实行、施行。"}], "explanations": {"试试": "正确。试试 shì shi 表示做一下看看。", "柿子": "shìzi 第二个音节声母不同（z 与 sh），意思是柿子。", "事实": "shìshí 第二个音节声调不同（第二声与轻声），意思是事实。", "时事": "shíshì 两个音节的声调都不同，意思是时事。", "实施": "shíshī 两个音节的声调都不同，意思是实行、施行。"}, "sentence_index": null, "correct_answer": "试试"}, "level_3": {"options": [{"text": "试试", "is_correct": true, "explanation": "正确。“你试试吧”表示让对方做一下看看，符合句意。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：鞋子“很好看”，却说“你扔掉吧”，与句意相反。"}, {"text": "唱唱", "is_correct": false, "explanation": "语义：“唱”的对象不是鞋子，“这双鞋很好看，你唱唱吧”不通。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”要带议题作宾语，这里是劝对方试穿鞋子，不能用“讨论”。"}], "explanations": {"试试": "正确。“你试试吧”表示让对方做一下看看，符合句意。", "扔掉": "语义：鞋子“很好看”，却说“你扔掉吧”，与句意相反。", "唱唱": "语义：“唱”的对象不是鞋子，“这双鞋很好看，你唱唱吧”不通。", "讨论": "配价：“讨论”要带议题作宾语，这里是劝对方试穿鞋子，不能用“讨论”。"}, "sentence_index": 0, "correct_answer": "试试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府试试解决这一长期存在的社会问题。", "explanation": "这里应该用〈着手〉或〈努力〉。“试试”只表示随便做一下看看，用于长期的重大社会问题不合适。"}, {"text": "他试试很久才拿到了奖。", "explanation": "这里不这么用。“试试”表示随便做一下看看，时间很短，不能与“很久”连用。"}, {"text": "他试试三次都没成功，只好放弃。", "explanation": "这里不这么用。“试试”表示随便做一下看看，不能用来表示多次认真的尝试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21096, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试试", "is_correct": true, "explanation": "正确。试试 shì shi 表示做一下看看。"}, {"text": "失事", "is_correct": false, "explanation": "shīshì 两个音节的声调都不同，意思是发生事故。"}, {"text": "实事", "is_correct": false, "explanation": "shíshì 第一个音节和第二个音节的声调都与“试试”不同，意思是实际的事情。"}, {"text": "世事", "is_correct": false, "explanation": "shìshì 第二个音节声调不同（第四声与轻声），意思是世间的事。"}], "explanations": {"试试": "正确。试试 shì shi 表示做一下看看。", "失事": "shīshì 两个音节的声调都不同，意思是发生事故。", "实事": "shíshì 第一个音节和第二个音节的声调都与“试试”不同，意思是实际的事情。", "世事": "shìshì 第二个音节声调不同（第四声与轻声），意思是世间的事。"}, "sentence_index": null, "correct_answer": "试试"}, "level_3": {"options": [{"text": "试试", "is_correct": true, "explanation": "正确。“明天我们试试坐地铁去，好吗？”是提议，符合句意。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡”不能带“坐地铁去”这样的动词短语，“明天我们睡坐地铁去”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣服、碗等物品，不能带“坐地铁去”这样的动词短语，“明天我们洗坐地铁去”不成立。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与提议去坐地铁的语境矛盾。"}], "explanations": {"试试": "正确。“明天我们试试坐地铁去，好吗？”是提议，符合句意。", "睡": "搭配：“睡”不能带“坐地铁去”这样的动词短语，“明天我们睡坐地铁去”不成立。", "洗": "搭配：“洗”的宾语是衣服、碗等物品，不能带“坐地铁去”这样的动词短语，“明天我们洗坐地铁去”不成立。", "讨厌": "语义：“讨厌”表示反感，与提议去坐地铁的语境矛盾。"}, "sentence_index": 6, "correct_answer": "试试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不小心试试这个按钮，才发现它坏了。", "explanation": "这里不这么用。“试试”表示有意去做一下看看，不能与“不小心”连用。"}, {"text": "这家公司试试改变整个行业的规则。", "explanation": "这里应该用〈试图〉。“试图”是书面用语，用于重大的事；“试试”口语化，只表示随便做一下看看。"}, {"text": "我每天都试试跑步，已经坚持了一年。", "explanation": "这里不这么用。“试试”表示只做一下看看，不能用于长期的习惯，与“坚持了一年”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他试试了那辆车的刹车。", "corrected_sentence": "他试了试那辆车的刹车。", "error_description": "体标错误：重叠形式“试试”后面不能直接加“了”，应说“试了试”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要是喜欢，就自己试试一下吧。", "corrected_sentence": "你要是喜欢，就自己试试吧。", "error_description": "重复错误：“试试”已表示“做一下看看”，后面不能再加“一下”，应说“自己试试吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
