INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "菜叶是菜上可以吃的叶子。", "primary_collocate": null, "pronunciation": "cài yè", "ipa": "tsʰaɪ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这片菜叶很绿。", "target_word": "菜叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兔子喜欢吃菜叶。", "target_word": "菜叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把菜叶洗干净。", "target_word": "菜叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把菜叶切成小片。", "target_word": "菜叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜叶上有一只小虫。", "target_word": "菜叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种菜的菜叶可以做汤。", "target_word": "菜叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把坏了的菜叶放在了桶里。", "target_word": "菜叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有很多黄菜叶。", "target_word": "菜叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不吃菜根，只吃菜叶。", "target_word": "菜叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "菜叶没洗干净，里面还有土。", "target_word": "菜叶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "菜叶子", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：蔬菜上可以吃的叶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜叶", "is_correct": true, "explanation": "正确。菜叶是蔬菜上可以吃的叶子，可以说“这片菜叶”。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪是白色的，不能说“这片雪很绿”。"}, {"text": "白纸", "is_correct": false, "explanation": "语义：白纸是白色的，与“很绿”不符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：量词“片”一般不用于作业，不说“这片作业”。"}], "explanations": {"菜叶": "正确。菜叶是蔬菜上可以吃的叶子，可以说“这片菜叶”。", "雪": "语义：雪是白色的，不能说“这片雪很绿”。", "白纸": "语义：白纸是白色的，与“很绿”不符。", "作业": "搭配：量词“片”一般不用于作业，不说“这片作业”。"}, "sentence_index": 0, "correct_answer": "菜叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗菜叶很绿。", "explanation": "这里应该用〈片〉。菜叶的量词是“片”，不说“颗”。"}, {"text": "我家的菜叶有三层楼。", "explanation": "这里不能用〈菜叶〉指建筑。菜叶是蔬菜的叶子，不是房屋。"}, {"text": "他把菜叶当成书包背在身上。", "explanation": "这里用错了〈菜叶〉的用途。菜叶是供人食用的叶子，不能当作背负的容器，应说“他把东西装进了篮子里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜叶", "is_correct": true, "explanation": "正确。他把坏了的菜叶放进了桶里，指蔬菜的叶子。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴装不进桶里，与“放在了桶里”不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能放进桶里，与句意冲突。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：放在桶里的一般是蔬果或垃圾，“坏了的空调”不这样搭配。"}], "explanations": {"菜叶": "正确。他把坏了的菜叶放进了桶里，指蔬菜的叶子。", "钢琴": "语义：钢琴装不进桶里，与“放在了桶里”不符。", "房子": "语义：房子不能放进桶里，与句意冲突。", "空调": "搭配：放在桶里的一般是蔬果或垃圾，“坏了的空调”不这样搭配。"}, "sentence_index": 6, "correct_answer": "菜叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "菜叶今天考试考了九十分。", "explanation": "这里用错了主语。菜叶是植物的叶子，不会参加考试。"}, {"text": "我用菜叶写了一封信。", "explanation": "这里用错了用途。菜叶不能用来写字，不能当作纸张。"}, {"text": "我们在菜叶里面上网。", "explanation": "这里用错了场所。菜叶不是可以进入或使用的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把一颗菜叶洗干净了。", "corrected_sentence": "妈妈把一片菜叶洗干净了。", "error_description": "错误：菜叶的量词是“片”，不是“颗”。正确：一片菜叶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把一朵菜叶扔进了垃圾桶。", "corrected_sentence": "我们把一片菜叶扔进了垃圾桶。", "error_description": "错误：菜叶的量词是“片”，不是“朵”。正确：把一片菜叶扔进了垃圾桶。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
