INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西吃完后剩下的部分。", "primary_collocate": null, "pronunciation": "zhā", "ipa": "ʈʂa˥", "syllable_count": 1, "sentences": [{"text": "小孩吃饼干，桌子上掉了很多渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蛋糕很干，吃的时候桌上到处都是渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完水果，盘子里只剩下一点渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃完饼，手上还有渣。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃螃蟹时，别把壳和渣放在桌上。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把桌上的渣擦干净。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我吃完薯片，衣服上全是渣。", "target_word": "渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饼干的时候，渣掉进了书里。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃得很干净，碗里一点渣也没有。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在地上找吃剩的渣。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "面包渣", "label": "复合"}], "register": "中性", "sense_fingerprint": "吃东西时掉下或吃完后剩下的碎屑、残余，如饼干渣、骨头渣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31afd34d-968e-49ad-b38e-18c0dc13cb10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。"}, {"text": "炸", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“油炸”。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。"}, {"text": "遮", "is_correct": false, "explanation": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}], "explanations": {"渣": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。", "炸": "zhà（第四声）与 zhā（第一声）声调不同，意思是“油炸”。", "叉": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。", "张": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。", "遮": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。", "眨": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。吃饼干时掉下的碎屑正是“渣”，与语境相符。"}, {"text": "电线", "is_correct": false, "explanation": "语义：吃饼干时掉下的是碎屑，不会是电线。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“掉”后面一般不接大件家电，“掉了很多冰箱”不成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是大型乐器，“掉了很多钢琴”不合常理，与吃饼干的场景不符。"}], "explanations": {"渣": "正确。吃饼干时掉下的碎屑正是“渣”，与语境相符。", "电线": "语义：吃饼干时掉下的是碎屑，不会是电线。", "冰箱": "搭配：“掉”后面一般不接大件家电，“掉了很多冰箱”不成立。", "钢琴": "语义：钢琴是大型乐器，“掉了很多钢琴”不合常理，与吃饼干的场景不符。"}, "sentence_index": 0, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃饼干时，最香的部分是渣。", "explanation": "这里应该用〈饼干〉。渣是吃完后剩下的碎屑，最香的应是饼干本身，不能说“渣”最香。"}, {"text": "这杯可乐上面都是渣。", "explanation": "这里应该用〈泡沫〉。渣指吃完后剩下的碎屑，可乐表面的气泡要说“泡沫”，不能说“渣”。"}, {"text": "这碗面的渣很鲜。", "explanation": "这里应该用〈汤汁〉。渣指吃完后剩下的碎屑，有鲜味的汤汁不能说成“渣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91cf8f18-fd7b-49aa-8a87-20bdad845f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。"}, {"text": "榨", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。"}, {"text": "章", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。"}, {"text": "闸", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}], "explanations": {"渣": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。", "榨": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。", "插": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。", "章": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。", "闸": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。吃薯片后衣服上沾满的碎屑正是“渣”。"}, {"text": "血", "is_correct": false, "explanation": "语义：吃薯片不会让衣服上沾满血。"}, {"text": "雪", "is_correct": false, "explanation": "语义：吃薯片的语境下，衣服上不会是雪。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“玻璃”是锋利的碎片，与吃薯片后沾在衣服上的碎屑不搭配。"}], "explanations": {"渣": "正确。吃薯片后衣服上沾满的碎屑正是“渣”。", "血": "语义：吃薯片不会让衣服上沾满血。", "雪": "语义：吃薯片的语境下，衣服上不会是雪。", "玻璃": "搭配：“玻璃”是锋利的碎片，与吃薯片后沾在衣服上的碎屑不搭配。"}, "sentence_index": 6, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "盘子里还剩一根渣。", "explanation": "这里应该用〈点〉。“根”用于细长的东西，碎屑不能用“根”计量。"}, {"text": "桌上有一只渣。", "explanation": "这里应该用〈点〉。“只”多用于动物或成对的物品，碎屑不用“只”来计量。"}, {"text": "他的衣服上沾了一条渣。", "explanation": "这里应该用〈点〉。“条”用于细长的物品，碎屑不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91cf8f18-fd7b-49aa-8a87-20bdad845f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裤子上还有一根渣。", "corrected_sentence": "裤子上还有一点渣。", "error_description": "量词错误：“根”用于细长的东西，渣是细碎的碎屑，不能用“根”计量，应说“一点渣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91cf8f18-fd7b-49aa-8a87-20bdad845f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃完饼干，桌上还有一只渣。", "corrected_sentence": "吃完饼干，桌上还有一点渣。", "error_description": "量词错误：“只”多用于动物，渣是细碎的碎屑，不能用“只”计量，应说“一点渣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91cf8f18-fd7b-49aa-8a87-20bdad845f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "这个词表示事情是真的，不是假的。", "primary_collocate": null, "pronunciation": "qí shí", "ipa": "tɕʰi˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他看起来很凶，其实人很好。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为这很难，其实一点也不难。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她二十岁，其实她已经三十了。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服看着很贵，其实只要五十块。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说他不会做饭，其实他做得很好。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说没问题，其实心里有点怕。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店看着很小，其实里面很大。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得英语难，其实多说就会了。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说没事，其实她很难过。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家以为他是老师，其实他是医生。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，指出事情真实的情况，常与前面看起来或以为的情况相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "其实", "is_correct": true, "explanation": "正确。“其实”表示事情真实的情况，与前面的看法相反。"}, {"text": "七十", "is_correct": false, "explanation": "第一音节 qī（第一声）与 qí（第二声）声调不同，意思是七十。"}, {"text": "骑士", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是骑士。"}, {"text": "启示", "is_correct": false, "explanation": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是启示。"}], "explanations": {"其实": "正确。“其实”表示事情真实的情况，与前面的看法相反。", "七十": "第一音节 qī（第一声）与 qí（第二声）声调不同，意思是七十。", "骑士": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是骑士。", "启示": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是启示。"}, "sentence_index": null, "correct_answer": "其实"}, "level_3": {"options": [{"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，不能表示与“看起来很凶”相反的情况。"}, {"text": "其实", "is_correct": true, "explanation": "正确。“其实”引出与“看起来很凶”相反的真实情况，形成转折。"}, {"text": "反正", "is_correct": false, "explanation": "语义：“反正”表示不论怎样，与前面的印象没有转折关系。"}, {"text": "诚然", "is_correct": false, "explanation": "语义：“诚然”表示承认前面的情况属实，不能引出与“看起来很凶”相反的真实情况。"}], "explanations": {"果然": "语义：“果然”表示与预料相符，不能表示与“看起来很凶”相反的情况。", "其实": "正确。“其实”引出与“看起来很凶”相反的真实情况，形成转折。", "反正": "语义：“反正”表示不论怎样，与前面的印象没有转折关系。", "诚然": "语义：“诚然”表示承认前面的情况属实，不能引出与“看起来很凶”相反的真实情况。"}, "sentence_index": 0, "correct_answer": "其实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "其实你明天来吗？", "explanation": "这里应该用〈真的〉。“其实”用于陈述真实情况，不用于询问；问别人是否真的要来，应说“你真的明天来吗”。"}, {"text": "请你其实坐下。", "explanation": "这里不用〈其实〉。“其实”用于说明真实情况，不能修饰请求或命令，放在祈使句里与请求的语气不相容。"}, {"text": "如果明天下雨，其实我们就不去了。", "explanation": "这里不用〈其实〉。“其实”引出已经存在的真实情况，不能用在假设的条件句里；假设只用“如果……就……”来表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "其实", "is_correct": true, "explanation": "正确。“其实”表示事情真实的情况，与前面的看法相反。"}, {"text": "奇事", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是奇怪的事。"}, {"text": "启事", "is_correct": false, "explanation": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是公告。"}, {"text": "气势", "is_correct": false, "explanation": "两个音节声调都不同：qì（第四声）、shì（第四声），意思是气派和声势。"}], "explanations": {"其实": "正确。“其实”表示事情真实的情况，与前面的看法相反。", "奇事": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是奇怪的事。", "启事": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是公告。", "气势": "两个音节声调都不同：qì（第四声）、shì（第四声），意思是气派和声势。"}, "sentence_index": null, "correct_answer": "其实"}, "level_3": {"options": [{"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示因某种情况而避免了坏结果，与这里的转折不符。"}, {"text": "其实", "is_correct": true, "explanation": "正确。“其实”引出与“看着很小”相反的真实情况，形成转折。"}, {"text": "总算", "is_correct": false, "explanation": "语义：“总算”表示经过努力终于有了结果，与“看着很小”的对比无关。"}, {"text": "固然", "is_correct": false, "explanation": "配价：“固然”后面要接“但是”或“却”等转折词，这里没有。"}], "explanations": {"幸亏": "语义：“幸亏”表示因某种情况而避免了坏结果，与这里的转折不符。", "其实": "正确。“其实”引出与“看着很小”相反的真实情况，形成转折。", "总算": "语义：“总算”表示经过努力终于有了结果，与“看着很小”的对比无关。", "固然": "配价：“固然”后面要接“但是”或“却”等转折词，这里没有。"}, "sentence_index": 6, "correct_answer": "其实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你其实别再等了。", "explanation": "这里不用〈其实〉。“其实”用于说明真实情况，不能修饰请求或命令，劝对方别等时不能用它。"}, {"text": "他昨天其实了三本书。", "explanation": "这里不用〈其实〉。“其实”是副词，不能当动词带宾语，句子缺少真正的动词，如“看了”。"}, {"text": "如果你不来，其实我们就去公园。", "explanation": "这里不用〈其实〉。“其实”引出已经存在的真实情况，不能用在假设的条件句里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区看着很旧，其实的环境很好。", "corrected_sentence": "这个小区看着很旧，其实环境很好。", "error_description": "错误在“其实的”：“其实”是副词，不能加“的”修饰名词；应去掉“的”，写作“其实环境很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表面上看他很安静，其实了很爱说话。", "corrected_sentence": "表面上看他很安静，其实很爱说话。", "error_description": "错误在“其实了”：“其实”是副词，后面不能加“了”；应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
