INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西往里面丢", "primary_collocate": null, "pronunciation": "rēng jìn", "ipa": "ɻəŋ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "别把香蕉皮扔进花盆里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把剩饭扔进了垃圾袋。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们比赛，看谁能把球扔进筐里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙扔进包里，就出门了。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把那封信扔进了火里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把垃圾分好，再扔进不同的桶里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把旧报纸扔进了回收箱。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一块面包扔进湖里喂鱼。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把脏袜子扔进洗衣篮里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电池扔进专门的回收桶。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔进去", "label": "趋向补语"}, {"form": "扔进来", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "把东西往里面丢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔进", "is_correct": true, "explanation": "扔进：把东西往里面丢，与“别把香蕉皮……花盆里”的动作相符。"}, {"text": "种进", "is_correct": false, "explanation": "语义：“种”指栽种植物，不能说把香蕉皮种进花盆。"}, {"text": "插进", "is_correct": false, "explanation": "搭配：“插进”多用于细长的东西，香蕉皮不说插进。"}, {"text": "挂进", "is_correct": false, "explanation": "配价：“挂”后要接“在……上”一类的处所，不能直接接“花盆里”。"}], "explanations": {"扔进": "扔进：把东西往里面丢，与“别把香蕉皮……花盆里”的动作相符。", "种进": "语义：“种”指栽种植物，不能说把香蕉皮种进花盆。", "插进": "搭配：“插进”多用于细长的东西，香蕉皮不说插进。", "挂进": "配价：“挂”后要接“在……上”一类的处所，不能直接接“花盆里”。"}, "sentence_index": 0, "correct_answer": "扔进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把鸡蛋轻轻地扔进了篮子里，生怕摔碎。", "explanation": "这里应该用〈放进〉。扔进是把东西丢进去，与“轻轻地”“生怕摔碎”矛盾，易碎的鸡蛋要轻放，应用“放进”。"}, {"text": "妈妈把衣服整整齐齐地扔进了行李箱。", "explanation": "这里应该用〈放进〉。扔进是随手丢进去，与“整整齐齐”矛盾，把衣服整齐地装入箱子应用“放进”。"}, {"text": "他把书扔进了桌子上，然后走了。", "explanation": "这里应该用〈放在〉。扔进要求进入某个内部空间，桌面是平面，不能说“扔进……上”，应说“放在”或“扔到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔进", "is_correct": true, "explanation": "扔进：把东西往里面丢，与“爸爸把旧报纸……了回收箱”相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚毁，与“回收箱”的回收用途相矛盾。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”要接买方，不能说卖了回收箱。"}, {"text": "保留", "is_correct": false, "explanation": "语义：“保留”指留下不丢，与“回收箱”的处理方式相反。"}], "explanations": {"扔进": "扔进：把东西往里面丢，与“爸爸把旧报纸……了回收箱”相符。", "烧": "语义：“烧”是焚毁，与“回收箱”的回收用途相矛盾。", "卖": "配价：“卖”要接买方，不能说卖了回收箱。", "保留": "语义：“保留”指留下不丢，与“回收箱”的处理方式相反。"}, "sentence_index": 6, "correct_answer": "扔进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把螺丝扔进了木板里。", "explanation": "这里应该用〈拧进〉。扔进表示抛投，把螺丝固定到木板里要用“拧进”。"}, {"text": "妈妈慢慢地把汤扔进了碗里。", "explanation": "这里应该用〈倒进〉。扔进是抛投，汤这类液体要用“倒进”，且与“慢慢地”矛盾。"}, {"text": "他把汽油扔进了油箱，怕溢出来。", "explanation": "这里应该用〈灌进〉。把液体装入容器要用“灌进”，扔进不适用于汽油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把垃圾扔进了窗外，就去上班了。", "corrected_sentence": "妈妈把垃圾扔到窗外，就去上班了。", "error_description": "错误：“扔进”要求进入某个内部空间，“窗外”不是；应改用“扔到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把剩菜扔进着垃圾桶，然后洗手。", "corrected_sentence": "他把剩菜扔进了垃圾桶，然后洗手。", "error_description": "错误：“扔进着”；正确：“扔进了”。“着”表示持续的状态，这里是一次完成的动作，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
