INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公交站旁边有一个垃圾桶们。", "corrected_sentence": "公交站旁边有一个垃圾桶。", "error_description": "词尾错误：“们”表示复数，只用于人，垃圾桶是物，应说“一个垃圾桶”，不能说“垃圾桶们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91cf8f18-fd7b-49aa-8a87-20bdad845f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
