INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21126, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子外面有围墙的空地。", "primary_collocate": null, "pronunciation": "yuàn zi", "ipa": "ɥɛn˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他家的院子有高高的围墙。", "target_word": "院子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在院子里跑来跑去。", "target_word": "院子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出了房门就是院子。", "target_word": "院子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "院子里有一口老井。", "target_word": "院子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸在院子里修自行车。", "target_word": "院子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们院子的门口有两棵树。", "target_word": "院子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，邻居们喜欢坐在院子里聊天。", "target_word": "院子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子不大，可是他种满了菜。", "target_word": "院子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨后，院子里到处都是水。", "target_word": "院子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里停着一辆旧车。", "target_word": "院子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "院子：房子外面有围墙的空地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '595ff53b-3f8d-47f8-b6b1-a4bfc88e2a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "院子", "is_correct": true, "explanation": "正确：“院子”指房子外面有围墙的空地，符合“他家的院子有高高的围墙”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是有围墙的场所，不能说“有高高的围墙”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能围上围墙，与句意不符。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“有围墙”只用于建筑或场地，“故事”不与之搭配。"}], "explanations": {"院子": "正确：“院子”指房子外面有围墙的空地，符合“他家的院子有高高的围墙”。", "钥匙": "语义：钥匙不是有围墙的场所，不能说“有高高的围墙”。", "冰箱": "语义：冰箱不能围上围墙，与句意不符。", "故事": "搭配：“有围墙”只用于建筑或场地，“故事”不与之搭配。"}, "sentence_index": 0, "correct_answer": "院子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一辆院子。", "explanation": "这里应该用〈个〉。“辆”用于车辆，院子应用“个”或“座”。"}, {"text": "他推开院子走进房间。", "explanation": "这里应该用〈门〉。“推开”的对象是门或窗，院子不能被推开。"}, {"text": "我们把院子装进书包里。", "explanation": "这里误把〈院子〉当成了能装进书包的小东西（如〈钥匙〉）。“院子”是房前屋后的空地，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "院子", "is_correct": true, "explanation": "正确：邻居们在“院子”里聊天，符合“坐在……里聊天”的语境。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：人不能坐在瓶子里聊天，句意不通。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱是投信的小箱子，坐不下人。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“树叶”不是可以坐人的场所，“坐在……里”不与它搭配。"}], "explanations": {"院子": "正确：邻居们在“院子”里聊天，符合“坐在……里聊天”的语境。", "瓶子": "语义：人不能坐在瓶子里聊天，句意不通。", "信箱": "语义：信箱是投信的小箱子，坐不下人。", "树叶": "搭配：“树叶”不是可以坐人的场所，“坐在……里”不与它搭配。"}, "sentence_index": 6, "correct_answer": "院子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们爬上院子看星星。", "explanation": "这里应该用〈屋顶〉。“爬上”要求有高度的地方，院子是平地，不能爬上去。"}, {"text": "我家有一幅院子，很大。", "explanation": "量词错误：这里应该用〈个〉。“幅”用于图画等平面的东西，院子不说“幅”。"}, {"text": "他打开院子透气。", "explanation": "这里应该用〈窗户〉。“打开”用于门窗，院子是空地，不能被打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷家的院子们有一棵老枣树。", "corrected_sentence": "爷爷家的院子有一棵老枣树。", "error_description": "多加了“们”：院子是无生命的场所名词，不能加复数“们”。应去掉“们”，说“院子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨后，院子的里到处都是泥。", "corrected_sentence": "下雨后，院子里到处都是泥。", "error_description": "多加了“的”：方位词“里”要直接接在“院子”后面，中间不能加“的”。应去掉“的”，说“院子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
