INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "空气能进到里面去。", "primary_collocate": null, "pronunciation": "tòu qì", "ipa": "tʰou̯˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "种子发芽前，土要松一松，好让根透气。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖子留个缝，锅里才能透气。", "target_word": "透气", "complexity_tier": "T3", "furigana": "gài zi liú gè fèng, guō lǐ cái néng tòu qì.", "sentence_source": "generated"}, {"text": "把窗户打开，让屋子透透气。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆底下要有洞，不然土里不透气。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子太满，里面不透气，水果容易烂。", "target_word": "透气", "complexity_tier": "T3", "furigana": "xiāng zi tài mǎn, lǐ miàn bù tòu qì, shuǐ guǒ róng yì làn.", "sentence_source": "generated"}, {"text": "把被子晾在外面，让它透透气。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋放在鞋柜里太久了，拿出来让它透气吧。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋盒上扎了几个小孔，好让里面透气。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的鞋有味道，放在阳台透透气，味道就没了。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土太硬，根不透气，要松一松。", "target_word": "透气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "透透气", "label": "重叠"}, {"form": "透气孔", "label": "复合"}], "register": "中性", "sense_fingerprint": "让空气进入某处、使之通风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '595ff53b-3f8d-47f8-b6b1-a4bfc88e2a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "透气", "is_correct": true, "explanation": "正确答案：透气（tòu qì），指让空气进入某处、使之通风。"}, {"text": "漏气", "is_correct": false, "explanation": "lòu 与 tòu 声母不同（l 与 t），意思是漏气，即气体跑出去。"}, {"text": "斗气", "is_correct": false, "explanation": "dòu 与 tòu 声母不同（d 与 t），意思是斗气，即赌气、闹别扭。"}, {"text": "投契", "is_correct": false, "explanation": "tóu（第二声）与 tòu（第四声）声调不同，意思是投契，即很合得来。"}], "explanations": {"透气": "正确答案：透气（tòu qì），指让空气进入某处、使之通风。", "漏气": "lòu 与 tòu 声母不同（l 与 t），意思是漏气，即气体跑出去。", "斗气": "dòu 与 tòu 声母不同（d 与 t），意思是斗气，即赌气、闹别扭。", "投契": "tóu（第二声）与 tòu（第四声）声调不同，意思是投契，即很合得来。"}, "sentence_index": null, "correct_answer": "透气"}, "level_3": {"options": [{"text": "透气", "is_correct": true, "explanation": "“土要松一松，好让根透气”，松土是为了让空气进入土里，与语境相符。"}, {"text": "保暖", "is_correct": false, "explanation": "语义：松土是为了让根获得空气，与“保暖”的目的不符。"}, {"text": "变硬", "is_correct": false, "explanation": "语义：“土要松一松”，“变硬”与松土的目的正相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“根”不会“睡觉”，主语与动词不搭配。"}], "explanations": {"透气": "“土要松一松，好让根透气”，松土是为了让空气进入土里，与语境相符。", "保暖": "语义：松土是为了让根获得空气，与“保暖”的目的不符。", "变硬": "语义：“土要松一松”，“变硬”与松土的目的正相反。", "睡觉": "搭配：“根”不会“睡觉”，主语与动词不搭配。"}, "sentence_index": 0, "correct_answer": "透气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些碗要透气，才能给宝宝用。", "explanation": "这里应该用〈消毒〉。透气指空气进入，碗的杀菌要说“消毒”。"}, {"text": "这块冰要透透气，才能化得快。", "explanation": "这里应该用〈融化〉。冰变成水要说“融化”，“透气”指让空气进入，不能用于冰的变化。"}, {"text": "这块玻璃很透气，阳光能照进来。", "explanation": "这里应该用〈透明〉。玻璃让光线穿过要说“透明”，“透气”指空气流通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透气", "is_correct": true, "explanation": "透气：让鞋在空气中流通，与“放在鞋柜里太久了”的语境相符。"}, {"text": "上锁", "is_correct": false, "explanation": "语义：上锁是为了关住东西，与“拿出来”的目的相反。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：鞋不能“洗澡”，主语与动词不搭配。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：鞋不会“吃饭”，“吃饭”与“鞋”的搭配不成立。"}], "explanations": {"透气": "透气：让鞋在空气中流通，与“放在鞋柜里太久了”的语境相符。", "上锁": "语义：上锁是为了关住东西，与“拿出来”的目的相反。", "洗澡": "搭配：鞋不能“洗澡”，主语与动词不搭配。", "吃饭": "搭配：鞋不会“吃饭”，“吃饭”与“鞋”的搭配不成立。"}, "sentence_index": 6, "correct_answer": "透气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子透气效果很好，装热水不容易凉。", "explanation": "这里应该用〈保温〉。透气是让空气进入，杯子保持热水温度要说“保温”。"}, {"text": "这盒牛奶要透气，才不会坏。", "explanation": "这里应该用〈冷藏〉。透气指空气进入，保存牛奶要说“冷藏”。"}, {"text": "这锅粥要慢慢透气，不能急。", "explanation": "这里应该用〈熬煮〉。煮粥要说“熬煮”，“透气”指让空气进入，不能用于煮粥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱子要开个小口，好让里面不透气。", "corrected_sentence": "箱子要开个小口，好让里面透气。", "error_description": "多加了“不”：开小口是为了让里面透气，加上“不”后变成“不透气”，与前面的目的相矛盾，应去掉“不”，写作“好让里面透气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳台的风很大，让屋里透气透。", "corrected_sentence": "阳台的风很大，让屋里透透气。", "error_description": "错误形式“透气透”，正确形式“透透气”。动词重叠要把整个动词重叠，写成“透透气”，不能拆开。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
