INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21138, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21138, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或力气把东西分成一块一块的。", "primary_collocate": null, "pronunciation": "sī suì", "ipa": "sɨ˥ suei˥˩", "syllable_count": 2, "sentences": [{"text": "他把那封旧信撕碎，扔进了垃圾桶。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟生气地撕碎了作业本。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把枕头撕碎了，里面的棉花飞出来。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面包撕碎，放进汤里。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先把纸撕碎，然后再丢掉。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧衣服可以撕碎，当抹布用。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看完日记，就把它撕碎了。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人撕碎了一张旧照片。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩得很开心，把彩纸撕碎了。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么要把我的画撕碎？", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撕碎了", "label": "体标"}, {"form": "撕碎过", "label": "体标"}], "register": "中性", "sense_fingerprint": "撕碎：用手把东西撕成一块一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1bd4ef5-97b2-41c8-b5f8-10c80ead5322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撕碎", "is_correct": true, "explanation": "正确。“他把那封旧信撕碎，扔进了垃圾桶”，撕碎后再扔掉，前后连贯。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：收藏的东西一般不会扔进垃圾桶，与“扔进了垃圾桶”相矛盾。"}, {"text": "保管", "is_correct": false, "explanation": "语义：保管是为了留存，与后面“扔进了垃圾桶”的处理矛盾。"}, {"text": "熨平", "is_correct": false, "explanation": "搭配：“熨平”用于衣物、布料，不用来处理旧信。"}], "explanations": {"撕碎": "正确。“他把那封旧信撕碎，扔进了垃圾桶”，撕碎后再扔掉，前后连贯。", "收藏": "语义：收藏的东西一般不会扔进垃圾桶，与“扔进了垃圾桶”相矛盾。", "保管": "语义：保管是为了留存，与后面“扔进了垃圾桶”的处理矛盾。", "熨平": "搭配：“熨平”用于衣物、布料，不用来处理旧信。"}, "sentence_index": 0, "correct_answer": "撕碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花瓶被风吹倒，撕碎了。", "explanation": "这里应该用〈打碎〉。花瓶是硬物，应说打碎；“撕碎”用于纸、布等软的东西。"}, {"text": "盘子从桌上掉下来，撕碎了。", "explanation": "这里应该用〈摔碎〉。盘子落地应说摔碎，瓷器不能用“撕碎”。"}, {"text": "工人用铁锤把冰块撕碎了。", "explanation": "这里应该用〈砸碎〉。用铁锤敲击冰块应说砸碎，冰块不能撕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撕碎", "is_correct": true, "explanation": "正确。“看完日记，就把它撕碎了”，看完后撕碎是合理的处理方式。"}, {"text": "擦干净", "is_correct": false, "explanation": "搭配：“擦干净”用于桌面等表面，不用来处理日记。"}, {"text": "烤焦", "is_correct": false, "explanation": "语义：日记被烤焦不是一般的处理方式，与“看完日记，就把它……”的语境不符。"}, {"text": "浇湿", "is_correct": false, "explanation": "语义：把日记浇湿与看完后的处理不符，且不是常见的做法。"}], "explanations": {"撕碎": "正确。“看完日记，就把它撕碎了”，看完后撕碎是合理的处理方式。", "擦干净": "搭配：“擦干净”用于桌面等表面，不用来处理日记。", "烤焦": "语义：日记被烤焦不是一般的处理方式，与“看完日记，就把它……”的语境不符。", "浇湿": "语义：把日记浇湿与看完后的处理不符，且不是常见的做法。"}, "sentence_index": 6, "correct_answer": "撕碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石磨把谷子撕碎了。", "explanation": "这里应该用〈碾碎〉。石磨碾的是谷物颗粒，撕碎只用于纸、布等薄物。"}, {"text": "他用锤子把核桃撕碎了。", "explanation": "这里应该用〈砸碎〉。用锤子敲硬核桃应说砸碎，硬东西不能撕。"}, {"text": "他跌倒了，膝盖被撕碎了。", "explanation": "这里应该用〈擦破〉。皮肤受伤应说擦破，不能说撕碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他信撕碎了。", "corrected_sentence": "他把信撕碎了。", "error_description": "漏用“把”：“撕碎”的宾语“信”前要加“把”，应为“他把信撕碎了”，不能说“他信撕碎了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没把照片撕碎了。", "corrected_sentence": "她没把照片撕碎。", "error_description": "体貌错误：“没”表示否定，与“了”不能同用，应为“她没把照片撕碎”，不能说“她没把照片撕碎了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
