INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吃完饭后剩下的饭菜和果皮等垃圾。", "primary_collocate": null, "pronunciation": "chú yú", "ipa": "ʈʂʰu˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "吃完饭后剩下的饭菜是厨余。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家每天都会产生不少厨余。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把厨余倒进绿色的桶里。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩饭、菜叶和果皮都算厨余。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨余可以做肥料，给花园的植物用。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆每天有很多厨余。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口有专门的桶放厨余。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把厨余和别的垃圾分开放。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨余放久了会有味道，要早点倒掉。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校食堂的厨余每天送到农场去。", "target_word": "厨余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厨余垃圾", "label": "复合"}], "register": "中性", "sense_fingerprint": "做饭吃饭后剩下的饭菜、菜叶、果皮等垃圾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调料", "is_correct": false, "explanation": "语义：调料是用来给菜调味的，吃剩的饭菜不可能是调料。"}, {"text": "厨余", "is_correct": true, "explanation": "“厨余”指吃完饭后剩下的饭菜等垃圾，与句中的“剩下的饭菜”相符。"}, {"text": "宝石", "is_correct": false, "explanation": "搭配：“是”后面的名词应与“剩下的饭菜”相搭，“宝石”不能与之搭配。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是用来演奏的，剩下的饭菜不可能是乐器。"}], "explanations": {"调料": "语义：调料是用来给菜调味的，吃剩的饭菜不可能是调料。", "厨余": "“厨余”指吃完饭后剩下的饭菜等垃圾，与句中的“剩下的饭菜”相符。", "宝石": "搭配：“是”后面的名词应与“剩下的饭菜”相搭，“宝石”不能与之搭配。", "乐器": "语义：乐器是用来演奏的，剩下的饭菜不可能是乐器。"}, "sentence_index": 0, "correct_answer": "厨余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的厨余很好吃。", "explanation": "这里应该用〈食物〉。厨余指吃剩下、要扔掉的饭菜和果皮，不能用来形容能吃的食物。"}, {"text": "老师买了厨余回家做饭。", "explanation": "这里应该用〈食材〉。厨余是要扔掉的剩余物，不能用来做饭，买来做饭的应是食材。"}, {"text": "我们班的厨余都很聪明，经常得奖。", "explanation": "这里应该用〈同学〉。厨余是要扔掉的剩余物，不指人，班里的人应说“同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病毒", "is_correct": false, "explanation": "语义：病毒是致病的微生物，不会有专门的桶用来放病毒，句子不通。"}, {"text": "厨余", "is_correct": true, "explanation": "“厨余”是要扔进桶里的剩余物，与“放”和“桶”相符。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“放”的宾语应是可以盛放的具体物品，“情绪”不能放进桶里。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻是信息，不能放进桶里，句子意思不通。"}], "explanations": {"病毒": "语义：病毒是致病的微生物，不会有专门的桶用来放病毒，句子不通。", "厨余": "“厨余”是要扔进桶里的剩余物，与“放”和“桶”相符。", "情绪": "搭配：“放”的宾语应是可以盛放的具体物品，“情绪”不能放进桶里。", "新闻": "语义：新闻是信息，不能放进桶里，句子意思不通。"}, "sentence_index": 6, "correct_answer": "厨余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们最爱吃厨余。", "explanation": "这里应该用〈糖果〉。厨余是要扔掉的剩余物，不能吃，孩子们爱吃的是糖果。"}, {"text": "工人在矿上挖厨余。", "explanation": "这里应该用〈煤炭〉。厨余不是矿产，矿上挖出的是煤炭。"}, {"text": "他用厨余打开了门。", "explanation": "这里应该用〈钥匙〉。厨余不是开门的工具，开门要用钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈拿着一只厨余出门了。", "corrected_sentence": "妈妈拿着一袋厨余出门了。", "error_description": "“厨余”的量词错误。“只”多用于动物、碗、船等，不能用来计量厨余；应使用“袋”（或“桶”），写作“一袋厨余”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些厨余们都要倒掉。", "corrected_sentence": "这些厨余都要倒掉。", "error_description": "“厨余”是不可数的物质名词，不能加“们”表示复数。“们”只用于人，应写作“这些厨余”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
