INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21144, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "湿是东西里有水。", "primary_collocate": null, "pronunciation": "shī", "ipa": "ʂʅ˥", "syllable_count": 1, "sentences": [{"text": "洗完澡，浴室里的地板很湿。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨伞放在门口，伞上还是湿的。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别坐在湿椅子上。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条毛巾一点也不湿。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服洗完很湿，要晒一晒。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子湿了就能捏成形。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑过水坑，身上都湿了。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发湿了，好像刚洗过澡。", "target_word": "湿", "complexity_tier": "T3", "furigana": "tā de tóu fa shī le, hǎo xiàng gāng xǐ guò zǎo.", "sentence_source": "generated"}, {"text": "土是湿的，今天不用浇花。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子湿湿的，是谁洒了水？", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "湿透", "label": "复合"}, {"form": "潮湿", "label": "复合"}, {"form": "湿湿", "label": "重叠"}], "register": "中性", "sense_fingerprint": "东西里有水，不干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '595ff53b-3f8d-47f8-b6b1-a4bfc88e2a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿（shī），意思是东西里有水，不干。"}, {"text": "是", "is_correct": false, "explanation": "是（shì）与 shī 声调不同（第四声），意思是“是的”或判断。"}, {"text": "石", "is_correct": false, "explanation": "石（shí）与 shī 声调不同（第二声），意思是石头。"}, {"text": "使", "is_correct": false, "explanation": "使（shǐ）与 shī 声调不同（第三声），意思是使用、致使。"}, {"text": "食", "is_correct": false, "explanation": "食（shí）与 shī 声调不同（第二声），意思是食物。"}], "explanations": {"湿": "正确答案：湿（shī），意思是东西里有水，不干。", "是": "是（shì）与 shī 声调不同（第四声），意思是“是的”或判断。", "石": "石（shí）与 shī 声调不同（第二声），意思是石头。", "使": "使（shǐ）与 shī 声调不同（第三声），意思是使用、致使。", "食": "食（shí）与 shī 声调不同（第二声），意思是食物。"}, "sentence_index": null, "correct_answer": "湿"}, "level_3": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿。洗完澡后，地板带水，指地板上有水分。"}, {"text": "干", "is_correct": false, "explanation": "语义：洗完澡后地板很干与句意矛盾，干与“洗完澡”的语境不合。"}, {"text": "轻", "is_correct": false, "explanation": "语义：轻描述重量，与地板的状态无关，句子不通。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：瘦形容人或物体的粗细，不用于形容地板的湿度。"}], "explanations": {"湿": "正确答案：湿。洗完澡后，地板带水，指地板上有水分。", "干": "语义：洗完澡后地板很干与句意矛盾，干与“洗完澡”的语境不合。", "轻": "语义：轻描述重量，与地板的状态无关，句子不通。", "瘦": "搭配：瘦形容人或物体的粗细，不用于形容地板的湿度。"}, "sentence_index": 0, "correct_answer": "湿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡太湿了，我等一会儿再喝。", "explanation": "这里应该用〈烫〉。湿只形容东西里有水，不能形容温度高；咖啡太热要说烫。"}, {"text": "他的脾气很湿，大家都喜欢他。", "explanation": "这里应该用〈好〉。湿只形容东西里有水，不能形容脾气；说脾气好要用好。"}, {"text": "这个孩子很湿，老师都夸他。", "explanation": "这里应该用〈聪明〉。湿只形容东西里有水，不能形容人的智力；说孩子聪明要用聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21144, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿（shī），意思是东西里有水，不干。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与 shī 声调不同（第二声），意思是数字十。"}, {"text": "书", "is_correct": false, "explanation": "书（shū）与 shī 的韵母不同（u 与 i），意思是书籍。"}, {"text": "事", "is_correct": false, "explanation": "事（shì）与 shī 声调不同（第四声），意思是事情。"}, {"text": "思", "is_correct": false, "explanation": "思（sī）与 shī 声母不同（s 与 sh），意思是思考。"}], "explanations": {"湿": "正确答案：湿（shī），意思是东西里有水，不干。", "十": "十（shí）与 shī 声调不同（第二声），意思是数字十。", "书": "书（shū）与 shī 的韵母不同（u 与 i），意思是书籍。", "事": "事（shì）与 shī 声调不同（第四声），意思是事情。", "思": "思（sī）与 shī 声母不同（s 与 sh），意思是思考。"}, "sentence_index": null, "correct_answer": "湿"}, "level_3": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿。跑过水坑后身上沾水，指身上带有水分。"}, {"text": "干", "is_correct": false, "explanation": "语义：跑过水坑后身上干与句意矛盾，句子不通。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：饱形容吃得足，不能与“身上”搭配表示沾水的状态。"}, {"text": "亮", "is_correct": false, "explanation": "语义：亮形容光线或颜色，与跑过水坑后的状态无关。"}], "explanations": {"湿": "正确答案：湿。跑过水坑后身上沾水，指身上带有水分。", "干": "语义：跑过水坑后身上干与句意矛盾，句子不通。", "饱": "搭配：饱形容吃得足，不能与“身上”搭配表示沾水的状态。", "亮": "语义：亮形容光线或颜色，与跑过水坑后的状态无关。"}, "sentence_index": 6, "correct_answer": "湿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月他很湿，经常加班。", "explanation": "这里应该用〈忙〉。湿只形容东西里有水，不能形容人忙不忙；说人忙要用忙。"}, {"text": "他做事很湿，但很仔细。", "explanation": "这里应该用〈慢〉。湿只形容东西里有水，不能形容做事的快慢；说做事慢要用慢。"}, {"text": "学校很湿，我每天走路去。", "explanation": "这里应该用〈远〉。湿只形容东西里有水，不能形容距离；说学校远要用远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子跳进水里，把衣服弄了湿。", "corrected_sentence": "孩子跳进水里，把衣服弄湿了。", "error_description": "错误形式：弄了湿；正确形式：弄湿了。“湿”作结果补语，应紧跟在动词“弄”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌布湿了着，别急着摆碗。", "corrected_sentence": "桌布湿着，别急着摆碗。", "error_description": "错误形式：湿了着；正确形式：湿着。“湿”是形容词，表示状态持续只用“着”，不能与“了”同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3828f1d-1b4b-4256-8519-8eb00fda7e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
