INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "让人生病的小东西。", "primary_collocate": null, "pronunciation": "bìng yuán tǐ", "ipa": "piŋ⁵¹ ɥɛn³⁵ tʰi²¹⁴", "syllable_count": 3, "sentences": [{"text": "小孩爱吃手，容易吃进病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病原体太小，眼睛看不见。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用开水煮可以杀死病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脏水里有很多病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病原体进了身体，人就会发烧。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种病原体是细菌。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗菜时要洗掉上面的病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口罩能挡住一部分病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病是因为感染了病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的病原体用肥皂就能洗掉。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病原體", "label": "繁体"}], "register": "科技", "sense_fingerprint": "让人生病的微小东西，如细菌、病毒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3509aa1-4a67-4a10-8fe3-c2b181bf7e77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病原体", "is_correct": true, "explanation": "正确。病原体是让人生病的小东西，小孩可能会把它吃进去。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是实物，不能被吃进身体。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“吃进”多搭配食物或异物，不说吃进故事。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是东西，不能被吃进身体。"}], "explanations": {"病原体": "正确。病原体是让人生病的小东西，小孩可能会把它吃进去。", "声音": "语义：声音不是实物，不能被吃进身体。", "故事": "搭配：“吃进”多搭配食物或异物，不说吃进故事。", "颜色": "语义：颜色不是东西，不能被吃进身体。"}, "sentence_index": 0, "correct_answer": "病原体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑中了病原体。", "explanation": "这里应该用〈病毒〉。病原体是能让人生病的小东西，不能指电脑中的程序。"}, {"text": "我给朋友寄了一封病原体。", "explanation": "这里应该用〈信〉。“一封”用于信件，病原体是让人生病的微小东西，不能寄给朋友。"}, {"text": "做面包要用病原体。", "explanation": "这里应该用〈酵母〉。做面包要用酵母发酵，病原体会让人生病，不能用来做面包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病原体", "is_correct": true, "explanation": "正确。病原体会附着在蔬菜上，洗菜时可以被洗掉。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会附着在蔬菜上，句意不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不会附着在蔬菜上，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是实物，不会附着在菜上，不能被洗掉。"}], "explanations": {"病原体": "正确。病原体会附着在蔬菜上，洗菜时可以被洗掉。", "手机": "语义：手机不会附着在蔬菜上，句意不通。", "蔬菜": "语义：蔬菜不会附着在蔬菜上，句意不通。", "声音": "语义：声音不是实物，不会附着在菜上，不能被洗掉。"}, "sentence_index": 6, "correct_answer": "病原体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上刷了一层病原体。", "explanation": "这里应该用〈颜料〉。病原体是让人生病的小东西，不能用来刷墙。"}, {"text": "护士给他打了一针病原体。", "explanation": "这里应该用〈疫苗〉。打针用的是能预防疾病的疫苗，病原体会让人生病。"}, {"text": "妈妈在汤里放了一勺病原体。", "explanation": "这里应该用〈盐〉。汤里放的应是调味品，病原体不能用来调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多病原体们进了身体，人就会发烧。", "corrected_sentence": "很多病原体进了身体，人就会发烧。", "error_description": "“们”只用于指人，病原体不是人，不能加“们”表示复数，应说“很多病原体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说，这张病原体很危险。", "corrected_sentence": "医生说，这种病原体很危险。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西，病原体应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7f0748-37a2-4643-a9f5-6c5c410a975b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏忽", "is_correct": true, "explanation": "反义：疏忽表示不小心、不留心，与“注意身体”的保重之意相对。"}, {"text": "思考", "is_correct": false, "explanation": "思考是动脑子想问题，与注意没有反义关系。"}, {"text": "发现", "is_correct": false, "explanation": "发现与注意是近义关系，不是反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是一种运动，与注意没有语义上的对立关系。"}], "correct_answer": "疏忽", "explanations": {"疏忽": "反义：疏忽表示不小心、不留心，与“注意身体”的保重之意相对。", "思考": "思考是动脑子想问题，与注意没有反义关系。", "发现": "发现与注意是近义关系，不是反义关系。", "游泳": "游泳是一种运动，与注意没有语义上的对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏忽", "is_correct": true, "explanation": "反义：疏忽表示不小心、不留心，与“注意笔画”相对。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是一种活动，与注意没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是一种动作，与注意没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是一种运动，与注意没有反义关系。"}], "correct_answer": "疏忽", "explanations": {"疏忽": "反义：疏忽表示不小心、不留心，与“注意笔画”相对。", "唱歌": "唱歌是一种活动，与注意没有反义关系。", "写字": "写字是一种动作，与注意没有反义关系。", "跑步": "跑步是一种运动，与注意没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把眼睛和心思放在一个东西或一件事情上。", "primary_collocate": null, "pronunciation": "zhù yì", "ipa": "ʈʂu˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "过马路时要注意车。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课请注意听老师讲。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家注意，下面是重要的话。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，要注意身体。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候，一定要注意安全。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直注意着时间。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家注意一下，火车要开了。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走路要注意脚下，地上很滑。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃鱼的时候，注意别吃到刺。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你写字的时候要注意笔画。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注意了", "label": "体标"}, {"form": "注意过", "label": "体标"}, {"form": "注意着", "label": "体标"}], "register": "中性", "sense_fingerprint": "把心思放在某事上、小心留意（注意安全、注意听）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfc61dd-6a36-42c2-919d-a796ba291367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "注意", "is_correct": true, "explanation": "正确答案，与听到的读音一致，意思是小心留意。"}, {"text": "主义", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是“主义”。"}, {"text": "竹椅", "is_correct": false, "explanation": "两个音节的声调都不同，意思是“竹子做的椅子”。"}, {"text": "逐一", "is_correct": false, "explanation": "两个音节的声调都不同，意思是“一个接一个”。"}, {"text": "句意", "is_correct": false, "explanation": "j 与 zh 声母不同，意思是“句子的意思”。"}], "explanations": {"注意": "正确答案，与听到的读音一致，意思是小心留意。", "主义": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是“主义”。", "竹椅": "两个音节的声调都不同，意思是“竹子做的椅子”。", "逐一": "两个音节的声调都不同，意思是“一个接一个”。", "句意": "j 与 zh 声母不同，意思是“句子的意思”。"}, "sentence_index": null, "correct_answer": "注意"}, "level_3": {"options": [{"text": "注意", "is_correct": true, "explanation": "注意表示留心、小心，与“过马路时要……车”的安全语境相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记与“要”提示的安全要求相反，过马路时不应忘记车辆。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略是不予理会，与“过马路时要”的安全要求矛盾。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：讨论接话题或问题，不能接“车”这类实物作宾语。"}], "explanations": {"注意": "注意表示留心、小心，与“过马路时要……车”的安全语境相符。", "忘记": "语义：忘记与“要”提示的安全要求相反，过马路时不应忘记车辆。", "忽略": "语义：忽略是不予理会，与“过马路时要”的安全要求矛盾。", "讨论": "搭配：讨论接话题或问题，不能接“车”这类实物作宾语。"}, "sentence_index": 0, "correct_answer": "注意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿饭的注意很好吃。", "explanation": "注意是心思上的留心，不是可以吃的东西，这里误把它当成了实物。"}, {"text": "他一拳把注意打碎了。", "explanation": "注意是心思上的留心，无法被打碎，这里误把它当成了实物。"}, {"text": "妈妈把注意藏在了抽屉里。", "explanation": "注意是抽象的留心，不能藏进抽屉，这里误把它当成了实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注意", "is_correct": true, "explanation": "“注意一下”表示提醒大家留心，与“火车要开了”的提醒语境相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视是不予重视，与“请大家……火车要开了”的提醒语境矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，与“火车要开了”的紧迫语境冲突。"}, {"text": "吃饭", "is_correct": false, "explanation": "配价：吃饭是离合词，不能直接说成“吃饭一下”，且与火车要开的语境冲突。"}], "explanations": {"注意": "“注意一下”表示提醒大家留心，与“火车要开了”的提醒语境相符。", "忽视": "语义：忽视是不予重视，与“请大家……火车要开了”的提醒语境矛盾。", "散步": "语义：散步是悠闲的活动，与“火车要开了”的紧迫语境冲突。", "吃饭": "配价：吃饭是离合词，不能直接说成“吃饭一下”，且与火车要开的语境冲突。"}, "sentence_index": 6, "correct_answer": "注意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你写字的时候要把注意放进笔画里。", "explanation": "注意是抽象的留心，不能像物品一样放进笔画里，这里误把它当成了实物。"}, {"text": "你写字的时候要用注意擦掉笔画。", "explanation": "注意是心思上的留心，不能用来擦笔画，擦除笔迹应使用橡皮。"}, {"text": "你写字的时候要把注意借给别人。", "explanation": "注意属于自己的心思，不能借给别人，这里误把它当成了可以转让的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开车的时候要注意了红绿灯。", "corrected_sentence": "开车的时候要注意红绿灯。", "error_description": "错误：“要”表示要求，与动作完成的“了”不能同用，“了”应去掉。正确：“开车的时候要注意红绿灯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请大家注意一个，别走丢了。", "corrected_sentence": "请大家注意一下，别走丢了。", "error_description": "错误：“一个”是事物的量词，不能计量“注意”这一动作，动量应用“一下”。正确：“注意一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
