INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21154, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "一定要这样做。", "primary_collocate": null, "pronunciation": "xū", "ipa": "ɕy˥", "syllable_count": 1, "sentences": [{"text": "进入教室，须先关手机。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路须看红绿灯。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用前须仔细看说明。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客上车后须系好安全带。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生考试时须带身份证。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车须遵守交通规则。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药前须问医生。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛须在今天报名。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进房间前须脱鞋。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了机场，旅客须先办手续。", "target_word": "须", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "須", "label": "繁体"}, {"form": "无须", "label": "否定复合"}, {"form": "须知", "label": "复合"}], "register": "书面", "sense_fingerprint": "书面语中表示一定要、必须", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "须", "is_correct": true, "explanation": "正确答案。须读 xū，书面语中表示一定要这样做。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xū 声调不同，意思是允许。"}, {"text": "续", "is_correct": false, "explanation": "xù（第四声）与 xū 声调不同，意思是继续。"}, {"text": "徐", "is_correct": false, "explanation": "xú（第二声）与 xū 声调不同，意思是缓慢。"}], "explanations": {"须": "正确答案。须读 xū，书面语中表示一定要这样做。", "许": "xǔ（第三声）与 xū 声调不同，意思是允许。", "续": "xù（第四声）与 xū 声调不同，意思是继续。", "徐": "xú（第二声）与 xū 声调不同，意思是缓慢。"}, "sentence_index": null, "correct_answer": "须"}, "level_3": {"options": [{"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量去做，与“进入教室要先关手机”的规定语境不符。"}, {"text": "须", "is_correct": true, "explanation": "正确。“进入教室，须先关手机”表示必须遵守的要求，书面语色彩相合。"}, {"text": "许", "is_correct": false, "explanation": "配价：“许”作动词，要带“允许”的对象，不能直接修饰“先关手机”。"}, {"text": "愿", "is_correct": false, "explanation": "语义：“愿”表示自愿，与规定性要求“须先关手机”不符。"}], "explanations": {"敢": "语义：“敢”表示有胆量去做，与“进入教室要先关手机”的规定语境不符。", "须": "正确。“进入教室，须先关手机”表示必须遵守的要求，书面语色彩相合。", "许": "配价：“许”作动词，要带“允许”的对象，不能直接修饰“先关手机”。", "愿": "语义：“愿”表示自愿，与规定性要求“须先关手机”不符。"}, "sentence_index": 0, "correct_answer": "须"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里须吸烟。", "explanation": "这里应该用〈禁止〉。“须”表示一定要做，“须吸烟”就成了必须吸烟，禁烟的地方应说〈禁止吸烟〉。"}, {"text": "图书馆里须大声说话。", "explanation": "这里应该用〈不能〉。“须”表示一定要做，图书馆要求安静，应说〈不能大声说话〉。"}, {"text": "这个会你须参加，不来也行。", "explanation": "这里应该用〈可以〉。“须”表示一定要做，与“不来也行”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21154, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "须", "is_correct": true, "explanation": "正确答案。须读 xū，书面语中表示一定要这样做。"}, {"text": "序", "is_correct": false, "explanation": "xù（第四声）与 xū 声调不同，意思是顺序。"}, {"text": "旭", "is_correct": false, "explanation": "xù（第四声）与 xū 声调不同，意思是初升的太阳。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xū 声调不同，意思是允许。"}], "explanations": {"须": "正确答案。须读 xū，书面语中表示一定要这样做。", "序": "xù（第四声）与 xū 声调不同，意思是顺序。", "旭": "xù（第四声）与 xū 声调不同，意思是初升的太阳。", "许": "xǔ（第三声）与 xū 声调不同，意思是允许。"}, "sentence_index": null, "correct_answer": "须"}, "level_3": {"options": [{"text": "欲", "is_correct": false, "explanation": "语域：“欲”带文言色彩，与“吃药前问医生”这种口语化的叮嘱不协调。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示乐意，与“必须问医生”的规定义不符。"}, {"text": "须", "is_correct": true, "explanation": "正确。“吃药前须问医生”表示必须遵守的要求，书面语色彩相合。"}, {"text": "虽", "is_correct": false, "explanation": "语法：“虽”是连词，表让步，不能放在动词前作情态，“吃药前虽问医生”句意不通。"}], "explanations": {"欲": "语域：“欲”带文言色彩，与“吃药前问医生”这种口语化的叮嘱不协调。", "肯": "语义：“肯”表示乐意，与“必须问医生”的规定义不符。", "须": "正确。“吃药前须问医生”表示必须遵守的要求，书面语色彩相合。", "虽": "语法：“虽”是连词，表让步，不能放在动词前作情态，“吃药前虽问医生”句意不通。"}, "sentence_index": 6, "correct_answer": "须"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么热的天，你须穿棉袄。", "explanation": "这里应该用〈不用〉。“须”表示一定要做，天热时说“须穿棉袄”就成了必须穿，应说〈不用穿棉袄〉。"}, {"text": "我须一台新电脑。", "explanation": "这里应该用〈要〉。“须”是情态动词，后面只能接动词，不能直接带名词宾语；想要东西要说〈要〉。"}, {"text": "明天须下雨。", "explanation": "这里应该用〈可能〉。“须”表示必须，不表示推测，推测要用〈可能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "进入实验室穿须白大衣。", "corrected_sentence": "进入实验室须穿白大衣。", "error_description": "错误形式：「穿须白大衣」。正确形式：「须穿白大衣」。情态动词“须”要放在动词前面，不能放在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你没须来，我们会处理。", "corrected_sentence": "你无须来，我们会处理。", "error_description": "错误形式：「没须来」。正确形式：「无须来」。“须”不能用“没”否定，表示“不必”时说「无须」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
