INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剩下的东西。", "primary_collocate": null, "pronunciation": "cán yú", "ipa": "tsʰan˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "我把盘子里的残余倒进了垃圾桶。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里还有一点咖啡的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完蛋糕，我把残余放进冰箱。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在吃我们饭后的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一些纸的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用布的残余做了一个小包。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里有一些油的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙角堆着一些旧木头的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡以后，身上没有香皂的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些残余还能用吗？", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殘餘", "label": "繁体"}, {"form": "残余物", "label": "复合"}], "register": "书面", "sense_fingerprint": "用过、吃过之后剩下的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfc61dd-6a36-42c2-919d-a796ba291367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "残余", "is_correct": true, "explanation": "正确答案。残余（cán yú）指用过、吃过之后剩下的东西。"}, {"text": "残雨", "is_correct": false, "explanation": "残雨（cán yǔ）第二个音节声调不同（yǔ 第三声），意思是快停的雨，与残余无关。"}, {"text": "参与", "is_correct": false, "explanation": "参与（cān yù）两个音节的声调都与残余（cán yú）不同，意思是参加。"}, {"text": "藏于", "is_correct": false, "explanation": "藏于（cángyú）与 cányú 的韵母不同（-ang 与 -an），意思是隐藏在某处。"}], "explanations": {"残余": "正确答案。残余（cán yú）指用过、吃过之后剩下的东西。", "残雨": "残雨（cán yǔ）第二个音节声调不同（yǔ 第三声），意思是快停的雨，与残余无关。", "参与": "参与（cān yù）两个音节的声调都与残余（cán yú）不同，意思是参加。", "藏于": "藏于（cángyú）与 cányú 的韵母不同（-ang 与 -an），意思是隐藏在某处。"}, "sentence_index": null, "correct_answer": "残余"}, "level_3": {"options": [{"text": "残余", "is_correct": true, "explanation": "残余指用过、吃过之后剩下的东西，与“盘子里”“倒进了垃圾桶”相合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不可能在盘子里，也不会被倒进垃圾桶，句中语境不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是盘子里的东西，也不能倒进垃圾桶，句中语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“倒进”的对象应是可以盛倒的东西，“窗户”不能与“倒进”搭配。"}], "explanations": {"残余": "残余指用过、吃过之后剩下的东西，与“盘子里”“倒进了垃圾桶”相合。", "星星": "语义：星星不可能在盘子里，也不会被倒进垃圾桶，句中语境不合。", "歌曲": "语义：歌曲不是盘子里的东西，也不能倒进垃圾桶，句中语境不合。", "窗户": "搭配：“倒进”的对象应是可以盛倒的东西，“窗户”不能与“倒进”搭配。"}, "sentence_index": 0, "correct_answer": "残余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天残余三个小时看电视。", "explanation": "这里应该用〈花〉。残余是名词，不能当动词表示“花费”。"}, {"text": "他很残余，大家都不喜欢他。", "explanation": "残余是名词，不能用来形容人；这里应该用形容词，如〈自私〉。"}, {"text": "他残余地走进了房间。", "explanation": "残余是名词，不能加“地”作状语修饰动作；这里应该用〈悄悄〉之类的副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残余", "is_correct": true, "explanation": "残余指油被处理后剩下的部分，与“河水里有一些油的”相合。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：河水里不会有“油的诗歌”这样的东西，句中语境不合。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光不能沾油，也不能说“一些油的月光”，与河水的语境不合。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“一些油的”一般修饰残余、油滴等，“窗帘”与河水的语境不搭配。"}], "explanations": {"残余": "残余指油被处理后剩下的部分，与“河水里有一些油的”相合。", "诗歌": "语义：河水里不会有“油的诗歌”这样的东西，句中语境不合。", "月光": "语义：月光不能沾油，也不能说“一些油的月光”，与河水的语境不合。", "窗帘": "搭配：“一些油的”一般修饰残余、油滴等，“窗帘”与河水的语境不搭配。"}, "sentence_index": 6, "correct_answer": "残余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个残余的老师教得很好。", "explanation": "残余是名词，不能用来修饰指人的“老师”；这里应该用形容词，如〈优秀〉。"}, {"text": "我昨晚残余到十二点才睡。", "explanation": "这里应该用〈熬〉。残余是名词，不能当动词用。"}, {"text": "用十七除以五，商是三，残余了二。", "explanation": "这里应该用〈余〉。残余是名词，不能当动词用，除不尽的部分应说“余二”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把三个残余倒进了垃圾桶。", "corrected_sentence": "我把那些残余倒进了垃圾桶。", "error_description": "量词错误：残余是不可数的物质，不能用“三个”来数，应说“那些残余”或“一些残余”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "锅底还有一些残余们，用水冲掉就行。", "corrected_sentence": "锅底还有一些残余，用水冲掉就行。", "error_description": "后缀错误：“们”只用于指人的名词，残余是物质，不能加“们”，正确的说法是“一些残余”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "反义：理性与动物性相对，指理智而非本能。"}, {"text": "石头", "is_correct": false, "explanation": "石头是矿物，与动物性没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然景物，与动物性没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包是日常用品，与动物性没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "反义：理性与动物性相对，指理智而非本能。", "石头": "石头是矿物，与动物性没有反义关系。", "河流": "河流是自然景物，与动物性没有反义关系。", "书包": "书包是日常用品，与动物性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "反义：理性与动物性相对，指理智而非本能。"}, {"text": "房屋", "is_correct": false, "explanation": "房屋是建筑物，与动物性没有反义关系。"}, {"text": "大海", "is_correct": false, "explanation": "大海是自然景物，与动物性没有语义上的对立关系。"}, {"text": "黑板", "is_correct": false, "explanation": "黑板是教学用具，与动物性没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "反义：理性与动物性相对，指理智而非本能。", "房屋": "房屋是建筑物，与动物性没有反义关系。", "大海": "大海是自然景物，与动物性没有语义上的对立关系。", "黑板": "黑板是教学用具，与动物性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人和动物身体里像动物一样的本性，比如想吃饭、想玩。", "primary_collocate": null, "pronunciation": "dòng wù xìng", "ipa": "tʊŋ˥˩ u˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "想吃饭、想睡觉，都是动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子爱玩，这是动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人有动物性，也有想法。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看到好吃的，动物性就出来了。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物性让我们饿了就想吃饭。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人不能只有动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩游戏的时候，他的动物性很明显。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，想玩是孩子的动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累了就想睡觉，这是动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人和狗都有动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動物性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人和动物身体里像动物一样的本性，如想吃饭、想玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfc61dd-6a36-42c2-919d-a796ba291367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物性", "is_correct": true, "explanation": "动物性指人和动物本能的需求，如吃饭、睡觉，与句意相符。"}, {"text": "理性", "is_correct": false, "explanation": "语义：理性指理智思考，与“想吃饭、想睡觉”这类本能需求不符。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想指意识活动，不是“想吃饭、想睡觉”这类本能。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指外表长相，与“想吃饭、想睡觉”这类需求无关。"}], "explanations": {"动物性": "动物性指人和动物本能的需求，如吃饭、睡觉，与句意相符。", "理性": "语义：理性指理智思考，与“想吃饭、想睡觉”这类本能需求不符。", "思想": "语义：思想指意识活动，不是“想吃饭、想睡觉”这类本能。", "外貌": "体貌：外貌指外表长相，与“想吃饭、想睡觉”这类需求无关。"}, "sentence_index": 0, "correct_answer": "动物性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的动物性很喜欢读书，一见到书就想看。", "explanation": "这里应该用〈爱好〉。动物性指本能需求，不指读书之类的兴趣爱好，应说“爱好”。"}, {"text": "孩子很动物性。", "explanation": "这里应该用〈天真〉。动物性指本能需求，不用来形容人的性格。"}, {"text": "他的动物性很勤奋地学习。", "explanation": "这里应该用〈努力〉。动物性指本能，不能用来形容学习的勤奋态度，应说“努力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物性", "is_correct": true, "explanation": "动物性指本能冲动，玩游戏时表现出的冲动符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不能“很明显”地表现在玩游戏的行为中，与句意不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户与玩游戏时的表现无关，不能“很明显”。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：形状是外貌特征，不能用“很明显”来描述玩游戏时的行为。"}], "explanations": {"动物性": "动物性指本能冲动，玩游戏时表现出的冲动符合句意。", "数学": "语义：数学不能“很明显”地表现在玩游戏的行为中，与句意不符。", "窗户": "语义：窗户与玩游戏时的表现无关，不能“很明显”。", "形状": "搭配：形状是外貌特征，不能用“很明显”来描述玩游戏时的行为。"}, "sentence_index": 6, "correct_answer": "动物性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有丰富的动物性，所以写了很多论文。", "explanation": "这里应该用〈知识〉。动物性指本能，不指学问或知识，写论文靠的不是动物性。"}, {"text": "这个城市有悠久的动物性。", "explanation": "这里应该用〈文化〉。动物性不指历史传统，不能说“悠久”。"}, {"text": "他的动物性非常会讲故事。", "explanation": "这里应该用〈口才〉。动物性指本能，不指讲故事的能力，应说“口才好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "想玩是孩子动物性。", "corrected_sentence": "想玩是孩子的动物性。", "error_description": "错误：表示领属的名词修饰语“孩子”后漏掉了“的”。正确：应说“孩子的动物性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人有也动物性。", "corrected_sentence": "人也有动物性。", "error_description": "错误：副词“也”放错了位置。正确：应说“人也有动物性”，“也”放在主语后、动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "油和脂肪，可以吃，用来做菜不粘锅。", "primary_collocate": null, "pronunciation": "yóu zhī", "ipa": "joʊ˧˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "老式点心多用动物油脂，香味很浓。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "lǎo shì diǎn xin duō yòng dòng wù yóu zhī, xiāng wèi hěn nóng.", "sentence_source": "generated"}, {"text": "平底锅上涂一层油脂，蛋就不会粘底。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "píng dǐ guō shàng tú yì céng yóu zhī, dàn jiù bú huì zhān dǐ.", "sentence_source": "generated"}, {"text": "我们家做饭很少用动物油脂。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "wǒ men jiā zuò fàn hěn shǎo yòng dòng wù yóu zhī.", "sentence_source": "generated"}, {"text": "减肥的人要少吃油脂。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煎鱼用的油脂不能太少，否则鱼皮会粘锅。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "jiān yú yòng de yóu zhī bù néng tài shǎo, fǒu zé yú pí huì zhān guō.", "sentence_source": "generated"}, {"text": "这种食用油脂适合做中餐。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈先把锅烧热，再倒入一点食用油脂。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "mā ma xiān bǎ rè guō shāo rè, zài dào rù yì diǎn shí yòng yóu zhī.", "sentence_source": "generated"}, {"text": "蛋糕里加了黄油这种油脂，味道很香。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师说，做这道红烧肉要用不少动物油脂。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "chú shī shuō, zuò zhè dào hóng shāo ròu yào yòng bù shǎo dòng wù yóu zhī.", "sentence_source": "generated"}, {"text": "饭店的菜油脂太多，我吃不惯。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点油脂", "label": "量词"}, {"form": "食用油脂", "label": "复合"}], "register": "中性", "sense_fingerprint": "做菜用的食用油和脂肪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfc61dd-6a36-42c2-919d-a796ba291367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正确答案。油脂（yóu zhī）指油和脂肪，可以用来做菜。"}, {"text": "优质", "is_correct": false, "explanation": "优质（yōuzhì）两个音节的声调都不同，意思是质量好，与油脂（yóuzhī）声调不同。"}, {"text": "油纸", "is_correct": false, "explanation": "油纸（yóuzhǐ）第二个音节声调不同（zhǐ 第三声），意思是涂了油的纸。"}, {"text": "有志", "is_correct": false, "explanation": "有志（yǒuzhì）两个音节的声调都不同，意思是有志向。"}], "explanations": {"油脂": "正确答案。油脂（yóu zhī）指油和脂肪，可以用来做菜。", "优质": "优质（yōuzhì）两个音节的声调都不同，意思是质量好，与油脂（yóuzhī）声调不同。", "油纸": "油纸（yóuzhǐ）第二个音节声调不同（zhǐ 第三声），意思是涂了油的纸。", "有志": "有志（yǒuzhì）两个音节的声调都不同，意思是有志向。"}, "sentence_index": null, "correct_answer": "油脂"}, "level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "油脂指做点心用的食用油和脂肪，与“动物油脂”“香味很浓”相合。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是动物的产物，“动物木头”与句意不合，点心也不用木头做。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是动物的产物，点心里也不会用玻璃，句中语境不合。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：做点心的原料要能食用，“煤炭”不能与“做点心”搭配，香味也不合。"}], "explanations": {"油脂": "油脂指做点心用的食用油和脂肪，与“动物油脂”“香味很浓”相合。", "木头": "语义：木头不是动物的产物，“动物木头”与句意不合，点心也不用木头做。", "玻璃": "语义：玻璃不是动物的产物，点心里也不会用玻璃，句中语境不合。", "煤炭": "搭配：做点心的原料要能食用，“煤炭”不能与“做点心”搭配，香味也不合。"}, "sentence_index": 0, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆摩托车要加满油脂才能跑。", "explanation": "这里应该用〈汽油〉。油脂是食用的油和脂肪，给摩托车加的燃料要用汽油。"}, {"text": "我用油脂把信封粘好了。", "explanation": "这里应该用〈胶水〉。油脂是食用的油和脂肪，粘信封要用胶水。"}, {"text": "煤油炉要用油脂才能点着。", "explanation": "这里应该用〈煤油〉。煤油炉烧的是煤油，句中的油脂是可以吃的食用油脂，不能当炉子的燃料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "油脂指食用的油和脂肪，与“倒入一点食用”相合。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：油漆不能食用，“食用油漆”与热锅的语境不合。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不能食用，也不会倒进热锅里，句中语境不合。"}, {"text": "铁钉", "is_correct": false, "explanation": "搭配：“倒入一点”要求液体或颗粒，“铁钉”是固体，不能与“倒入”搭配。"}], "explanations": {"油脂": "油脂指食用的油和脂肪，与“倒入一点食用”相合。", "油漆": "语义：油漆不能食用，“食用油漆”与热锅的语境不合。", "肥皂": "语义：肥皂不能食用，也不会倒进热锅里，句中语境不合。", "铁钉": "搭配：“倒入一点”要求液体或颗粒，“铁钉”是固体，不能与“倒入”搭配。"}, "sentence_index": 6, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只油脂，准备炒菜。", "explanation": "量词错误：“只”多用于动物，油脂要用“点”或“勺”计量。"}, {"text": "我们正在给墙刷一层油脂，颜色很好看。", "explanation": "这里应该用〈油漆〉。油脂是可以吃的油和脂肪，刷墙要用油漆，不能用油脂。"}, {"text": "用油脂可以洗掉碗上的油污。", "explanation": "这里应该用〈洗洁精〉。油脂是可以吃的油和脂肪，本身就是油污的来源，洗掉碗上的油污要用洗洁精。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做这个菜要放一本油脂。", "corrected_sentence": "做这个菜要放一点油脂。", "error_description": "量词错误：“本”用于书，油脂是物质，应说“一点油脂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "锅里还剩一只油脂，别全倒掉。", "corrected_sentence": "锅里还剩一点油脂，别全倒掉。", "error_description": "量词错误：油脂是物质，不能用动物量词“只”计量，正确的说法是“一点油脂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
